        local p1 = Area.preview(AP, 90, 90, 94, 90, 0)
        local p2 = Area.preview(AP, 90, 90, 94, 90, 0)
        local W5 = withBox(ours(engineSq(91, 91, 0), wallS, {}))
        local p3 = Area.preview(AP, 90, 90, 94, 91, 0)
