        flags = { "collideW", "windowW", "transparentW", "cutW", "canPathW", "WindowW" },
        keys = { WindowLocked = "", WindowW = "WindowW" } })
    local framed2 = sprite("walls_fbwin_01_98", 9202, { type = T.wall, flags = { "collideW", "windowW", "cutW", "WindowW" },
