    local binds = { MinidoracatBuilder_LayerUp = 201, MinidoracatBuilder_LayerDown = 209 }
    local alts = {} -- 替代鍵：getKey 只回主鍵，isKey 兩個都認（Core.java:2405-2416）
    Keyboard = { KEY_PRIOR = 201, KEY_NEXT = 209 }
    getKeyName = function(k) return "K" .. k end
    getCore = function() return { getKey = function(_, name) return binds[name] or 0 end,
        isKey = function(_, name, k) return type(name) == "string" and (binds[name] == k or alts[name] == k) end } end
    check(Cursor.keyText("PgUp a PgDn") == "PgUp a PgDn", "換層鍵是預設：提示不動")
    binds.MinidoracatBuilder_LayerUp, binds.MinidoracatBuilder_LayerDown = 19, 0
    check(Cursor.keyText("PgUp a PgDn") == "K19 a -", "改了鍵：提示寫實際鍵名，沒綁寫「-」")
    local lc = setmetatable({ entry = { kind = "roof" }, up = false }, { __index = Cursor })
    lc:rotateKey(201)
    local stay = lc.up
    lc:rotateKey(19)
    check(stay == false and lc.up == true, "游標照綁的鍵換層：舊的 PgUp 不再有用，新鍵換到上一層")
    alts.MinidoracatBuilder_LayerDown = 33
    lc:rotateKey(33)
    check(lc.up == false, "替代鍵也換層（照 isKey 比，不是只比 getKey 的主鍵）")
    -- 2026-11-23 回饋：格邊種類（牆、窗框、門框、柵欄、門、窗、柱子）也能換層：換層鍵、手把 X、X 的提示都有；
    -- 家具、窗簾、牆面疊圖照舊不能
    local function layers(kind)
        local c = setmetatable({ entry = { kind = kind }, up = false }, { __index = Cursor })
        c:rotateKey(19)
        local byKey, prompt = c.up, c:getXPrompt()
        if not byKey then return false, prompt end
        c:onJoypadPressButton(0, nil, Joypad.XButton)
        return c.up == false, prompt
    end
    local realPad = Joypad
    Joypad = { XButton = 3 }
    local edgeOk, others = true, true
    for _, k in ipairs({ "wall", "windowFrame", "doorFrame", "fence", "door", "window", "post" }) do
        local ok, prompt = layers(k)
        edgeOk = edgeOk and ok and prompt == "IGUI_MBLD_PadLayerHere"
    end
    for _, k in ipairs({ "furniture", "curtain", "wallOverlay", "container" }) do
        local ok, prompt = layers(k)
        others = others and not ok and prompt == nil
    end
    -- 審查 1123 Codex：規劃模式接管樓層時（hook.layer 回數字）X 不能改一般游標的層，否則退出規劃後才生效
    local realLayer = Cursor.hook.layer
    local planned = setmetatable({ entry = { kind = "wall" }, up = false }, { __index = Cursor })
    Cursor.hook.layer = function() return 0 end
    planned:onJoypadPressButton(0, nil, Joypad.XButton)
    local held = planned.up == false and planned:getXPrompt() == nil
    Cursor.hook.layer = nil
    check(held and planned:getXPrompt() == "IGUI_MBLD_PadLayerUp",
        "規劃模式接管樓層時：手把 X 不換一般游標的層、不顯示換層提示；退出規劃後提示回來")
    Cursor.hook.layer = realLayer
    Joypad = realPad
    check(edgeOk and others, "格邊種類能換層（換層鍵換到上一層、手把 X 換回來、X 提示有字）；家具、窗簾、牆面疊圖、容器不能")
    getCore, getKeyName, Keyboard, KeybindId = realCore2, realKeyName, realKb, realKid
    sb.MaxCellsPerDrag = realMax
end)()

print("情境四十一：2026-11-07 Workshop 回饋：五個 tileset 的價錢、不能搬的燈收燈泡（燈泡還在才退）、牆型窗＝窗框＋窗")
