    check(not fits("wall", wallN, cell(393, 390, dirtN)), "有它：不是外邊的土牆照舊擋")
    check(not fits("wall", wallN, cell(394, 390, woodN, "N")), "有它、沒有它的牆表（aparosa_BD_Build 不在）：外邊上它的木牆照舊擋")
    check(not fits("doorFrame", tdoorN, cell(399, 390, dirtN, "N")),
