                        out[(g.x[i] - X) .. "," .. (g.y[i] - Y) .. "," .. g.z[i]] = { s = s, ta = g.ta[i], fa = g.fa[i],
                            tr = g.tr[i], fr = g.fr[i], m = g.m[i] }
                    end
                    return setmetatable(out, NONE), g.n, stair, cur
