    end
    local L = W.filter(st())
    check(L.n == 7 and L[1] == "rcp_walls_01_16" and L[2] == "rcp_chair_01_0" and L[3] == "recipe:Neat.Bench"
        and L[7] == "recipe:Base.WoodWall", "全部頁：圖塊在前，配方接在後面、照顯示名（使用者 2026-11-12）")
    local fu = W.filter(st({ tab = "furniture" }))
