    end
    world({ sp("pm_wall_01_0", 3101, { "WallW" }), sp("pm_wall_01_1", 3102, { "WallN" }), sp("pm_lone_01_0", 3103, { "WallW" }),
        sp("pm_floor_01_0", 3104, { "solidfloor" }), chairs[1], chairs[2], chairs[3], chairs[4] })
    local fakeCheck, resets = nil, 0
    B.PlanCheck = { reset = function() resets = resets + 1 end, state = function(p) return fakeCheck and fakeCheck(p) end }

    require "MinidoracatBuilder/PlanMode"
    require "MinidoracatBuilder/PlanGhost"
    local PM, PG = B.PlanMode, B.PlanGhost
    local function at(plan, x, y, z) return Plan.at(plan, x, y, z)[1] end
    local function sq(x, y, z) return { getX = function() return x end, getY = function() return y end, getZ = function() return z end } end

    -- 沒有藍圖：虛影第一行就離開（不問玩家、不畫）
    PG.draw()
    check(PM.state() == "none" and specCalls == 0 and ghostN == 0 and PG.lastDrawn == 0, "沒有藍圖：虛影不問玩家、不畫")

    -- 打開規劃：腳下建一張空的，掛上游標掛鉤
    check(PM.toggle(0) == true and PM.planning() and PM.state() == "edit" and Cur.hook.commit ~= nil and PM.level() == 0,
        "打開規劃：狀態 edit、游標掛鉤掛上、樓層是玩家那層")
    local ox, oy, oz = PM.origin()
    check(ox == 50 and oy == 50 and oz == 0, "空藍圖的原點在玩家腳下")
    local plan = PM.plan()
    local colors = { text = "T", warning = "W", textMuted = "M" }
    local function cursor(res, name)
        return setmetatable({ kx = 1, ky = 1, kz = 0, res = res, name = name or "pm_wall_01_1", character = P, colors = colors,
            lineX = 5, hint = "HINT" }, { __index = Cur })
    end
    local cur = cursor({ { a = { 52, 50, 0, 0 } }, { a = { 53, 50, 0, 0 }, code = "NO_MATERIAL" },
        { a = { 54, 50, 0, nil }, code = "NO_FACE" }, { a = { 55, 50, 0, 5 }, code = "BLOCKED" }, { a = { 56, 50, 0, 0, 3 } } })
    local lbl = Cur.hook.label(cur, { "L1", "T", "L2", "T", "HINT", "M" })
    check(lbl[3] == "IGUI_MBLD_PlanAdd(4)" and lbl[5] == "L2" and lbl[#lbl - 1] == "IGUI_MBLD_PlanHint" and lbl[#lbl] == "M"
        and Cur.hook.valid(cur) == true, "規劃中的標籤：插一行「放開會記 4 片」（沒有那一面的不算），按鍵說明換成規劃的")
    local commit = Cur.hook.commit
    cur:tryBuild(1, 1, 0)
    check(sent == 0 and plan.n == 4 and cur.lineX == nil, "規劃中放開：不送伺服器，缺料、被擋的照記，沒有那一面的不記")
    check(at(plan, 2, 0, 0).d == 0 and at(plan, 5, 0, 0).d == 5 and at(plan, 4, 0, 0) == nil and at(plan, 6, 0, 0).w == 3
        and plan.items[at(plan, 2, 0, 0).it].id == "pm_wall_01_1", "記進藍圖的片：相對原點、朝向、車庫門寬度照游標")
    cursor({ { a = { 52, 51, 0, 0 } }, { a = { 53, 51, 0, 0 } } }):tryBuild(1, 1, 0)
    check(plan.n == 6 and PM.undo() and plan.n == 4 and PM.undo() and plan.n == 0 and PM.redo() and plan.n == 4,
        "上一步：一次放開整步拿掉（兩次放開兩步），下一步拿回來")
    check(PM.redo() and plan.n == 6 and not PM.redo(), "下一步到底回 false")

    -- 上限：超出的那次放開不記、標籤寫原因
    local wide = cursor({ { a = { 50 + 70, 50, 0, 0 } } })
    local wl = Cur.hook.label(wide, { "L1", "T", "HINT", "M" })
    check(Cur.hook.valid(wide) == false and wl[3] == "IGUI_MBLD_PlanTooWide" and wl[4] == "W", "超出每邊 64 格：標籤寫原因、不可放")
    local before = #toasts
    wide:tryBuild(1, 1, 0)
    check(plan.n == 6 and sent == 0 and toasts[before + 1] == "IGUI_MBLD_PlanTooWide", "超出每邊 64 格：放開不記、跳原因")
    local high = cursor({ { a = { 52, 50, 4, 0 } } })
    Cur.hook.label(high, { "L1", "T" })
    check(Cur.hook.valid(high) == false and high.planWhy == "TOO_HIGH", "超出 4 層：TOO_HIGH")
    local full = Plan.new("full")
    local fi = Plan.item(full, "pm_floor_01_0")
    for y = 0, 63 do for x = 0, 63 do Plan.add(full, x, y, 0, 0, 0, fi) end end
    full.ox, full.oy, full.oz = 0, 0, 0
    check(PM.overflow(full, { { 5, 5, 0, 0 } }, "pm_floor_01_0", 0) == nil
        and PM.overflow(full, { { 5, 5, 0, 1 } }, "pm_floor_01_0", 0) == "FULL",
        "4,096 片：重複的片不算數，多一片新的 FULL")
    -- 朝向只有一種寫法：椅子自己那張圖朝南，游標轉一圈回到南（d＝3）和剛開的 0 是同一片
    local cf = Plan.new("cf")
    for y = 0, 63 do for x = 0, 63 do if x + y > 0 then Plan.add(cf, x, y, 0, 0, 0, Plan.item(cf, "pm_floor_01_0")) end end end
    Plan.add(cf, 0, 0, 0, 0, 0, Plan.item(cf, "pm_chair_01_0"))
    cf.ox, cf.oy, cf.oz = 0, 0, 0
    check(cf.n == 4096 and PM.overflow(cf, { { 0, 0, 0, 3 } }, "pm_chair_01_0", 0) == nil
        and PM.overflow(cf, { { 0, 0, 0, 4 } }, "pm_chair_01_0", 0) == "FULL",
        "朝向同一種寫法：轉一圈回到自己那張圖（d＝3）和 0 算同一片；別的朝向是新的一片")

    -- 配方游標交來的格子
    check(PM.addCells(0, "recipe:Base.Tarp", { { 51, 51, 0, 2 } }) == true and at(plan, 1, 1, 0).d == 2
        and plan.items[at(plan, 1, 1, 0).it].id == "recipe:Base.Tarp" and plan.n == 7, "配方的格子記進藍圖（面編號照收）")
    -- F9 挖地下室的三個項目不進藍圖：配方那條路回 DIG；建造游標標籤寫原因、不可放、放開不記也不送
    -- （藍圖檔讀檔、擷取、「把缺的換成…」在情境五十一之三）
    local nDig, tDig = plan.n, #toasts
    local okDig, whyDig = PM.addCells(0, Entry.DIG_CELL, { { 52, 52, -1, 0 } })
    local dc = cursor({ { a = { 52, 52, 0, 0 } } }, Entry.DIG_S)
    local dl = Cur.hook.label(dc, { "L1", "T" })
    local dcValid = Cur.hook.valid(dc)
    dc:tryBuild(1, 1, 0)
    check(okDig == nil and whyDig == "DIG" and dl[3] == "IGUI_MBLD_PlanNoDig" and dl[4] == "W" and dcValid == false
        and plan.n == nDig and sent == 0 and toasts[#toasts] == "IGUI_MBLD_PlanNoDig" and #toasts == tDig + 2,
        "F9 規劃不收挖掘項目：配方路徑回 DIG、游標標籤寫原因且不可放、放開不記不送（"
        .. tostring(whyDig) .. " " .. tostring(dl[3]) .. " n=" .. plan.n .. " toasts+" .. (#toasts - tDig) .. "）")

    -- 樓層：hook.layer 回規劃層和玩家那層的差，夾在藍圖 4 層的範圍內
    PM.setLevel(2)
    check(Cur.hook.layer(cur) == 2, "換到 3 樓規劃：游標往上 2 層")
    PM.setLevel(9)
    check(PM.level() == 3, "樓層夾在藍圖能到的 4 層內（全部片在 1 樓：最多到 4 樓）")
    PM.onKeyPressed(44)
    check(plan.n == 6, "Ctrl+Z（假綁定 44）：上一步")
    PM.onKeyPressed(21)
    check(plan.n == 7, "Ctrl+Y：下一步")
    PM.setLevel(0)

    -- 選取、擦：只算規劃那一層
    check(PM.selectRect(52, 50, 53, 51) == 4 and #PM.selected() == 4 and PM.isSelected(at(plan, 2, 0, 0)), "框選 2×2：選到 4 片")
    PM.setLevel(1)
    check(PM.selectRect(52, 50, 53, 51) == 0 and PM.selectRect(52, 50, 53, 51, true) == 4, "別層框不到；按住 Shift 全部樓層")
    PM.setLevel(0)
    check(PM.eraseRect(55, 50, 56, 50) == 2 and plan.n == 5 and #PM.selected() == 0, "擦：拿掉框到的片、清掉選取")
    PM.selectRect(52, 51, 53, 51)
    PM.onKeyPressed(211)
    check(plan.n == 3 and at(plan, 2, 1, 0) == nil, "Delete：刪掉選到的 2 片")

    -- 關掉規劃：存檔、記進這個存檔的地上藍圖，掛鉤拿掉
    check(PM.toggle(0) == true and PM.state() == "fixed" and Cur.hook.commit == nil, "關掉規劃：狀態 fixed、掛鉤拿掉")
    check(commit(cur) == false, "植入：規劃關掉後還留著的掛鉤也不收（回 false，游標照常送）")
    local file = "MinidoracatBuilder/plans/" .. plan.file
    local st = PS.load()
    check(disk[file] ~= nil and st.file == plan.file and st.ox == 51 and st.oy == 50 and st.oz == 0,
        "存檔：藍圖檔寫進磁碟；位置記包圍盒的角（51, 50, 0）")

    -- 重新載入（模組重跑＝遊戲重開）：讀回原處
    local function reload()
        loadfile(MEDIA .. "/client/MinidoracatBuilder/PlanMode.lua")()
        PM = B.PlanMode
    end
    reload()
    check(PM.plan() == nil and PM.restore() == true and PM.state() == "fixed", "重新載入：讀回地上的藍圖")
    plan = PM.plan()
    ox, oy, oz = PM.origin()
    local w1 = at(plan, 52 - ox, 50 - oy, 0)
    check(ox == 51 and oy == 50 and w1 and w1.d == 0 and plan.items[w1.it].id == "pm_wall_01_1"
        and at(plan, 51 - ox, 51 - oy, 0) ~= nil, "重新載入：每片在世界上的位置不變")
    -- 這張藍圖在磁碟上的每個檔（正式檔與存檔時另寫的副本）一起換掉；回原本的內容
    local function swapFiles(path, text)
        local stem, old = (path:gsub("%.txt$", "")), {}
        for k, v in pairs(disk) do if k:sub(1, #stem + 1) == stem .. "." then old[k] = v end end
        for k in pairs(old) do disk[k] = text end
        return old
    end
    local function putBack(old) for k, v in pairs(old) do disk[k] = v end end
    local good = swapFiles(file, "壞掉的內容\n")
    reload()
    before = #toasts
    local fine, res = pcall(PM.restore)
    check(fine and res == false and PM.plan() == nil and toasts[before + 1] == "IGUI_MBLD_PlanLost" and PS.load().file == nil,
        "壞檔：不丟錯、通知一次、地上的藍圖記錄清掉")
    putBack(good)
    PS.save(st)
    reload()
    check(PM.restore() == true, "檔案修好、記錄寫回：照常讀回（對照組）")
    plan = PM.plan()

    -- 搬：跟著游標、取消回原位置；放回原位置
    check(PM.pickUp(0) == true and PM.state() == "place" and PM.origin() == nil and drags[0] ~= nil, "搬：整張跟著游標，原點暫時沒有")
    local o = drags[0]
    o:isValid(sq(80, 80, 0))
    o:rotateKey(19)
    check(PM.drag(0) == o and PM.drag(1) == nil, "搬：拖曳物件查得到（只有拿著的那位玩家）")
    MinidoracatBuilder.Cursor.onRightMouseUp() -- 右鍵：不是建造游標也要取消（關掉拖曳物件 → deactivate）
    check(drags[0] == nil and PM.drag(0) == nil, "右鍵：藍圖的搬／擺放也取消")
    ox, oy = PM.origin()
    check(PM.state() == "fixed" and ox == 51 and oy == 50 and at(plan, 52 - 51, 0, 0) and at(plan, 1, 0, 0).d == 0,
        "搬到一半取消：轉過的撤回，回原位置")
    PM.pickUp(0)
    check(PM.home() ~= nil and PM.placeHome() == true and select(1, PM.origin()) == 51 and PM.state() == "fixed", "放回原位置")

    -- 審查 1116 第 1 輪 C5：包圍盒的角變了以後按「存檔」或「隱藏」再重進，每片還在原處（藍圖檔與位置一起存）
    local function worldSig()
        local out, ox2, oy2, oz2 = {}, PM.origin()
        Plan.each(PM.plan(), function(p) out[#out + 1] = (p.x + ox2) .. "," .. (p.y + oy2) .. "," .. (p.z + oz2) .. "," .. p.d end)
        table.sort(out)
        return table.concat(out, "|")
    end
    local function quit() -- 沒按完成就離開遊戲：拿掉舊模組掛的游標掛鉤，重新載入再讀回
        for _, k in ipairs({ "valid", "commit", "label", "tint", "layer" }) do Cur.hook[k] = nil end
        reload()
        return PM.restore()
    end
    local paused
    B.Runner = { pause = function(r) paused = r end }
    PM.toggle(0)
    check(paused == "EDIT" and PM.planning(), "C8：進入規劃前先暫停照圖蓋（原因 EDIT）")
    PM.eraseRect(51, 51, 51, 51)
    local want = worldSig()
    check(PM.save() == true and quit() == true and worldSig() == want, "C5：角變了以後按存檔，重進每片仍在原處")
    -- 第 2 輪 PM6：按隱藏只改記錄的 hidden，不重寫藍圖檔
    PM.toggle(0)
    PM.eraseRect(52, 50, 52, 50)
    want = worldSig()
    local planPath = "MinidoracatBuilder/plans/" .. PM.plan().file
    local fileBefore = disk[planPath]
    PM.setHidden(true)
    check(disk[planPath] == fileBefore and PS.load().hidden == true, "PM6：按隱藏只改記錄，不重寫藍圖檔")
    check(PM.save() == true and quit() == true and worldSig() == want and PM.hidden() == true,
        "C5：角變了以後存檔，重進每片仍在原處、照樣隱藏")
    PM.setHidden(false)

    -- 第 2 輪 PM5：藍圖檔一時打不開（在資料夾裡、讀不到）保留記錄、下次再讀；正式檔與備份都不在資料夾裡才當成刪掉
    plan = PM.plan()
    local pfile = "MinidoracatBuilder/plans/" .. plan.file
    local pback = (pfile:gsub("%.txt$", ".cfg"))
    locked[pfile], locked[pback] = true, true
    before = #toasts
    check(quit() == false and toasts[before + 1] == "IGUI_MBLD_PlanUnread" and PS.load().file == plan.file,
        "打不開的藍圖檔：記錄留著、說下次再讀")
    PM.toggle(0)
    check(PM.stopEdit() == true and PM.state() == "none" and PS.load().file == plan.file,
        "PM5：保留記錄時開規劃又關掉（空白的丟掉），記錄還在")
    locked[pfile], locked[pback] = nil, nil
    local oldName = plan.file
    local moved = PF.rename(oldName, "Kept")
    check(moved ~= nil and PM.retarget(oldName, moved, "Kept") == true and PS.load().file == moved,
        "PM5：保留記錄、地上沒有藍圖時藍圖庫改名，記錄跟著指向新檔名")
    check(quit() == true and PM.plan().file == moved, "檔案打得開了：下次照常讀回（改名後的檔）")
    plan = PM.plan()
    local stKeep = PS.load()
    local gone = swapFiles("MinidoracatBuilder/plans/" .. plan.file, nil)
    before = #toasts
    check(quit() == false and toasts[before + 1] == "IGUI_MBLD_PlanLost" and PS.load().file == nil
        and quit() == false and #toasts == before + 1, "PM5：正式檔與備份都不在資料夾裡＝刪掉了：清記錄、只說一次")
    putBack(gone)
    PS.save(stKeep)
    check(quit() == true, "檔案與記錄放回：照常讀回（對照組）")
    plan = PM.plan()

    -- C2：存檔失敗時不離開規劃、不收起
    PM.toggle(0)
    PM.addCells(0, "recipe:Base.Tarp", { { 54, 50, 0, 2 } })
    failWrite = true
    before = #toasts
    local ok2, why2 = PM.stopEdit()
    check(ok2 == false and why2 ~= nil and PM.planning() and Cur.hook.commit ~= nil and toasts[before + 1] == "IGUI_MBLD_PlanSaveFail",
        "C2：完成時存檔失敗：留在規劃、掛鉤還在、通知")
    check(PM.clear() == false and PM.plan() == plan and plan.n == 2 and PM.planning(), "C2：收起時存檔失敗：藍圖留著、什麼都不動")
    failWrite = false

    -- C10：搬、複製中按旋轉只轉預覽；取消時原片不動，複製放下時只轉新的那份，算一步
    local function wallAt(x, y)
        local wx, wy = PM.origin()
        for _, p in ipairs(Plan.at(plan, x - wx, y - wy, 0)) do if plan.items[p.it].id == "pm_wall_01_1" then return p end end
        return nil
    end
    check(select(2, PM.blank(0)) == "BUSY" and PM.planning() and PM.plan() == plan, "blank：規劃中也回 BUSY、不動")
    local n0 = plan.n
    PM.selectRect(53, 50, 54, 50)
    PM.moveSel(true)
    o = drags[0]
    o:isValid(sq(60, 50, 0))
    o:rotateKey(19)
    getCell():setDrag(nil, 0)
    check(plan.n == n0 and wallAt(53, 50) and wallAt(53, 50).d == 0, "C10：複製中轉了再取消：原片沒轉、沒多片")
    PM.moveSel(true)
    o = drags[0]
    o:isValid(sq(60, 50, 0))
    o:rotateKey(19)
    o:tryBuild(60, 50, 0)
    local copyWall = wallAt(61, 50)
    check(plan.n == n0 + 2 and wallAt(53, 50) and wallAt(53, 50).d == 0 and copyWall and copyWall.d == 5 and PM.isSelected(copyWall),
        "C10：複製轉 90 度放下：原片不動，新的那份轉了（北牆→右邊那格的西牆）")
    check(PM.undo() and plan.n == n0 and wallAt(53, 50).d == 0, "C10：複製加旋轉算一步，上一步一次拿掉")
    -- 第 2 輪 PM4：照預覽的最終位置一次放下（中間位置不去重）
    local function wallD(x, y, d)
        local wx, wy = PM.origin()
        for _, p in ipairs(Plan.at(plan, x - wx, y - wy, 0)) do
            if plan.items[p.it].id == "pm_wall_01_1" and p.d == d then return p end
        end
        return nil
    end
    PM.addCells(0, "pm_wall_01_1", { { 63, 50, 0, 0 } })
    PM.selectRect(53, 50, 53, 50)
    PM.moveSel(false)
    o = drags[0]
    o:isValid(sq(63, 50, 0))
    o:rotateKey(19)
    o:tryBuild(63, 50, 0)
    check(plan.n == n0 + 1 and wallD(63, 50, 0) and wallD(64, 50, 5) and not wallD(53, 50, 0),
        "PM4：搬 10 格再轉，中間位置疊到沒選的同款牆：兩片都在，搬的那片在預覽的位置")
    check(PM.undo() and plan.n == n0 + 1 and wallD(53, 50, 0) and wallD(63, 50, 0) and not wallD(64, 50, 5),
        "PM4：搬加轉，上一步一次回到原樣")
    PM.selectRect(53, 50, 53, 50)
    PM.moveSel(true)
    o = drags[0]
    o:isValid(sq(53, 50, 0))
    o:rotateKey(19)
    o:tryBuild(53, 50, 0)
    check(plan.n == n0 + 2 and wallD(53, 50, 0) and wallD(54, 50, 5), "PM4：原地轉 90 度複製：新的那片照預覽加上，不漏片")
    PM.undo()
    PM.undo()
    check(plan.n == n0, "上一步拿掉複製與加的牆")
    -- 2026-11-24 回饋 G：複製中按住左鍵拖排成一列（原版按住期間每幀 rotateMouse(滑鼠那格)，o.square 停在按下那格）
    do
        local wx = PM.origin()
        PM.addCells(0, "pm_wall_01_1", { { 56, 56, 0, 0 }, { 57, 56, 0, 0 } })
        local nRow = plan.n
        local function press(x, y)
            PM.selectRect(56, 56, 57, 56)
            PM.moveSel(true)
            local d = drags[0]
            d:isValid(sq(56, 56, 0))
            d.square, d.isLeftDown = sq(56, 56, 0), true
            if x then d:rotateMouse(x, y) end
            return d
        end
        local d = press(nil, nil)
        check(#PM.selected() == 2 and d.lines[2] == "IGUI_MBLD_PlanCopyDragHint", "G：鍵鼠、1 份：第二行提示可以按住拖")
        d:rotateMouse(61, 57)
        check(d.reps == 3 and d.sx == 2 and d.sy == 0 and d.lines[2] == "IGUI_MBLD_PlanCopyRow(3,6)",
            "G：往東拖 5 格（橫的比縱的多）：走 x 軸、間距是寬 2、3 份，提示換成份數與片數")
        d:rotateMouse(57, 59)
        check(d.reps == 4 and d.sx == 0 and d.sy == 1, "G：往南拖 3 格：走 y 軸、間距是深 1、4 份")
        d:rotateMouse(52, 56)
        for k in pairs(ghostAt) do ghostAt[k] = nil end
        PG.draw()
        check(d.reps == 3 and d.sx == -2 and ghostAt["52,56,0"] and ghostAt["53,56,0"] and ghostAt["54,56,0"],
            "G：往西拖 4 格：往負的方向排 3 份，虛影每份都畫")
        d:rotateMouse(61, 57)
        d.isLeftDown = false
        d:tryBuild(56, 56, 0)
        check(plan.n == nRow + 4 and wallD(58, 56, 0) and wallD(61, 56, 0) and #PM.selected() == 4 and PM.isSelected(wallD(60, 56, 0)),
            "G：在原地按下拖 3 份放開：第 0 份和原片重疊略過，其餘 4 片加上、選取換成新片")
        check(PM.undo() and plan.n == nRow, "G：拖出來的 3 份算一步，上一步一次清光")

        d = press(61, 56)
        d.isLeftDown = false
        d:isValid(sq(40, 40, 0))
        check((d.reps or 1) == 1 and d.lines[2] == "IGUI_MBLD_PlanCopyDragHint", "G：放開但沒放下（例如在介面上），游標跟著滑鼠走時份數回 1")
        getCell():setDrag(nil, 0)

        d = press(56 + 200, 56)
        local x0, _, _, x1 = Plan.bounds(plan)
        local lo, far = math.min(x0, 56 - wx), 57 - wx + (d.reps - 1) * 2
        check(d.reps > 1 and math.max(x1, far) - lo < 64 and math.max(x1, far + 2) - lo >= 64,
            "G：拖過 64 格：夾到每邊 64 格放得下的最多份（" .. tostring(d.reps) .. "）")
        local reps, said = d.reps, #toasts
        d.isLeftDown = false
        d:tryBuild(56, 56, 0)
        check(#toasts == said and plan.n == nRow + (reps - 1) * 2, "G：夾過的份數放下一定成功，不跳上限提示")
        PM.undo()

        local keep = Plan.MAX_PIECES
        Plan.MAX_PIECES = plan.n + 5
        d = press(66, 56)
        Plan.MAX_PIECES = keep
        check(d.reps == 3, "G：片數上限：剩 5 片、每份 2 片，在原位按下（第 0 份不佔額度）夾到 3 份")
        getCell():setDrag(nil, 0)

        -- 審查 1124 Codex 第 6 條：在原位按下時第 0 份疊在原片上、放下會略過，不算進片數額度；上限還生效時放下
        Plan.MAX_PIECES = plan.n + 2
        d = press(58, 56)
        local cap = d.reps
        d.isLeftDown = false
        d:tryBuild(56, 56, 0)
        local full = plan.n == Plan.MAX_PIECES and wallD(58, 56, 0) and wallD(59, 56, 0)
        Plan.MAX_PIECES = keep
        check(cap == 2 and full, "G：剩 2 片、在原位按下拖一個間距：第 0 份不佔額度，排 2 份、放下剛好到上限（" .. tostring(cap) .. "）")
        check(PM.undo() and plan.n == nRow, "G：到上限的那一排一次上一步拿掉")

        -- 審查 1124 Codex 第 7 條：拖排中轉了直接放開（中間沒有 rotateMouse），放下照轉過的尺寸重排
        d = press(60, 56)
        d:rotateKey(19)
        check(d.reps == 5 and d.sx == 1 and d.sy == 0,
            "G：拖 4 格（間距 2、3 份）時轉 90 度：兩片橫排變直的，照同一個位移馬上重排成間距 1、5 份（" .. tostring(d.reps) .. "）")
        d.isLeftDown = false
        d:tryBuild(56, 56, 0)
        check(plan.n == nRow + 10 and PM.undo() and plan.n == nRow, "G：轉完直接放開：放下 5 份 10 片，和預覽同一組，一步拿掉")

        -- 審查 1124 第 2 輪：額度看第 0 份會不會真的被略過，不看有沒有轉過。有方向的牆轉了就不在原位，照舊計入
        Plan.MAX_PIECES = plan.n + 2
        d = press(nil, nil)
        d:rotateKey(19)
        d:rotateMouse(57, 56)
        Plan.MAX_PIECES = keep
        check((d.reps or 1) == 1, "G：剩 2 片、兩片牆轉了往東拖一格：第 0 份換了方向要新增，夾到 1 份（" .. tostring(d.reps) .. "）")
        getCell():setDrag(nil, 0)
        local fx, fy = PM.origin()
        PM.addCells(0, "pm_floor_01_0", { { 56, 63, 0, 0 } })
        local nF, fl = plan.n, Plan.at(plan, 56 - fx, 63 - fy, 0)[1]
        local function pressFloor()
            PM.selectRect(56, 63, 56, 63)
            PM.moveSel(true)
            local f = drags[0]
            f:isValid(sq(56, 63, 0))
            f.square, f.isLeftDown = sq(56, 63, 0), true
            f:rotateKey(19)
            return f
        end
        Plan.MAX_PIECES = nF + 1
        d = pressFloor()
        d:rotateMouse(57, 63)
        local fr = d.reps
        d.isLeftDown = false
        d:tryBuild(56, 63, 0)
        Plan.MAX_PIECES = keep
        check(fr == 2 and plan.n == nF + 1 and #Plan.at(plan, 57 - fx, 63 - fy, 0) == 1,
            "G：剩 1 片、無方向地板轉了還疊在原片上，往東拖一格：第 0 份不佔額度，排 2 份、新增 1 片（" .. tostring(fr) .. "）")
        check(PM.undo() and plan.n == nF, "G：那一片一次上一步拿掉")
        d = pressFloor()
        d.isLeftDown = false
        d:tryBuild(56, 63, 0)
        check(plan.n == nF and #PM.selected() == 1 and PM.isSelected(fl), "G：轉了也和原片一樣、一片都沒加：選取留著原片")
        PM.undo()

        -- 審查 1124 Codex 第 2 條：間距量實際佔地。三格寬的車庫門（北向沿 +x、西向沿 −y，Entry.groupCells）緊貼著拖不重疊
        local E = B.Entry
        local resolve0, face0, doorSet0 = E.resolve, E.face, E.doorSet
        local gN, gW = E.sprite("pm_wall_01_1"), E.sprite("pm_wall_01_0")
        local gd = { kind = "door", name = "pm_gd", spr = gN }
        E.resolve = function(id) if id == "pm_gd" then return gd end return resolve0(id) end
        E.face = function(e, f) if e == gd then return f == 5 and gW or gN end return face0(e, f) end
        E.doorSet = function(s)
            if s == gN or s == gW then return { garage = true, north = s == gN, parts = { s, s, s } } end
            return doorSet0(s)
        end
        local function gate(x, y, f)
            local gx, gy = PM.origin()
            for _, p in ipairs(Plan.at(plan, x - gx, y - gy, 0)) do
                if plan.items[p.it].id == "pm_gd" and p.d == f then return p end
            end
            return nil
        end
        local function gateRow(x, y, f, mx, my)
            PM.addCells(0, "pm_gd", { { x, y, 0, f, 3 } })
            local n1 = plan.n
            PM.selectRect(x, y, x, y)
            PM.moveSel(true)
            local g = drags[0]
            g:isValid(sq(x, y, 0))
            g.square, g.isLeftDown = sq(x, y, 0), true
            g:rotateMouse(mx, my)
            local reps, sx, sy = g.reps, g.sx, g.sy
            g.isLeftDown = false
            g:tryBuild(x, y, 0)
            return reps, sx, sy, plan.n - n1
        end
        local r1, s1, _, a1 = gateRow(56, 59, 0, 62, 59)
        local northOk = r1 == 3 and s1 == 3 and a1 == 2 and gate(59, 59, 0) and gate(62, 59, 0) and not gate(57, 59, 0)
        local r2, _, s2, a2 = gateRow(62, 62, 5, 62, 68)
        local westOk = r2 == 3 and s2 == 3 and a2 == 2 and gate(62, 65, 5) and gate(62, 68, 5) and not gate(62, 63, 5)
        E.resolve, E.face, E.doorSet = resolve0, face0, doorSet0
        check(northOk, "G：北向三格車庫門往東拖 6 格：間距 3、3 份，相鄰兩扇不重疊（" .. tostring(r1) .. "×" .. tostring(s1) .. "）")
        check(westOk, "G：西向三格車庫門往南拖 6 格：間距 3、3 份，相鄰兩扇不重疊（" .. tostring(r2) .. "×" .. tostring(s2) .. "）")
        for _ = 1, 4 do PM.undo() end
        check(plan.n == nRow, "G：上一步拿掉兩排車庫門與兩扇原門")

        JoypadState.players[1] = {}
        d = press(61, 56)
        check(d.joypad and (d.reps or 1) == 1 and #d.lines == 1, "G：手把：份數恆為 1、沒有按住拖的提示")
        getCell():setDrag(nil, 0)
        JoypadState.players[1] = nil
        PM.undo()
        check(plan.n == nRow - 2, "上一步拿掉 G 加的兩片牆")
    end
    check(PM.stopEdit() == true and PM.state() == "fixed", "對照：寫得進去就照常結束規劃")

    -- C3／K1：藍圖庫改名、刪除後地上那張跟著改；刪掉後存檔另取檔名，不蓋掉舊檔名
    local f0 = plan.file
    check(PM.retarget("nope.txt", "x.txt", "X") == false and plan.file == f0, "retarget：不是地上那張就不動")
    check(PM.retarget(f0, "cabin.txt", "Cabin") == true and plan.file == "cabin.txt" and plan.name == "Cabin"
        and PS.load().file == "cabin.txt", "retarget：改名後地上那張與記錄都換成新檔名")
    check(PM.retarget("cabin.txt", nil) == true and plan.file == nil and PS.load().file == nil, "retarget：刪除後解除連結、記錄清掉")
    disk["MinidoracatBuilder/plans/cabin.txt"] = "NEWPLAN\n" -- 這個檔名已經給了別張
    check(PM.save() == true and disk["MinidoracatBuilder/plans/cabin.txt"] == "NEWPLAN\n" and plan.file ~= nil
        and plan.file ~= "cabin.txt" and PS.load().file == plan.file, "刪除後按存檔：另取檔名，舊檔名那張沒被蓋掉")

    -- 同一個檔的另一份（重新匯入或讀回、換過圖）擺到地上：取代地上那張、位置不動，之後存的是新內容
    local again = PF.load(plan.file)
    local ax0, ay0 = Plan.bounds(again)
    Plan.add(again, ax0, ay0, 0, 0, 0, Plan.item(again, "pm_floor_01_0"))
    local function wallIn(pl2, x, y)
        local gx, gy = PM.origin()
        for _, p in ipairs(Plan.at(pl2, x - gx, y - gy, 0)) do if pl2.items[p.it].id == "pm_wall_01_1" then return p end end
        return nil
    end
    check(PM.place(again, 0) == true and PM.plan() == again and PM.state() == "place" and PM.placeHome() == true
        and wallIn(again, 53, 50) ~= nil, "同一個檔的新一份擺到地上：取代地上那張，放回原位置時每片位置不變")
    check(PM.save() == true and PF.load(again.file).n == plan.n + 1, "之後存檔寫的是新的那份（多一片地板），不是地上的舊內容")
    plan = again

    -- 地上已經有一張，沒有框架時不換、說一聲
    before = #toasts
    check(PM.place(Plan.new("別張"), 0) == false and PM.plan() == plan and toasts[before + 1] == "IGUI_MBLD_NeedFramework",
        "地上已經有藍圖、沒有框架：不換、通知")
    check(PM.clear() == true and PM.state() == "none" and PS.load().file == nil, "收起：地上沒有藍圖、記錄清掉")
    check(PM.blank(0) == true and PM.planning() and PM.plan().n == 0 and PM.plan() ~= plan, "blank：沒有藍圖時建一張空白的並開始規劃")
    check(PM.stopEdit() == true and PM.state() == "none", "空白的沒畫就結束：直接丟掉")

    -- 1118：規劃可以取消（存過的回到上次存檔的樣子與位置、沒存過的整張丟掉）；unsaved；另存新檔（finishAs）；詢問的接線
    do
        local function wx() -- 地上那張每片的世界 x
            local out, gx = {}, PM.origin()
            Plan.each(PM.plan(), function(p) out[#out + 1] = p.x + gx end)
            table.sort(out)
            return table.concat(out, ",")
        end
        local cp = Plan.new("Cancel")
        local cf = Plan.item(cp, "pm_floor_01_0")
        Plan.add(cp, 0, 0, 0, 0, 0, cf)
        Plan.add(cp, 1, 0, 0, 0, 0, cf)
        local realWin = B.Window.close
        local closed = 0
        B.Window.close = function() closed = closed + 1 end
        PM.place(cp, 0)
        B.Window.close = realWin
        drags[0]:isValid(sq(200, 50, 0))
        drags[0]:tryBuild(200, 50, 0)
        check(closed == 1, "從藍圖庫擺（beginPlace）：建造工坊視窗收起")
        local cfile = PM.plan().file
        local path = "MinidoracatBuilder/plans/" .. cfile
        local saved = disk[path]
        check(wx() == "200,201" and PM.unsaved() == false and PM.cancelEdit() == false,
            "✗ 不在規劃：cancelEdit 回 false、unsaved 是 false")
        PM.toggle(0)
        check(PM.unsaved() == false, "unsaved：剛進規劃、還沒改是 false")
        PM.eraseRect(200, 50, 200, 50) -- 擦掉最西邊一排：包圍盒的角變了
        PM.addCells(0, "pm_floor_01_0", { { 203, 50, 0, 0 } })
        check(PM.unsaved() == true and wx() == "201,203", "unsaved：規劃中改了是 true")
        check(PM.cancelEdit() == true and not PM.planning() and PM.state() == "fixed" and wx() == "200,201"
            and disk[path] == saved and PS.load().file == cfile and Cur.hook.commit == nil,
            "取消：片與位置回到上次存檔（擦掉最西邊一排、包圍盒變了也一樣），檔與記錄沒動、離開規劃")
        check(quit() == true and wx() == "200,201", "取消後重進：仍是存檔的樣子與位置")
        PM.setHidden(true)
        PM.toggle(0) -- 進規劃會先顯示出來；取消後要照記錄回到隱藏，不必等重進
        PM.addCells(0, "pm_floor_01_0", { { 205, 50, 0, 0 } })
        check(PM.hidden() == false and PM.cancelEdit() == true and PM.hidden() == true and PS.load().hidden == true,
            "取消：規劃前是隱藏的，取消後照記錄仍是隱藏")
        PM.setHidden(false)
        PM.toggle(0)
        PM.addCells(0, "pm_floor_01_0", { { 202, 50, 0, 0 } })
        check(PM.save() == true and PM.unsaved() == false and PM.planning(), "unsaved：存檔後是 false（留在規劃）")
        saved = disk[path]
        PM.addCells(0, "pm_floor_01_0", { { 204, 50, 0, 0 } })
        local back = (path:gsub("%.txt$", ".cfg"))
        locked[path], locked[back] = true, true
        before = #toasts
        local okL = PM.cancelEdit()
        locked[path], locked[back] = nil, nil
        check(okL == false and PM.planning() and wx() == "200,201,202,204" and toasts[before + 1] == "IGUI_MBLD_PlanCancelFail",
            "取消時讀不回上次存的：留在規劃、改動還在、說一聲")
        fail = { pat = "plans/" }
        local okX = PM.finishAs("Third")
        fail = nil
        check(okX ~= true and PM.planning() and PM.plan().file == cfile and PM.plan().name == "Cancel" and disk[path] == saved,
            "finishAs 寫不進：留在規劃，檔名與名稱改回去，原本的檔沒動")
        local okF = PM.finishAs("Cancel Copy")
        local nf = PM.plan().file
        check(okF == true and nf ~= cfile and PM.plan().name == "Cancel Copy" and PS.load().file == nf and disk[path] == saved
            and PF.load(nf).n == 4 and PF.load(cfile).n == 3 and not PM.planning(),
            "finishAs：另存成新檔、原本的檔不變、記錄指向新檔、離開規劃")
        PM.toggle(0)
        PM.addCells(0, "pm_floor_01_0", { { 206, 50, 0, 0 } })
        check(PM.saveAs("Cancel Third") == true and PM.planning() and PM.plan().file ~= nf and PF.load(nf).n == 4
            and PM.unsaved() == false, "saveAs：另存成新檔、留在規劃、原本的檔不變")
        PM.addCells(0, "pm_floor_01_0", { { 207, 50, 0, 0 } })
        -- 詢問的接線：換成假藍圖庫，記下開了什麼框
        local realL, asked, conf = B.PlanLibrary, nil, nil
        B.PlanLibrary = { askOverwrite = function(_, o) asked = o; return true end, confirm = function(_, o) conf = o; return o end }
        local f3 = PM.plan().file
        local okA, whyA = PM.askSave()
        check(okA == true and whyA == "ASKED" and asked and asked.name == "Cancel Third" and PM.unsaved(),
            "askSave：有沒存的改動先問覆蓋或另存，還沒存")
        asked.onOverwrite()
        check(PM.unsaved() == false and PM.planning() and PM.plan().file == f3, "askSave 覆蓋：存回同一個檔、留在規劃")
        asked = nil
        local okN = PM.askFinish()
        check(okN == true and asked == nil and not PM.planning(), "askFinish：沒有沒存的改動直接完成、不問")
        PM.toggle(0)
        PM.addCells(0, "pm_floor_01_0", { { 208, 50, 0, 0 } })
        PM.askFinish()
        check(asked ~= nil and PM.planning(), "askFinish：有沒存的改動先問、還在規劃")
        asked.onNew("Cancel Four")
        check(not PM.planning() and PM.plan().name == "Cancel Four" and PM.plan().file ~= f3 and PF.load(f3).n == 6,
            "askFinish 另存：存成新的一張、原本的檔不變")
        PM.toggle(0)
        check(PM.askCancel() == true and conf == nil and not PM.planning(), "askCancel：沒改過直接取消、不問")
        PM.toggle(0)
        PM.addCells(0, "pm_floor_01_0", { { 209, 50, 0, 0 } })
        check(PM.askCancel() == true and conf and conf.danger and conf.text == "IGUI_MBLD_PlanDiscardText" and PM.planning(),
            "askCancel：有沒存的改動先確認（危險樣式），還在規劃")
        conf.onYes()
        check(not PM.planning() and PM.plan().n == 7, "askCancel 按放棄改動：回到上次存檔的樣子")
        B.PlanLibrary = { askOverwrite = function() return nil end }
        PM.toggle(0)
        PM.addCells(0, "pm_floor_01_0", { { 209, 50, 0, 0 } })
        check(PM.askCancel() == false and PM.planning() and PM.plan().n == 8, "✗ 沒有確認框：askCancel 不丟改動")
        check(PM.askFinish() == true and not PM.planning() and PF.load(PM.plan().file).n == 8,
            "✗ 沒有三選一的框：askFinish 照舊覆蓋原本的")
        -- 審查 1118：三選一與另存的名稱框不擋畫面，按下去時已經離開規劃（取消了）就不做；離開規劃時關掉三選一
        do
            local shut = 0
            B.PlanLibrary = { askOverwrite = function(_, o) asked = o; return true end, confirm = function(_, o) conf = o; return o end,
                closeChooser = function() shut = shut + 1 end }
            PM.toggle(0)
            PM.addCells(0, "pm_floor_01_0", { { 210, 50, 0, 0 } })
            local keepFile, keepName = PM.plan().file, PM.plan().name
            asked = nil
            PM.askSave()
            local stale = asked
            check(stale ~= nil and PM.cancelEdit() == true and shut >= 1, "離開規劃（取消）：關掉還開著的三選一")
            local nFiles = 0
            for p in pairs(disk) do if p:find("plans/", 1, true) then nFiles = nFiles + 1 end end
            local okS = stale.onNew("Stale Copy")
            local okO = stale.onOverwrite()
            local nAfter = 0
            for p in pairs(disk) do if p:find("plans/", 1, true) then nAfter = nAfter + 1 end end
            check(okS == false and okO == false and nAfter == nFiles and PM.plan().file == keepFile and PM.plan().name == keepName
                and PS.load().file == keepFile, "✗ 取消之後才按舊框的另存新檔／覆蓋：不存、地上那張與記錄不變")
            check(PM.saveAs("Not Editing") == false and PM.plan().file == keepFile, "✗ 不在規劃：saveAs 不做")
            -- 擦光之後另存：沒有東西可以存成新的一張（三選一不給「另存新檔」，程式介面回 EMPTY）
            PM.toggle(0)
            local gx, gy = PM.origin()
            PM.eraseRect(gx - 5, gy - 5, gx + 30, gy + 5)
            asked = nil
            PM.askFinish()
            local okE1, whyE1 = PM.finishAs("Empty Copy")
            local okE2 = PM.saveAs("Empty Copy")
            check(PM.plan().n == 0 and asked and asked.onNew == nil and asked.onOverwrite ~= nil and okE1 == false and whyE1 == "EMPTY"
                and okE2 == false and PM.planning() and PM.plan().file == keepFile and PM.plan().name == keepName,
                "✗ 整張擦光了：三選一沒有另存新檔，finishAs／saveAs 不存、留在規劃")
            check(PM.cancelEdit() == true and PM.plan().n > 0, "（收尾）取消：擦掉的回來")
            -- 第二條審查線：另存時同名的原檔一時打不開（在資料夾裡、讀不到）。不能當成刪掉的檔名重用：
            -- 重用的話這次另存寫進原檔，原檔與備份都被蓋掉。讀得到刪除標記才重用（空的、打不開的都不算）
            do
                PM.toggle(0)
                PM.addCells(0, "pm_floor_01_0", { { 212, 50, 0, 0 } })
                local kp = "MinidoracatBuilder/plans/" .. keepFile
                local kb = (kp:gsub("%.txt$", ".cfg"))
                local wasMain, wasBack = disk[kp], disk[kb]
                locked[kp], locked[kb] = true, true
                local okL2 = PM.saveAs(keepName)
                locked[kp], locked[kb] = nil, nil
                local nf2 = PM.plan().file
                check(wasMain ~= nil and disk[kp] == wasMain and disk[kb] == wasBack,
                    "✗ 另存、同名的原檔一時打不開：原檔與備份沒被蓋掉")
                check(okL2 == true and nf2 ~= keepFile and PF.load(nf2).n == PM.plan().n and PF.load(keepFile).n == PM.plan().n - 1,
                    "✗ 另存、同名的原檔一時打不開：存成另一個檔名，原檔還是另存前的內容 " .. tostring(nf2))
                disk["MinidoracatBuilder/plans/Void.txt"] = ""
                check(PF.fileName("Void") == "Void2.txt", "✗ 空的檔、沒有備份（不知道是什麼）：檔名不重用 " .. tostring(PF.fileName("Void")))
                disk["MinidoracatBuilder/plans/Void.txt"] = nil
                -- 複審：只剩備份檔（第一次存、正式檔還沒建立就斷掉）。那個名稱不算沒人用：拿來存會把唯一完整的一份蓋掉
                local lone = "MinidoracatBuilder/plans/Lone.cfg"
                disk[lone] = wasMain
                local okL3 = PM.saveAs("Lone")
                check(okL3 == true and PM.plan().file == "Lone2.txt" and disk[lone] == wasMain,
                    "✗ 另存、同名的只剩備份檔：存成另一個檔名，備份沒被蓋掉 " .. tostring(PM.plan().file))
                disk[lone] = nil
                -- 複審第二次：正式檔是刪除標記、備份檔卻是別的內容（刪掉後又存同名、正式檔還沒寫就斷掉）。
                -- 備份是那張唯一完整的一份：檔名不重用。兩個都是刪除標記、或沒有備份檔才重用
                local tp, tb = "MinidoracatBuilder/plans/Tomb.txt", "MinidoracatBuilder/plans/Tomb.cfg"
                disk[tp], disk[tb] = wasMain, wasMain
                local okT = PF.remove("Tomb.txt")
                local tomb = disk[tp]
                check(okT == true and tomb ~= wasMain and disk[tb] == tomb and PF.fileName("Tomb") == "Tomb.txt",
                    "反面：正式檔與備份檔都是刪除標記：檔名照舊重用")
                disk[tb] = wasMain
                check(PF.fileName("Tomb") == "Tomb2.txt" and disk[tb] == wasMain,
                    "✗ 正式檔是刪除標記、備份檔是別的內容：檔名不重用 " .. tostring(PF.fileName("Tomb")))
                locked[tb] = true
                check(PF.fileName("Tomb") == "Tomb2.txt", "✗ 正式檔是刪除標記、備份檔一時打不開：檔名不重用")
                locked[tb] = nil
                disk[tb] = nil
                check(PF.fileName("Tomb") == "Tomb.txt", "反面：正式檔是刪除標記、沒有備份檔：重用")
                -- 複審第三次：資料夾列不出來（引擎回空清單）但照檔名開得到。清單沒列備份不代表沒有備份：照樣開來看
                disk[tb] = wasMain
                local realList = listFilesInZomboidLuaDirectory
                listFilesInZomboidLuaDirectory = function() return javaList({}) end
                local nameT = PF.fileName("Tomb")
                local okT2 = PM.saveAs("Tomb")
                listFilesInZomboidLuaDirectory = realList
                check(nameT ~= "Tomb.txt" and disk[tb] == wasMain and disk[tp] == tomb and PM.plan().file ~= "Tomb.txt",
                    "✗ 資料夾列不出來、正式檔是刪除標記、備份檔是別的內容：另存不蓋掉備份 " .. tostring(nameT) .. " " .. tostring(okT2) .. " " .. tostring(PM.plan().file))
                disk[tb] = nil
                disk[tp] = nil
            end
            B.PlanLibrary = { askOverwrite = function() return nil end }
        end
        check(PM.clear() == true and PM.blank(0) == true, "（準備）收起，開一張空白的")
        PM.addCells(0, "pm_floor_01_0", { { 50, 60, 0, 0 } })
        conf = nil
        B.PlanLibrary = { confirm = function(_, o) conf = o; return o end }
        PM.askCancel()
        check(conf and conf.text == "IGUI_MBLD_PlanDiscardNew", "askCancel：沒存過的那張說整張都會不見")
        local recBefore = PS.load().file
        conf.onYes()
        check(PM.state() == "none" and PM.plan() == nil and PS.load().file == recBefore, "取消沒存過的：整張丟掉、記錄不動")
        B.PlanLibrary = realL
    end

    -- ===== 審查第 2 輪：改名（PM3）、兩段式存檔（PM2）、搬之前先存（PM1）、同一個檔的另一份（PM8） =====
    local two = Plan.new("Two")
    local tf = Plan.item(two, "pm_floor_01_0")
    Plan.add(two, 0, 0, 0, 0, 0, tf)
    Plan.add(two, 1, 0, 0, 0, 0, tf)
    local function settleAt(pl, x)
        PM.place(pl, 0)
        drags[0]:isValid(sq(x, 50, 0))
        drags[0]:tryBuild(x, 50, 0)
    end
    settleAt(two, 100)
    local function xs() -- 地上那張每片的世界 x
        local out, gx = {}, PM.origin()
        Plan.each(PM.plan(), function(p) out[#out + 1] = p.x + gx end)
        table.sort(out)
        return table.concat(out, ",")
    end
    check(xs() == "100,101" and PS.load().file == two.file, "第 2 輪：兩片定在 100、101，記錄指著這張")
    local function editLeft() -- 規劃中刪掉左片：包圍盒的角從 100 變 101
        PM.toggle(0)
        PM.eraseRect(100, 50, 100, 50)
    end
    editLeft()
    local f1 = two.file
    local f2 = PF.rename(f1, "Twin")
    check(f2 ~= nil and PM.retarget(f1, f2, "Twin") == true and quit() == true and xs() == "100,101",
        "PM3：規劃中刪掉左片、沒完成就改名，重進兩片仍在 100、101（照磁碟上那份）")

    editLeft()
    fail = { pat = "worlds/" }
    local ok3 = PM.save()
    fail = nil
    check(ok3 == nil and quit() == true and xs() == "100,101", "PM2：只有 worlds 寫不進：重進是舊的那一版（100、101），不是混的")
    editLeft()
    fail = { pat = "plans/" }
    ok3 = PM.save()
    fail = nil
    check(ok3 == nil and PS.load().px == 100 and quit() == true and xs() == "100,101",
        "PM2：只有藍圖檔寫不進：記錄已是新的角，讀回照藍圖檔的 pos 認出上一版，仍在 100、101")
    editLeft()
    crash = { after = "worlds/.*%.txt$" }
    PM.save()
    crash = nil
    local sig = (quit() == true) and xs() or "-"
    check(sig == "100,101" or sig == "101", "PM2：記錄寫好、藍圖檔還沒寫就當掉：重進是完整的一版（" .. sig .. "）")
    editLeft()
    check(PM.save() == true and quit() == true and xs() == "101", "對照：兩邊都寫得進去，重進是新的那一版（只剩 101）")
    PM.pickUp(0)
    fail = { pat = "worlds/" }
    local okC, whyC = PM.clear()
    fail = nil
    drags[0] = nil -- 離開遊戲：跟著游標的那個不會被取消
    check(okC == false and whyC == "STORE" and PM.plan() ~= nil and quit() == true and xs() == "101",
        "PM2：收起時 worlds 寫不進：回 false、藍圖還在，重進仍在原處")

    local realUi, shown = B.Window.ui, 0
    B.Window.ui = function(need) -- 只給確認框；工具列照沒有框架時不出（不在這裡測）
        if not (need and need[1] == "dialog") then return nil end
        return { Dialog = { show = function(d) shown = shown + 1; d.onResult(true) end },
            Theme = { create = function() return {} end } }
    end
    PM.toggle(0)
    PM.addCells(0, "pm_floor_01_0", { { 102, 50, 0, 0 } })
    local cur2 = PM.plan()
    local other = Plan.new("Other")
    Plan.add(other, 0, 0, 0, 0, 0, Plan.item(other, "pm_floor_01_0"))
    check(PM.pickUp(0) == true and PM.state() == "place" and PM.place(other, 0) == true and shown == 1 and PM.plan() == other
        and PF.load(cur2.file).n == 2, "PM1：規劃中改了按「搬」再換一張：搬之前已存，換掉後檔裡有改動")
    getCell():setDrag(nil, 0)
    settleAt(PF.load(cur2.file), 101)
    PM.toggle(0)
    PM.addCells(0, "pm_floor_01_0", { { 103, 50, 0, 0 } })
    failWrite = true
    local okP, whyP = PM.pickUp(0)
    failWrite = false
    check(okP == false and whyP ~= nil and PM.planning() and PM.plan().n == 3, "PM1：搬之前存不了：留在規劃、改動還在記憶體")
    PM.stopEdit()

    local file2 = PM.plan().file
    local newer = PF.load(file2)
    local nx0, ny0 = Plan.bounds(newer)
    Plan.add(newer, nx0, ny0, 0, 0, 0, Plan.item(newer, "pm_wall_01_1"))
    PF.save(newer, file2) -- 藍圖庫「存進藍圖庫」寫到同一個檔
    check(PM.adopt ~= nil and PM.adopt(newer) == true and PM.plan() == newer and PM.state() == "fixed"
        and xs() == "101,101,102,103", "PM8：定住時 adopt：換成新的這份、位置不動、不拿起來")
    check(PM.save() == true and PF.load(file2).n == 4 and quit() == true and xs() == "101,101,102,103",
        "PM8：adopt 之後存檔，檔案內容是新的那一份")
    newer = PM.plan()
    PM.toggle(0)
    local okA, whyA = PM.adopt(PF.load(file2))
    check(okA == false and whyA == "EDITING" and PM.plan() == newer, "PM8：規劃中 adopt：不換、回 EDITING")
    PM.addCells(0, "pm_floor_01_0", { { 104, 50, 0, 0 } })
    local dup = PF.load(file2)
    shown = 0
    check(PM.place(dup, 0) == true and shown == 1 and PM.plan() == dup and dup.file == nil and PM.state() == "place"
        and PF.load(file2).n == 5, "PM8：規劃中擺同一個檔的另一份：先問、存檔收起地上那張（改動有存），新的這份當成另一張")
    getCell():setDrag(nil, 0)
    B.Window.ui = realUi

    -- 從藍圖庫擺：轉 90 度（北牆換成右邊那格的西牆；沒有另一面的照原朝向），點一下定位
    local np = Plan.new("小屋")
    local fl, wn, lone = Plan.item(np, "pm_floor_01_0"), Plan.item(np, "pm_wall_01_1"), Plan.item(np, "pm_lone_01_0")
    Plan.add(np, 0, 0, 0, 0, 0, fl)
    Plan.add(np, 1, 0, 0, 0, 0, fl)
    Plan.add(np, 0, 0, 0, 0, 0, wn)
    Plan.add(np, 2, 0, 0, 0, 0, lone)
    check(PM.place(np, 0) == true and PM.state() == "place" and PM.home() == nil, "擺放：沒有原位置的不給「放回原位置」")
    o = drags[0]
    o:isValid(sq(70, 70, 0))
    check(o.ox == 69 and o.oy == 70 and o.oz == 0, "跟著游標：藍圖中心對準滑鼠那格")
    before = #toasts
    o:rotateKey(19)
    check(toasts[before + 1] == "IGUI_MBLD_PlanStuck(1)", "轉 90 度：沒有另一面的牆朝向不變、說一聲")
    o:tryBuild(70, 70, 0)
    ox, oy, oz = PM.origin()
    local fA, fB = at(np, 0, 0, 0), at(np, 0, 1, 0)
    local wall = nil
    for _, p in ipairs(Plan.at(np, 1, 0, 0)) do if np.items[p.it].id == "pm_wall_01_1" then wall = p end end
    check(PM.state() == "fixed" and ox == 70 and oy == 69 and oz == 0, "點一下定位：原點照轉過的包圍盒對準滑鼠")
    check(fA and fB and wall and wall.d == 5 and at(np, 0, 2, 0) and at(np, 0, 2, 0).d == 0,
        "轉 90 度：橫的兩格地板變直的，左格北邊的牆到右邊那格的西邊（配對面 d＝5）")
    check(disk["MinidoracatBuilder/plans/" .. tostring(np.file)] ~= nil and PS.load().file == np.file, "定位後存檔並記進地上藍圖")
    check(PM.turnPiece({ d = 5 }, { id = "pm_wall_01_1" }) == 0 and select(2, PM.turnPiece({ d = 5 }, { id = "pm_wall_01_1" })) == 0
        and select(2, PM.turnPiece({ d = 0 }, { id = "pm_wall_01_1" })) == 1, "轉向：西牆轉北牆不移格；北牆轉東邊移到右邊那格")
    local cd = { PM.turnPiece({ d = 0 }, { id = "pm_chair_01_0" }) }
    local c2 = PM.turnPiece({ d = cd[1] }, { id = "pm_chair_01_0" })
    local c3 = PM.turnPiece({ d = c2 }, { id = "pm_chair_01_0" })
    local c4 = PM.turnPiece({ d = c3 }, { id = "pm_chair_01_0" })
    check(cd[1] == 4 and c2 == 1 and c3 == 2 and c4 == 0, "轉向：四面家具南→西→北→東，轉四次回到 0（和原來一模一樣）")
    B.Recipes = { faces = function() return { n = 2, 1, 3 } end }
    check(PM.turnPiece({ d = 1 }, { id = "recipe:x" }) == 3 and PM.turnPiece({ d = 3 }, { id = "recipe:x" }) == 1
        and PM.turnPiece({ d = 2 }, { id = "recipe:x" }) == nil, "配方片照 Recipes.faces 循環；沒有的面回 nil")
    B.Recipes = { faces = function() return nil end }

    -- 虛影：一幀最多 512 片、近的先；完成的不畫；隱藏時只畫閃的
    PM.clear()
    local big = Plan.new("大")
    local bf = Plan.item(big, "pm_floor_01_0")
    for y = 0, 63 do for x = 0, 63 do Plan.add(big, x, y, 0, 0, 0, bf) end end
    PM.place(big, 0)
    drags[0]:isValid(sq(50, 50, 0))
    drags[0]:tryBuild(50, 50, 0)
    ghostN, ghostAt = 0, {}
    PG.draw()
    check(PG.lastDrawn == 512 and ghostN == 512 and ghostAt["50,50,0"], "4,096 片：一幀只畫 512 片，玩家腳下那片有畫")
    PG.DRAW_MAX = 10
    PG.draw()
    check(PG.lastDrawn == 10, "植入：上限改 10 就只畫 10 片（上限確實在管）")
    PG.DRAW_MAX = 512
    fakeCheck = function(p) return p.x + big.ox == 50 and p.y + big.oy == 50 and "done" or nil end
    ghostN, ghostAt = 0, {}
    PG.draw()
    check(not ghostAt["50,50,0"] and ghostAt["51,50,0"] and PG.lastDrawn == 512, "蓋好的片（done）不畫，換下一片補上")
    fakeCheck = nil
    PM.setHidden(true)
    ghostN = 0
    PG.draw()
    check(ghostN == 0 and PS.load().hidden == true, "隱藏：不畫，記進存檔")
    PG.flash(at(big, 0, 0, 0))
    PG.flash(at(big, 1, 0, 0))
    PG.draw()
    check(ghostN == 2 and PG.lastDrawn == 2, "隱藏時「在哪」照閃：一秒內叫的片一起閃")
    PM.setHidden(false)

    -- 2026-11-21 回饋 F5f：圖塊照原色畫（看得出材質），能蓋、缺料、被擋只染地框；選到的整片染選取色、地框淡一點
    local function rgba(t, r, g, b, a)
        return t ~= nil and math.abs(t[1] - r) < 1e-6 and math.abs(t[2] - g) < 1e-6 and math.abs(t[3] - b) < 1e-6
            and math.abs(t[4] - a) < 1e-6
    end
    fakeCheck = function(p)
        if p.y + big.oy ~= 50 then return nil end
        local x = p.x + big.ox
        return x == 51 and "short" or x == 52 and "blocked" or nil
    end
    tint.tile, tint.floor = {}, {}
    PG.draw()
    local tt, ft = tint.tile, tint.floor
    check(rgba(tt["50,50,0"], 1, 1, 1, 0.5) and rgba(tt["51,50,0"], 1, 1, 1, 0.5) and rgba(tt["52,50,0"], 1, 1, 1, 0.5),
        "虛影：能蓋、缺料、被擋的片圖塊都照原色畫（不再整片染紫，看得出是哪種材質）")
    check(rgba(ft["50,50,0"], 0.75, 0.6, 1, 0.5) and rgba(ft["51,50,0"], 1, 0.8, 0.3, 0.5)
        and rgba(ft["52,50,0"], 0.95, 0.35, 0.35, 0.5), "虛影：狀態改染地框（能蓋紫、缺料黃、被擋紅），還分得出哪片有問題")
    fakeCheck = nil
    PM.toggle(0)
    tint.tile, tint.floor = {}, {}
    check(PM.selectRect(53, 50, 53, 50) == 1, "規劃中框選一片（對照組）")
    PG.draw()
    check(rgba(tint.tile["53,50,0"], 0.4, 0.9, 1, 0.5) and rgba(tint.floor["53,50,0"], 0.4, 0.9, 1, 0.3)
        and rgba(tint.tile["54,50,0"], 1, 1, 1, 0.5), "虛影：選到的片圖塊與地框都染選取色（地框淡一點），沒選到的照原色")
    PM.toggle(0)

    -- F5a：擺放中畫整張的外框：照包圍盒（多格家具伸出去的格子也算）、跟著游標、轉向後寬深對調、放下就沒有
    PM.clear()
    local bed0 = ghostly(sprite("pm_bed_01_0", 3130, { keys = { IsMoveAble = "" } }))
    local bed1 = ghostly(sprite("pm_bed_01_1", 3131, { keys = { IsMoveAble = "" } }))
    fakeGrid(2, 1, { { bed0, bed1 } })
    spriteMap[bed0.name], spriteMap[bed1.name] = bed0, bed1
    spriteOrder[#spriteOrder + 1], spriteOrder[#spriteOrder + 2] = bed0, bed1
    local ob = Plan.new("框")
    local obf = Plan.item(ob, "pm_floor_01_0")
    Plan.add(ob, 0, 0, 0, 0, 0, obf)
    Plan.add(ob, 1, 0, 0, 0, 0, obf)
    Plan.add(ob, 2, 1, 0, 0, 0, Plan.item(ob, "pm_bed_01_0"))
    local function box()
        local b = PG.outline()
        return b and table.concat({ b[1], b[2], b[3], b[4], b[5] }, ",")
    end
    PM.place(ob, 0)
    drags[0]:isValid(sq(60, 60, 0))
    local lines2, realScr = 0, { x = isoToScreenX, y = isoToScreenY, font = UIFont, tm = getTextManager }
    ISUIElement = { derive = function(self) return setmetatable({}, { __index = self }) end,
        new = function(cls) return setmetatable({}, { __index = cls }) end, initialise = function() end,
        addToUIManager = function() end, backMost = function() end,
        drawLine2 = function() lines2 = lines2 + 1 end, drawText = function() end, drawRect = function() end }
    isoToScreenX = function(_, x, y) return (x - y) * 32 end
    isoToScreenY = function(_, x, y, z) return (x + y) * 16 - z * 96 end
    UIFont = UIFont or { Small = 1 }
    getTextManager = function()
        return { getFontHeight = function() return 14 end, MeasureStringX = function(_, _, s) return #s end }
    end
    PG.draw()
    check(box() == "59,60,63,62,0", "擺放外框：照整張的包圍盒（床伸出去那格也算），格子邊界、跟著游標")
    local ov = PG.overlay()
    ov:render()
    check(lines2 == 8, "擺放外框：畫在世界上（四條邊各畫兩次，2 px 粗）")
    drags[0]:tryBuild(60, 60, 0)
    PG.draw()
    ov:render()
    check(PM.state() == "fixed" and box() == nil and lines2 == 8, "點一下定位後外框就沒有、不再畫")
    PM.clear()
    local strip = Plan.new("條")
    local sf = Plan.item(strip, "pm_floor_01_0")
    for x = 0, 2 do Plan.add(strip, x, 0, 0, 0, 0, sf) end
    PM.place(strip, 0)
    drags[0]:isValid(sq(60, 60, 0))
    PG.draw()
    local b1 = { PG.outline()[1], PG.outline()[2], PG.outline()[3], PG.outline()[4] }
    drags[0]:rotateKey(19)
    PG.draw()
    local b2 = PG.outline()
    check(b1[3] - b1[1] == 3 and b1[4] - b1[2] == 1 and b2 and b2[3] - b2[1] == 1 and b2[4] - b2[2] == 3,
        "擺放外框：轉 90 度後跟著轉（3×1 變 1×3）")
    -- 審查 #14：轉是繞包圍盒的角，轉完不動滑鼠也要照滑鼠那格重新對齊（外框和放下的位置跟移一下滑鼠一樣）
    local turnedAt, b2s = { drags[0].ox, drags[0].oy }, table.concat(b2, ",", 1, 4)
    PM.dragMoved(drags[0], 60, 60, 0)
    PG.draw()
    check(drags[0].ox == turnedAt[1] and drags[0].oy == turnedAt[2] and table.concat(PG.outline(), ",", 1, 4) == b2s,
        "擺放轉 90 度、滑鼠不動：原點與外框已照滑鼠那格對齊（和移一下滑鼠的結果一樣）")
    drags[0]:tryBuild(60, 60, 0)
    -- 審查 #6：配方片的虛影只畫第一格，外框照那一面整塊（真的 Recipes.span）；span 丟錯時 log 一次、退回錨點那格。
    -- 配方資料用假的 BuildEntity info（面 1＝西 3×1、面 2＝北 1×3，照 Recipes 的 FACE_OF 對到 getFace(1)、getFace(0)）
    PM.clear()
    local realR, realPrint, spanLogs = B.Recipes, print, 0
    local RR = real.recipes -- 情境開頭換成假的之前的真模組
    local RID = "recipe:Base.HarnessBench"
    local keepList, keepBy = RR.list, RR.byId
    local function face(w, h) -- 格子沒有圖（TileInfo 回 nil）：虛影照樣畫不出，外框只靠 span
        return { getWidth = function() return w end, getHeight = function() return h end, getTileInfo = function() return nil end }
    end
    local FACES = { [1] = face(3, 1), [0] = face(1, 3) }
