    do -- 匯入結果：四種狀態的片數
        local pl = sample("Four")
        local s = L.summary(pl.items)
        check(s.n == 10 and s.ok == 3 and s.missing == 2 and s.off == 1 and s.closed == 4, "四種狀態：能蓋 3、缺 2、關掉 1、不開放 4")
        check(#s.mods == 1 and s.mods[1].workshop == "123" and s.mods[1].n == 2, "缺的照 MOD 分組：名稱、工作坊 ID、片數")
        local ws = false
        for _, ln in ipairs(L.describe(s, true)) do if ln.ws == "123" then ws = true end end
        check(ws, "沒啟用的 MOD 那行附工作坊 ID（給「開工作坊頁」）")
        setStates({ off_01_0 = "off", shut_01_0 = "closed" })
        local s2 = L.summary(pl.items)
        check(s2.missing == 0 and s2.ok == 5 and #s2.mods == 0, "反面：MOD 回來後缺的變能蓋")
        setStates(BAD)
    end

    do -- 把缺的換成這裡有的
        local pl, _, b, _, d = sample("Swap")
        local n = L.swap(pl, b, "fresh_01_0")
        local s = L.summary(pl.items)
        check(n == 2 and s.missing == 0 and s.ok == 5 and s.n == 10, "換掉缺的一款：2 片改成能蓋，總數不變")
        states.shut2_01_0 = "closed"
        local n2, err = L.swap(pl, d, "shut2_01_0")
        check(n2 == nil and err == "IGUI_MBLD_Imp_SwapBad" and pl.items[d].n == 4, "反面：換成這裡也不能蓋的：不換、說原因")
        check(L.guessKind("walls_exterior_01_0") == "wall" and L.guessKind("fixtures_doors_01_0") == "door"
            and L.guessKind("x_01_0") == "furniture", "換項目：照圖塊名猜種類")
        setStates(BAD)
    end

    do -- 刪除要確認
        wipePlans()
        local pl = sample("Gone")
        local file = L.store(pl)
        dialogs = {}
        local done
        local d = L.askRemove(file, pl.name, pl.n, 0, function(ok) done = ok end)
        check(file == "Gone.txt" and d ~= nil and d.danger == true and has(PF.list(), file), "刪除：先跳危險確認框，還沒刪")
        d.onResult(false)
        check(has(PF.list(), file) and done == nil, "反面：按取消不刪")
        L.askRemove(file, pl.name, pl.n, 0, function(ok) done = ok end)
        dialogs[#dialogs].onResult(true)
        check(not has(PF.list(), file) and done == true, "按確認才刪")
    end

    local USED = "MinidoracatBuilder/plans-used.txt"
    local function three()
        wipePlans()
        local function mk(name, n)
            local pl = Plan.new(name)
            local it = Plan.item(pl, "okay_01_0")
            for i = 1, n do Plan.add(pl, i, 0, 0, 0, 0, it) end
            PF.save(pl, PF.fileName(name))
        end
        mk("Bravo", 1)
        mk("Alpha", 3)
        mk("Charlie", 2)
        disk[USED] = "Alpha.txt\t100\nCharlie.txt\t300\n#end\n"
    end
    local function order(sort)
        L.st.sort = sort
        local t = {}
        for i, e in ipairs(L.view()) do t[i] = e.file end
        return table.concat(t, ",")
    end

    do -- 三種排序、搜尋
        three()
        check(L.open(0) and L.visible(), "藍圖庫：打得開")
        while L.pending() > 0 do L.pump(1000) end
        check(order("used") == "Charlie.txt,Alpha.txt,Bravo.txt", "排序：最近用過（沒用過的排後面）")
        check(order("name") == "Alpha.txt,Bravo.txt,Charlie.txt", "排序：名稱")
        check(order("pieces") == "Alpha.txt,Charlie.txt,Bravo.txt", "排序：片數多的在前")
        L.st.query = "char"
        check(order("name") == "Charlie.txt", "搜尋：名稱不分大小寫")
        L.st.query = ""
        disk[USED] = "Alpha.txt\t100\nCharlie.txt\t300\n"
        check(L.loadUsed() == true and order("used") == "Charlie.txt,Alpha.txt,Bravo.txt" and L.markUsed("Bravo.txt", nil) == true
            and disk[USED]:find("#end\n$") ~= nil and disk[USED]:find("Alpha.txt\t100\n", 1, true) ~= nil
            and disk[USED]:find("Charlie.txt\t300\n", 1, true) ~= nil, "少了 #end 的紀錄：收讀得出來的行，下次寫入補齊")
        local rd = getFileReader
        getFileReader = function() return nil end
        local before = disk[USED]
        check(L.loadUsed() == false and L.markUsed("Alpha.txt", nil) == false and disk[USED] == before,
            "反面：讀不到紀錄檔時不載入也不覆寫")
        getFileReader = rd
        L.loadUsed()
        -- 檔名照藍圖名稱取之後（2026-11-18）：檔名有大寫、空白、括號、中文
        local odd = Plan.new("Zulu")
        Plan.add(odd, 0, 0, 0, 0, 0, Plan.item(odd, "okay_01_0"))
        PF.save(odd, "House (v2).txt")
        L.scan()
        while L.pending() > 0 do L.pump(1000) end
        L.st.query = "house"
        check(order("name") == "House (v2).txt", "搜尋：照檔名找也不分大小寫（檔名保留大小寫）")
        L.st.query = ""
        disk[USED] = "House (v2).txt\t500\n海邊 小屋.txt\t400\n../x.txt\t900\na\tb.txt\t7\n#end\n"
        check(L.loadUsed() == true and L.usedAt("House (v2).txt") == 500 and L.usedAt("海邊 小屋.txt") == 400
            and L.usedAt("../x.txt") == nil and L.usedAt("a\tb.txt") == nil,
            "最近用過：檔名有空白、括號、中文的時間讀得回來；不合檔名規則的行不收")
        PF.remove("House (v2).txt")
        three()
        L.loadUsed()
        local list = {}
        for i = 1, 2000 do list[i] = 2001 - i end
        L.sort(list, function(a, b) return a < b end)
        local sorted = true
        for i = 1, 2000 do if list[i] ~= i then sorted = false end end
        check(sorted, "合併排序：2,000 筆倒序排對（不遞迴）")
    end

    do -- 改名更新清單、用過的時間跟著搬
        three()
        L.open(0)
        while L.pending() > 0 do L.pump(1000) end
        L.markUsed("Bravo.txt", nil)
        local nf = L.rename("Bravo.txt", "Delta")
        L.v:reload(nf)
        while L.pending() > 0 do L.pump(1000) end
        L.v:refreshRows()
        local shown = false
        for _, row in ipairs(L.v.list.items) do
            if row.e.file == "Delta.txt" and row.cells[1] == "Delta" then shown = true end
        end
        check(nf == "Delta.txt" and shown and L.st.byFile["Bravo.txt"] == nil and L.v.selected == L.st.byFile["Delta.txt"],
            "改名：清單換成新名稱與檔名、選著它")
        check(L.usedAt("Delta.txt") ~= nil and L.usedAt("Bravo.txt") == nil, "改名：上次用的時間搬到新檔名")
        dialogs = {}
        L.v:act("delete")
        dialogs[#dialogs].onResult(true)
        check(L.st.byFile["Delta.txt"] == nil and #L.v.list.items == 2 and L.usedAt("Delta.txt") == nil, "清單上刪除：確認後清單少一列")
    end

    do -- 1,000 個檔：打開時不讀檔頭，之後每幀最多 HEAD_MAX 個
        wipePlans()
        local text = PF.encode((sample("Many")))
        for i = 1, 1000 do disk["MinidoracatBuilder/plans/m" .. i .. ".txt"] = text end
        local heads = 0
        PF.head = function(f)
            heads = heads + 1
            return real.head(f)
        end
        L.open(0)
        check(heads == 0 and #L.st.files == 1000 and #L.v.list.items == 1000, "1,000 個檔：打開時只列檔名、不讀檔頭")
        L.v:pump()
        check(heads > 0 and heads <= L.HEAD_MAX, "一幀最多讀 " .. L.HEAD_MAX .. " 個檔頭（讀了 " .. heads .. "）")
        local frames = 1
        while L.pending() > 0 and frames < 100 do
            L.v:pump()
            frames = frames + 1
        end
        check(heads == 1000 and frames == 40 and L.v.list.items[1].cells[3] == "10" and L.v.list.items[1].cells[4] == "7",
            "補完 1,000 個檔頭（40 幀），列出片數與這裡不能蓋的片數")
        PF.head = real.head
        L.close()
    end

    do -- MOD 更新或下架的告知：多了不能蓋的才通知，同樣的只通知一次
        local pl = sample("Ground")
        ground = pl
        setStates({})
        toasts = {}
        check(L.notices() == false and #toasts == 0, "告知：都能蓋時不通知")
        states.gone_01_0 = "missing"
        check(L.notices() == true and #toasts == 1, "告知：變成不能蓋時通知一則")
        check(L.notices() == false and #toasts == 1, "反面：狀態沒再變，下次進遊戲不再通知")
        states.off_01_0 = "off"
        check(L.notices() == true and #toasts == 2, "告知：又多一種不能蓋的，再通知")
        states.shut_01_0 = "closed"
        L.baseline(pl)
        check(L.notices() == false and #toasts == 2, "擺上時記基準：匯入時就缺的不再通知")
        ground = nil
        L.startNotices()
        for _ = 1, 3 do fire("OnTick") end
        local waiting = count("OnTick")
        ground = pl
        states.okay_01_0 = "missing"
        fire("OnTick")
        check(waiting == 1 and #toasts == 3 and count("OnTick") == 0, "進遊戲：等到地上的藍圖才檢查一次，然後摘掉自己")
        L.startNotices()
        ground = nil
        for _ = 1, L.WAIT_TICKS + 1 do fire("OnTick") end
        check(count("OnTick") == 0 and #toasts == 3, "反面：一直沒有藍圖，等滿就放棄、不通知")
    end

    do -- 面板：分組、閃、平面圖、手把、照圖蓋按鈕
        local pl, a, b, _, d = sample("Panel")
        ground = nil
        check(P.open(0) and L.visible() and not P.visible(), "面板：地上沒有藍圖時改開藍圖庫")
        L.close()
        ground = pl
        setStates(BAD)
        Plan.each(pl, function(p)
            local id = pl.items[p.it].id
            if id == "shut_01_0" then pieceState[p] = { "closed", "DISABLED_TILESET" }
            elseif id == "gone_01_0" then pieceState[p] = { "missing", "UNKNOWN" }
            elseif id == "off_01_0" then pieceState[p] = { "off", "DISABLED_KIND" }
            elseif p.x == 0 then pieceState[p] = { "short", "NO_MATERIAL" }
            elseif p.x == 1 then pieceState[p] = { "done" } end
        end)
        local mat = P.materials(nil)
        local groups = P.groups(mat)
        check(#groups == 4 and groups[1].code == "closed" and groups[1].n == 4 and groups[2].code == "missing"
            and mat.short["Base.Plank"] == 3 and mat.short["Base.Nails"] == nil and mat.missTools[1] == "Hammer",
            "蓋不了的片照原因分組（片多的在前）；缺料只算缺的")
        check(P.flash(groups[1].pieces) == 4 and flashed == 4, "點一組：那幾片都閃")
        local g = P.grid(pl, 0)
        check(#g.fine == 30 and g.counts.blocked == 7 and g.counts.short == 1 and g.counts.done == 1 and g.counts.ok == 1,
            "平面圖：一格一塊，圖例每種狀態有片數")
        SandboxVars.MinidoracatBuilder.AllowAutoBuild = false
        check(P.open(0) and P.visible() and P.v.goBtn.enabled == false and P.statusLines()[2][1] == "IGUI_MBLD_Plan_AutoOff",
            "沙盒關照圖蓋：按鈕停用、寫出原因")
        SandboxVars.MinidoracatBuilder.AllowAutoBuild = nil
        P.v:refresh()
        check(P.v.goBtn.enabled == true, "反面：沙盒沒關時能按")
        check(P.onGo(0) == "IGUI_MBLD_Plan_Start_NOTHING" and started == 1, "照圖蓋開不了：原因碼寫成句子")
        B.PlanMode.state = function() return "edit" end
        P.v:refresh()
        check(P.v.goBtn.enabled == false and P.statusLines()[2][1] == "IGUI_MBLD_Run_EDIT" and P.onGo(0) == "IGUI_MBLD_Run_EDIT"
            and started == 1, "規劃中：照圖蓋停用、寫出原因，硬按也不開始")
        B.PlanMode.state = function() return "fixed" end
        P.v:refresh()
        check(P.v.goBtn.enabled == true, "反面：規劃完成後又能按")
        B.PlanMode.state = nil
        local v = P.v
        v:show("map")
        v:refreshMap()
        local cv = v.canvas
        cv.render(cv)
        v.cx, v.cy = 0, 0
        check(cv.onFocusKey(cv, Keyboard.KEY_LEFT) == false and cv.onFocusKey(cv, Keyboard.KEY_RIGHT) == true and v.cx == 1,
            "手把：方向鍵移格子，到邊才讓焦點離開")
        flashed = 0
        cv.forceClick(cv)
        check(flashed == #Plan.at(pl, 1, 0, 0) and flashed > 0, "手把 A：閃游標那格的片")
        v.coarse, v.drawMs, v.frames = false, 0, 0
        for _ = 1, P.SAMPLE do cv.render(cv) end
        check(v.coarse == false, "反面：畫得快時不改粗格")
        clockStep = 2
        for _ = 1, P.SAMPLE do cv.render(cv) end
        clockStep = 0
        check(v.coarse == true, "平面圖：32 幀平均超過 1 毫秒改成 2×2 一塊")
        P.close()
        pieceState = {}
    end

    do -- 審查：改名、刪除時地上那張跟著改（不寫回舊檔名、不蓋掉重用檔名的新藍圖）
        three()
        ground = PF.load("Alpha.txt")
        local nf = L.rename("Alpha.txt", "Echo")
        check(nf == "Echo.txt" and ground.file == "Echo.txt" and ground.name == "Echo", "改名：地上那張的檔名與名稱跟著改")
        L.rename("Bravo.txt", "Foxtrot")
        check(ground.file == "Echo.txt", "反面：改別張不動地上那張")
        check(L.remove("Echo.txt") == true and ground.file == nil, "刪除：地上那張不再連到這個檔")
        local fresh = Plan.new("Echo")
        Plan.add(fresh, 0, 0, 0, 0, 0, Plan.item(fresh, "okay_01_0"))
        local file = L.store(fresh)
        local text = disk["MinidoracatBuilder/plans/Echo.txt"]
        local gf = ground.file or PF.fileName(ground.name) -- 之後存地上那張（PlanMode 的取檔名規則）
        PF.save(ground, gf)
        check(file == "Echo.txt" and gf ~= file and disk["MinidoracatBuilder/plans/Echo.txt"] == text,
            "刪除後重用同一個檔名：之後存地上那張不會蓋掉新藍圖")
        ground = nil
    end

    do -- 審查：收起失敗就停（換一張、面板收起、面板完成）
        local a, b = sample("Keep"), sample("Next")
        ground, placed, clearFail = a, 0, true
        L.open(0)
        dialogs = {}
        L.placePlan(b, 0)
        dialogs[#dialogs].onResult(true)
        check(ground == a and placed == 0 and L.visible(), "換一張：地上那張存不了就不換、藍圖庫留著")
        clearFail = false
        L.placePlan(b, 0)
        dialogs[#dialogs].onResult(true)
        check(ground == b and placed == 1, "反面：存得了就換")
        clearFail = true
        P.open(0)
        P.v:act("clear")
        dialogs[#dialogs].onResult(true)
        check(ground == b and P.visible(), "面板收起：存不了時地上那張與面板都留著")
        clearFail = false
        B.PlanMode.toggle = function() return false, "WRITE" end
        P.v:act("edit")
        check(P.visible(), "面板完成：存不了時面板留著")
        B.PlanMode.toggle = noop
        P.v:act("clear")
        dialogs[#dialogs].onResult(true)
        check(ground == nil and not P.visible(), "反面：存得了就收起、關面板")
    end

    do -- 審查：新的空白藍圖（沒有、定住、規劃中三種）
        ground, blanked, clearFail = nil, 0, false
        dialogs = {}
        L.open(0)
        local btn
        for _, c in ipairs(L.v.win.children) do if c.title == "IGUI_MBLD_Lib_New" then btn = c end end
        btn.onClick(L.v)
        check(blanked == 1 and #dialogs == 0 and ground ~= nil and not L.visible(), "空白藍圖：地上沒有時直接開、不問")
        local fixed = sample("Fixed")
        for _, mode in ipairs({ "fixed", "edit" }) do
            B.PlanMode.state = function() return mode end
            ground, blanked = fixed, 0
            L.newBlank(0)
            dialogs[#dialogs].onResult(false)
            check(ground == fixed and blanked == 0, "反面（" .. mode .. "）：按取消不動地上那張")
            clearFail = true
            L.open(0)
            L.newBlank(0)
            dialogs[#dialogs].onResult(true)
            check(ground == fixed and blanked == 0 and L.visible(), "空白藍圖（" .. mode .. "）：收不起來就不開新的、藍圖庫留著")
            clearFail = false
            L.newBlank(0)
            dialogs[#dialogs].onResult(true)
            check(ground ~= fixed and ground ~= nil and blanked == 1, "空白藍圖（" .. mode .. "）：先收起再開新的")
        end
        B.PlanMode.state = nil
        ground = nil
    end

    do -- 規劃中有沒存的改動：面板搬、收起，藍圖庫擺放、新的空白藍圖先問覆蓋／另存／取消，答完接著做（使用者 2026-11-18 裁定）
        local function press(title)
            for _, c in ipairs(L.chooser.win.children) do if c.title == title then return c.onClick() end end
            error("no button " .. title)
        end
        local keep = {}
        for k, v in pairs(disk) do keep[k] = v end
        local a, b = sample("Dirty"), sample("Other")
        a.file = "Dirty.txt"
        local picked, saved, savedAs, saveFail = 0, 0, nil, false
        local realSave = B.PlanMode.save
        B.PlanMode.pickUp = function()
            picked = picked + 1
            return true
        end
        B.PlanMode.save = function()
            if saveFail then return nil, "WRITE" end
            saved, dirty = saved + 1, false
            return true
        end
        B.PlanMode.saveAs = function(name)
            if saveFail then return false, "WRITE" end
            savedAs, dirty = name, false
            return true
        end
        local mode = "edit"
        B.PlanMode.state = function() return ground and mode or "none" end
        local function reset()
            ground, placed, blanked, dirty, picked, saved, savedAs, mode = a, 0, 0, true, 0, 0, nil, "edit"
            dialogs, toasts = {}, {}
            L.closeChooser()
        end
        -- 搬：沒有確認框，直接問
        reset()
        P.open(0)
        P.v:act("move")
        check(L.chooser ~= nil and picked == 0 and saved == 0 and #toasts == 0, "✗ 搬：有沒存的改動先問，還沒存、還沒拿起來")
        press("UI_Cancel")
        check(picked == 0 and saved == 0 and dirty and P.visible(), "搬→取消：不存、不拿起來，面板留著")
        P.v:act("move")
        press("IGUI_MBLD_SaveOverwrite")
        check(saved == 1 and picked == 1 and not P.visible(), "搬→覆蓋原本的：存好接著拿起來、關面板")
        reset()
        P.open(0)
        P.v:act("move")
        press("IGUI_MBLD_SaveAsNew")
        dialogs[#dialogs].onResult(true, "Dirty Two")
        check(savedAs == "Dirty Two" and saved == 0 and picked == 1, "搬→另存新檔：照新名稱另存、接著拿起來")
        reset()
        saveFail = true
        P.open(0)
        P.v:act("move")
        press("IGUI_MBLD_SaveOverwrite")
        check(picked == 0 and P.visible(), "✗ 搬→覆蓋但存不了：不拿起來、面板留著")
        saveFail = false
        -- 收起：先確認、按確認才問
        reset()
        P.open(0)
        P.v:act("clear")
        check(#dialogs == 1 and L.chooser == nil, "收起：先開確認框，還沒問存檔")
        dialogs[#dialogs].onResult(true)
        check(L.chooser ~= nil and ground == a, "✗ 收起→確認：有沒存的改動再問覆蓋或另存，還沒收")
        press("IGUI_MBLD_SaveOverwrite")
        check(saved == 1 and ground == nil and not P.visible(), "收起→覆蓋原本的：存好接著收起、關面板")
        -- 換一張
        reset()
        L.placePlan(b, 0)
        dialogs[#dialogs].onResult(true)
        check(L.chooser ~= nil and ground == a and placed == 0, "✗ 換一張→確認：先問，還沒換")
        press("UI_Cancel")
        check(ground == a and placed == 0 and saved == 0, "換一張→取消：地上那張照留、沒存")
        L.placePlan(b, 0)
        dialogs[#dialogs].onResult(true)
        press("IGUI_MBLD_SaveOverwrite")
        check(saved == 1 and ground == b and placed == 1, "換一張→覆蓋原本的：存好接著換")
        -- 新的空白藍圖
        reset()
        L.newBlank(0)
        dialogs[#dialogs].onResult(true)
        check(L.chooser ~= nil and blanked == 0 and ground == a, "✗ 新的空白藍圖→確認：先問，還沒開")
        press("IGUI_MBLD_SaveOverwrite")
        check(saved == 1 and blanked == 1 and ground ~= a and ground ~= nil, "新的空白藍圖→覆蓋原本的：存好、收起、開新的")
        -- 三選一不擋畫面：答的時候已經不在規劃那一張 → 不存、不做
        reset()
        P.open(0)
        P.v:act("move")
        ground = b
        press("IGUI_MBLD_SaveOverwrite")
        check(saved == 0 and picked == 0, "✗ 答的時候地上已經換了一張：不存、不拿起來")
        reset()
        P.open(0)
        P.v:act("move")
        mode = "fixed"
        press("IGUI_MBLD_SaveOverwrite")
        check(saved == 0 and picked == 0, "✗ 答的時候已經離開規劃：不存、不拿起來")
        -- 整張擦光了：沒有東西可以另存，只給覆蓋
        reset()
        ground = Plan.new("Wiped")
        ground.file = "Wiped.txt"
        P.open(0)
        P.v:act("move")
        local titles = {}
        for _, c in ipairs(L.chooser.win.children) do if c.title then titles[#titles + 1] = c.title end end
        check(table.concat(titles, ",") == "IGUI_MBLD_SaveOverwrite,UI_Cancel", "✗ 整張擦光了：三選一沒有另存新檔 " .. table.concat(titles, ","))
        -- 藍圖庫擺的就是規劃中那個檔：當成「搬」地上那張，不另讀一份存檔前的舊內容
        three()
        reset()
        ground = L.loadFile("Alpha.txt")
        local cur = ground
        L.placeFile("Alpha.txt", 0)
        check(L.chooser ~= nil and placed == 0, "✗ 擺規劃中那個檔：先問")
        press("IGUI_MBLD_SaveOverwrite")
        check(saved == 1 and placed == 1 and ground == cur, "✗ 擺規劃中那個檔→覆蓋：擺的是地上那張（不是存檔前讀的舊內容）")
        -- 沒有沒存的改動：照舊，不問
        reset()
        dirty = false
        P.open(0)
        P.v:act("move")
        check(L.chooser == nil and picked == 1 and saved == 0, "反面：沒有沒存的改動時搬照舊、不問")
        -- 另存也存不了：不接著做
        reset()
        saveFail = true
        P.open(0)
        P.v:act("move")
        press("IGUI_MBLD_SaveAsNew")
        dialogs[#dialogs].onResult(true, "Nope")
        check(picked == 0 and savedAs == nil and P.visible(), "✗ 搬→另存新檔但存不了：不拿起來、面板留著")
        saveFail = false
        -- 收起→另存新檔、新的空白藍圖→取消
        reset()
        P.open(0)
        P.v:act("clear")
        dialogs[#dialogs].onResult(true)
        press("IGUI_MBLD_SaveAsNew")
        dialogs[#dialogs].onResult(true, "Kept")
        check(savedAs == "Kept" and ground == nil and not P.visible(), "收起→另存新檔：照新名稱另存、接著收起")
        reset()
        L.newBlank(0)
        dialogs[#dialogs].onResult(true)
        press("UI_Cancel")
        check(blanked == 0 and ground == a and saved == 0, "新的空白藍圖→取消：地上那張照留、沒存、沒開新的")
        -- 另存的名稱框也不擋畫面：離開規劃（PlanMode 的 leaveEdit 會 L.closeChooser）時跟著關，
        -- 不然完成後再進規劃同一張，舊名稱框按確定還會另存、接著做（審查第 9 輪）
        reset()
        P.open(0)
        P.v:act("move")
        press("IGUI_MBLD_SaveAsNew")
        local box = dialogs[#dialogs]
        L.closeChooser()
        check(box.closed == true and savedAs == nil and picked == 0, "✗ 另存的名稱框開著時離開規劃：名稱框跟著關，不存、不拿起來")
        -- 三選一開著時藍圖庫刪檔、改名：三選一作廢（手上那份的檔名可能被別張重用，答了會寫進別張的檔；審查第 9 輪）
        three()
        reset()
        L.placePlan(L.loadFile("Bravo.txt"), 0)
        dialogs[#dialogs].onResult(true)
        check(L.chooser ~= nil, "（準備）換一張→確認：三選一開著")
        check(L.remove("Bravo.txt") == true and L.chooser == nil and placed == 0 and ground == a, "✗ 三選一開著時藍圖庫刪檔：三選一關掉、不換")
        L.placePlan(L.loadFile("Alpha.txt"), 0)
        dialogs[#dialogs].onResult(true)
        check(L.chooser ~= nil, "（準備）再換一張→確認：三選一開著")
        check(L.rename("Charlie.txt", "Zed") ~= nil and L.chooser == nil and placed == 0, "✗ 三選一開著時藍圖庫改名：三選一關掉、不換")
        -- 回呼裡再開一個三選一：新的留著、照樣能答
        local second = false
        L.askOverwrite(0, { name = "One", onOverwrite = function()
            L.askOverwrite(0, { name = "Two", onOverwrite = function() second = true end })
        end })
        press("IGUI_MBLD_SaveOverwrite")
        check(L.chooser ~= nil and not second, "回呼裡再開三選一：新的那個留著")
        press("IGUI_MBLD_SaveOverwrite")
        check(second and L.chooser == nil, "新的那個照樣能答")
        -- 規劃中、沒有沒存的改動，從藍圖庫擺同一個檔：不問，擺的是地上那張
        three()
        reset()
        dirty = false
        ground = L.loadFile("Alpha.txt")
        cur = ground
        L.placeFile("Alpha.txt", 0)
        check(L.chooser == nil and #dialogs == 0 and placed == 1 and ground == cur, "規劃中沒改動擺同一個檔：不問，擺的是地上那張")
        -- 審查第 9 輪複審：匯入框擺「地上正在規劃的同一個檔」。換過項目的那份當成另一張、不帶原檔名：
        -- 帶著的話，地上那張選了另存新檔之後檔名就不同了，這份會擺下去、定位時不問就寫回原檔
        three()
        reset()
        ground = L.loadFile("Alpha.txt")
        cur = ground
        local copy = L.loadFile("Alpha.txt")
        L.import(0)
        L.imp.plan, L.imp.rev = copy, copy.rev
        Plan.add(copy, 9, 9, 0, 0, 0, Plan.item(copy, "fresh_01_0"))
        L.imp:finish("place")
        check(L.chooser == nil and #dialogs == 1 and placed == 0, "✗ 匯入換過項目擺到地上、地上正在規劃同一個檔：不問覆蓋或另存，先問要不要換掉地上那張")
        if dialogs[1] then dialogs[1].onResult(true) end
        press("IGUI_MBLD_SaveAsNew")
        dialogs[#dialogs].onResult(true, "Alpha Two")
        check(placed == 1 and ground == copy and copy.file == nil and savedAs == "Alpha Two",
            "✗ 地上那張選另存新檔：擺下去的那份不帶原檔名（定位時不會寫回原檔）")
        L.closeImport()
        -- 沒換過項目的：擺的是地上那張（同 L.placeFile），不是匯入框手上那份舊的
        three()
        reset()
        ground = L.loadFile("Alpha.txt")
        cur = ground
        copy = L.loadFile("Alpha.txt")
        L.import(0)
        L.imp.plan, L.imp.rev = copy, copy.rev
        L.imp:finish("place")
        press("IGUI_MBLD_SaveOverwrite")
        check(saved == 1 and placed == 1 and ground == cur, "✗ 匯入沒換過項目擺到地上、地上正在規劃同一個檔：問地上那張怎麼存，搬的是地上那張")
        L.closeImport()
        -- 按下去時地上那張沒在規劃、匯入的三選一開著才去規劃同一個檔、再答覆蓋：也當成另一張（檢查要在答的那一刻做）
        three()
        reset()
        dirty = false
        ground = L.loadFile("Alpha.txt")
        mode = "fixed"
        copy = L.loadFile("Alpha.txt")
        L.import(0)
        L.imp.plan, L.imp.rev = copy, copy.rev
        Plan.add(copy, 9, 9, 0, 0, 0, Plan.item(copy, "fresh_01_0"))
        L.imp:finish("place")
        check(L.chooser ~= nil, "（準備）地上那張定住、匯入換過項目擺到地上：先問覆蓋或另存")
        mode = "edit"
        dialogs = {}
        press("IGUI_MBLD_SaveOverwrite")
        check(copy.file == nil and #dialogs == 1 and placed == 0, "✗ 三選一開著才去規劃同一個檔、再答覆蓋：那份當成另一張，先問要不要換掉地上那張")
        L.closeChooser()
        L.closeImport()
        do -- 第二條審查線（2026-11-19）：確認框、三選一都不擋畫面，答的時候世界可能變了
            local function grow(file)
                local pl = L.loadFile(file)
                Plan.add(pl, 9, 9, 0, 0, 0, Plan.item(pl, "fresh_01_0"))
                PF.save(pl, file)
                return pl.n
            end
            -- 換一張的確認框開著時，要擺的那個檔在藍圖庫存了新內容：按確定擺的是現在的內容
            -- （擺按下去那一刻讀的舊內容，定位時會把舊的寫回去、蓋掉剛存的）
            three()
            reset()
            dirty = false
            L.placeFile("Alpha.txt", 0)
            local nowN = grow("Alpha.txt")
            dialogs[#dialogs].onResult(true)
            check(placed == 1 and ground ~= a and ground.n == nowN, "✗ 換一張的確認框開著時那個檔存了新內容：按確定擺的是藍圖庫裡現在的內容")
            -- 地上那張有沒存的改動時還要答一次三選一：那段時間存的新內容也算
            three()
            reset()
            L.placeFile("Alpha.txt", 0)
            dialogs[#dialogs].onResult(true)
            nowN = grow("Alpha.txt")
            press("IGUI_MBLD_SaveOverwrite")
            check(saved == 1 and placed == 1 and ground.n == nowN, "✗ 地上那張的三選一開著時那個檔存了新內容：答完擺的是現在的內容")
            -- 確認框開著時那個檔刪掉了：不擺（擺了的話定位時會把刪掉的檔寫回來）、說一聲
            three()
            reset()
            dirty = false
            L.placeFile("Bravo.txt", 0)
            PF.remove("Bravo.txt")
            toasts = {}
            dialogs[#dialogs].onResult(true)
            check(placed == 0 and ground == a and #toasts == 1, "✗ 換一張的確認框開著時那個檔刪掉了：不擺、說一聲")
            -- 確認框上寫的是原本地上那張：答的時候地上換了別張就不做
            local swapped = sample("Swapped")
            three()
            reset()
            dirty, mode = false, "fixed"
            L.placePlan(b, 0)
            ground = swapped
            dialogs[#dialogs].onResult(true)
            check(placed == 0 and ground == swapped, "✗ 換一張的確認框開著時地上換了別張：不換")
            reset()
            dirty, mode = false, "fixed"
            L.newBlank(0)
            ground = swapped
            dialogs[#dialogs].onResult(true)
            check(blanked == 0 and ground == swapped, "✗ 新的空白藍圖的確認框開著時地上換了別張：不收起、不開新的")
            reset()
            dirty, mode = false, "fixed"
            P.open(0)
            P.v:act("clear")
            ground = swapped
            dialogs[#dialogs].onResult(true)
            check(ground == swapped, "✗ 收起的確認框開著時地上換了別張：不收起")
            -- 作廢的三選一（藍圖庫的檔變了、離開規劃）：舊按鈕還被按到也不做事
            three()
            reset()
            L.placePlan(L.loadFile("Bravo.txt"), 0)
            dialogs[#dialogs].onResult(true)
            local stale
            for _, c in ipairs(L.chooser.win.children) do if c.title == "IGUI_MBLD_SaveOverwrite" then stale = c.onClick end end
            L.closeChooser()
            stale()
            check(saved == 0 and placed == 0 and ground == a, "✗ 作廢的三選一再按覆蓋：不存、不換")
        end
        -- 三選一開不出來：不替玩家決定，只說先按完成或取消
        reset()
        local realAsk = L.askOverwrite
        L.askOverwrite = function() return nil end
        P.open(0)
        P.v:act("move")
        L.askOverwrite = realAsk
        check(picked == 0 and saved == 0 and #toasts == 1 and toasts[1] == "IGUI_MBLD_PlanUnsaved",
            "✗ 三選一開不出來：不存、不拿起來，說先按完成或取消")
        L.closeChooser()
        B.PlanMode.pickUp, B.PlanMode.save, B.PlanMode.saveAs, B.PlanMode.state = noop, realSave, nil, nil
        for k in pairs(disk) do disk[k] = nil end
        for k, v in pairs(keep) do disk[k] = v end
        dirty = false
        ground = nil
    end

    do -- 藍圖介面出來時收起建造工坊視窗；從面板「規劃」、新的空白藍圖進規劃時打開
        local W = B.Window
        ground = sample("Win")
        wins.open, wins.close = 0, 0
        W.openPlans()
        check(P.visible() and wins.close == 1, "工坊的藍圖鈕：地上有藍圖＝開藍圖面板、工坊視窗收起")
        P.close()
        ground = nil
        W.openPlans()
        check(L.visible() and wins.close == 2, "工坊的藍圖鈕：地上沒有＝開藍圖庫、工坊視窗收起")
        L.close()
        ground = sample("Win")
        P.open(0)
        P.v:act("edit")
        check(not P.visible() and wins.open == 1, "面板「規劃」：進規劃後面板關、工坊視窗打開")
        local asked = 0
        B.PlanMode.planning = function() return true end
        B.PlanMode.askFinish = function() asked = asked + 1 end
        P.open(0)
        P.v:act("edit")
        check(asked == 1 and wins.open == 1, "規劃中按面板「完成」：走 askFinish（改過的先問覆蓋或另存），不再開工坊")
        B.PlanMode.planning, B.PlanMode.askFinish = nil, nil
        P.close()
        ground, blanked = nil, 0
        L.newBlank(0)
        check(blanked == 1 and wins.open == 2, "新的空白藍圖：進規劃時工坊視窗打開")
        -- 審查 #10：「工坊被藍圖鈕收起」的記號（plansClosed，搬的放下後要不要叫回工坊）：面板與藍圖庫都關掉才清；
        -- 面板按「藍圖庫」轉過去時留著（藍圖庫先開）。搬一次就清在規劃那段驗
        local realVis = W.visible
        W.visible = function() return true end
        ground = sample("Win")
        W.openPlans() -- 面板
        L.open(0)
        P.close()
        local libStill = W.plansClosed
        L.close()
        local bothGone = W.plansClosed
        ground = nil
        W.openPlans() -- 藍圖庫
        ground = sample("Win")
        P.open(0)
        L.close()
        local panelStill = W.plansClosed
        P.close()
        local bothGone2 = W.plansClosed
        W.openPlans() -- 面板
        P.v:act("library")
        local switched = W.plansClosed == true and L.visible() and not P.visible()
        L.close()
        W.visible = realVis
        check(libStill == true and bothGone == nil and panelStill == true and bothGone2 == nil and switched and W.plansClosed == nil,
            "工坊被藍圖鈕收起的記號：面板、藍圖庫還有一個開著就留著，兩個都關了才清；面板轉藍圖庫時留著，藍圖庫再關才清")
        ground = nil
    end

    do -- 三選一的小框：覆蓋原本的／另存新檔／取消；另存再問名稱；同時只開一個；closeAll 也關
        local function press(title)
            for _, c in ipairs(L.chooser.win.children) do if c.title == title then return c.onClick() end end
            error("no button " .. title)
        end
        local got = {}
        local function ask()
            return L.askOverwrite(0, { name = "Foo", onOverwrite = function() got[#got + 1] = "over" end,
                onNew = function(n) got[#got + 1] = "new:" .. n end })
        end
        dialogs = {}
        check(ask() == true and L.chooser and L.chooser.win.visible and L.chooser.win.title == "IGUI_MBLD_SaveTitle",
            "askOverwrite：開出三選一的小框")
        local titles = {}
        for _, c in ipairs(L.chooser.win.children) do if c.title then titles[#titles + 1] = c.title .. "/" .. tostring(c.style) end end
        check(table.concat(titles, ",") == "IGUI_MBLD_SaveOverwrite/primary,IGUI_MBLD_SaveAsNew/nil,UI_Cancel/nil",
            "三顆鈕：覆蓋原本的（primary）、另存新檔、取消 " .. table.concat(titles, ","))
        local first = L.chooser.win
        ask()
        check(first.visible == false and L.chooser.win ~= first, "同時只開一個：再開一次先關掉舊的")
        press("IGUI_MBLD_SaveOverwrite")
        check(got[1] == "over" and L.chooser == nil, "按覆蓋原本的：先關框再呼叫 onOverwrite")
        ask()
        press("IGUI_MBLD_SaveAsNew")
        local d = dialogs[#dialogs]
        check(L.chooser == nil and d and d.input and d.input.text == "Foo" and d.text == "IGUI_MBLD_SaveAsText",
            "按另存新檔：關框、接一個名稱框（預設現在的名稱）")
        d.onResult(true, "Bar")
        check(got[2] == "new:Bar", "名稱框按確定：onNew 收到新名稱")
        ask()
        press("UI_Cancel")
        check(#got == 2 and L.chooser == nil, "按取消：什麼都不做、關框")
        ask()
        L.chooser.win:close()
        check(#got == 2 and L.chooser == nil, "X 關掉：什麼都不做")
        ask()
        local w = L.chooser.win
        L.chooser.win.onEscape()
        check(#got == 2 and L.chooser == nil and w.visible == false, "Esc：什麼都不做、關框")
        ask()
        w = L.chooser.win
        L.placePlan(sample("Close"), 0)
        check(L.chooser == nil and w.visible == false, "closeAll（擺放藍圖）也關掉三選一")
        ground = nil
    end

    do -- 審查：匯入框沒有可輸入的文字框，只能按鈕貼上；超長的不收、也沒有任何路徑送進剪貼簿
        local realClip = Clipboard
        local clip, sent = "", {}
        Clipboard = { getClipboard = function() return clip end, setClipboard = function(s) sent[#sent + 1] = #s end }
        L.import(0)
        local imp = L.imp
        local field, pasteBtn = false, nil
        for _, c in ipairs(imp.win.children) do
            if c.field then field = true end
            if c.title == "IGUI_MBLD_Imp_Paste" then pasteBtn = c end
        end
        check(not field and pasteBtn ~= nil and pasteBtn.y < imp.fileDD.y and imp.status.y == pasteBtn.y
            and imp.status.y + imp.status.height <= imp.fileDD.y, "匯入框：沒有原生文字框；貼上鈕在檔案清單上面，狀態行不蓋到下一列")
        check(imp.code == nil and imp.status.lines[1].s:find("IGUI_MBLD_Imp_CodeHint", 1, true) == 1, "還沒貼：狀態行說先複製再按貼上")
        clip = string.rep("A", PF.SHARE_MAX + 1)
        imp:paste()
        check(imp.code == nil and imp.err == "IGUI_MBLD_Imp_TooLong", "太長的剪貼簿不收，改請用檔案")
        clip = string.rep("A", 50000) .. "\195\169"
        imp:paste()
        check(imp.code == nil and imp.err == "IGUI_MBLD_Imp_TooLong", "有非 ASCII 字、轉 UTF-8 可能超過上限：不收")
        clip = PF.share((sample("Paste")), false)
        imp:paste()
        check(imp.code == clip and imp.plan ~= nil and imp.status.lines[1].s:find("IGUI_MBLD_Imp_CodeRead", 1, true) == 1,
            "反面：正常的分享碼貼得進來，狀態行寫已讀到")
        clip = PF.share((sample("Again")), false)
        imp:paste()
        check(imp.code == clip and imp.plan.name == "Again", "再按一次貼上：換成新的")
        imp.fileDD.selected = nil
        imp.fileDD.onChange(imp)
        check(imp.code == nil and imp.status.lines[1].s:find("IGUI_MBLD_Imp_CodeHint", 1, true) == 1, "選資料夾裡的檔：清掉已讀到的分享碼")
        check(L.copy(string.rep("A", PF.SHARE_MAX + 1)) == false, "反面：超長的分享碼也不寫進剪貼簿")
        local over = false
        for _, n in ipairs(sent) do if n > PF.SHARE_MAX then over = true end end
        check(not over, "整個匯入流程沒有任何超過上限的文字送進剪貼簿")
        L.closeImport()
        Clipboard = realClip
    end

    do -- 審查：檔名不合規則沒列出的檔要說；匯入結果列數有上限
        three()
        local list = PF.list
        PF.list = function() return list(), 3 end
        L.open(0)
        local drawn = {}
        L.v:headerRender({ drawText = function(_, s) drawn[#drawn + 1] = s end, drawTextRight = noop })
        check(L.st.skipped == 3 and drawn[1]:find("IGUI_MBLD_Lib_Skipped", 1, true) ~= nil, "藍圖庫：寫出幾個檔沒列出")
        L.import(0)
        local withSkip = #L.imp.box.children
        L.closeImport()
        PF.list = list
        L.import(0)
        check(withSkip == #L.imp.box.children + 1, "匯入框：沒列出的檔多一行說明")
        local pl = Plan.new("Huge")
        local st = {}
        for i = 1, 50 do
            local id = "miss" .. i .. "_01_0"
            st[id] = "missing"
            Plan.add(pl, i, 0, 0, 0, 0, Plan.item(pl, id, i <= 40 and { mod = "M" .. i } or nil))
        end
        setStates(st)
        local mods, more = 0, 0
        for _, ln in ipairs(L.describe(L.summary(pl.items), true)) do
            if ln[1] == "IGUI_MBLD_Imp_ModOff" then mods = mods + 1 end
            if ln[1] == "IGUI_MBLD_Imp_More" then more = more + 1 end
        end
        check(mods == L.LIST_MAX and more == 1, "匯入結果：MOD 行最多 " .. L.LIST_MAX .. " 行，其餘一行帶過")
        local imp = L.imp
        imp.plan = pl
        imp:render()
        local swaps = 0
        for _, c in ipairs(imp.box.children) do if c.title == "IGUI_MBLD_Imp_Swap" then swaps = swaps + 1 end end
        check(swaps == L.LIST_MAX, "匯入結果：換項目最多 " .. L.LIST_MAX .. " 列（共 50 種）")
        L.closeImport()
        L.close()
        setStates(BAD)
    end

    do -- 取不到檔名時說真正的原因（列不出資料夾＝READ）
        local fileName = PF.fileName
        PF.fileName = function() return nil, "READ" end
        local f, err = L.store(Plan.new("NoDir"))
        PF.fileName = fileName
        check(f == nil and err == "IGUI_MBLD_PlanErr_READ", "存進藍圖庫：取不到檔名時說列不出資料夾，不說檔名不合規則")
        local f2 = L.store(sample("HasDir"))
        check(f2 == "HasDir.txt", "反面：取得到檔名照常存")
    end

    do -- 審查第 2 輪：存進藍圖庫寫到地上那張的檔（定住＝地上換成這份；規劃中＝另存新的一張）
        three()
        ground = PF.load("Alpha.txt")
        local imp1 = L.loadFile("Alpha.txt")
        Plan.add(imp1, 9, 9, 0, 0, 0, Plan.item(imp1, "fresh_01_0"))
        local f1, new1 = L.store(imp1)
        PF.save(ground, ground.file) -- 之後地上那張存檔（收起、完成）
        check(f1 == "Alpha.txt" and not new1 and ground == imp1 and PF.load("Alpha.txt").n == imp1.n,
            "定住時存進藍圖庫：地上那張換成這份，之後存檔是換過的內容")
        ground = PF.load("Bravo.txt")
        local mine = ground
        B.PlanMode.state = function() return "edit" end
        local before = disk["MinidoracatBuilder/plans/Bravo.txt"]
        local imp2 = L.loadFile("Bravo.txt")
        Plan.add(imp2, 9, 9, 0, 0, 0, Plan.item(imp2, "fresh_01_0"))
        toasts = {}
        L.import(0)
        L.imp.plan = imp2
        L.imp.rev = imp2.rev - 1 -- 讀進來後換過項目；要蓋的那張正在規劃，不問、直接另存
        L.imp:finish("store")
        local copy = PF.load("Bravo2.txt")
        check(ground == mine and ground.file == "Bravo.txt" and disk["MinidoracatBuilder/plans/Bravo.txt"] == before
            and toasts[1] and toasts[1]:find("IGUI_MBLD_Imp_StoredNew", 1, true) == 1 and copy and copy.n == imp2.n,
            "規劃中存進藍圖庫：另存成新的一張（Bravo2.txt）並通知，原檔與地上那張都沒動")
        -- 審查第 9 輪：地上那張正跟著游標（搬到一半）也一樣另存：它定位時會把自己寫回那個檔，蓋掉剛存的
        three()
        ground = PF.load("Charlie.txt")
        mine = ground
        B.PlanMode.state = function() return "place" end
        before = disk["MinidoracatBuilder/plans/Charlie.txt"]
        local imp3 = L.loadFile("Charlie.txt")
        Plan.add(imp3, 9, 9, 0, 0, 0, Plan.item(imp3, "fresh_01_0"))
        toasts = {}
        L.import(0)
        L.imp.plan = imp3
        L.imp.rev = imp3.rev - 1
        L.imp:finish("store")
        check(L.chooser == nil and ground == mine and disk["MinidoracatBuilder/plans/Charlie.txt"] == before
            and toasts[1] and toasts[1]:find("IGUI_MBLD_Imp_StoredNew", 1, true) == 1 and PF.load("Charlie2.txt") ~= nil,
            "✗ 地上那張跟著游標時存進藍圖庫：不問、另存成新的一張，原檔沒動")
        L.closeChooser()
        L.closeImport()
        B.PlanMode.state = nil
        ground = nil
    end

    do -- 存進藍圖庫前三選一：從檔案讀的、讀進來後換過項目；分享碼、藍圖庫裡同名剛好一張才問
        local function press(title)
            for _, c in ipairs(L.chooser.win.children) do if c.title == title then return c.onClick() end end
            error("no button " .. title)
        end
        local function fresh(plan)
            Plan.add(plan, 9, 9, 0, 0, 0, Plan.item(plan, "fresh_01_0"))
            return plan
        end
        local function imp(plan, rev)
            L.import(0)
            L.imp.plan, L.imp.rev = plan, rev
            return L.imp
        end
        three()
        ground = nil
        local p = L.loadFile("Alpha.txt")
        local before = disk["MinidoracatBuilder/plans/Alpha.txt"]
        imp(p, p.rev)
        fresh(p)
        L.imp:finish("store")
        check(L.chooser ~= nil and disk["MinidoracatBuilder/plans/Alpha.txt"] == before,
            "從檔案讀的、換過項目：先問覆蓋或另存，還沒寫檔")
        press("IGUI_MBLD_SaveOverwrite")
        check(PF.load("Alpha.txt").n == 4 and L.imp == nil, "按覆蓋原本的：寫回同一個檔、關掉匯入框")
        three()
        p = L.loadFile("Alpha.txt")
        before = disk["MinidoracatBuilder/plans/Alpha.txt"]
        imp(p, p.rev)
        fresh(p)
        dialogs = {}
        L.imp:finish("store")
        press("IGUI_MBLD_SaveAsNew")
        dialogs[#dialogs].onResult(true, "Alpha Two")
        check(disk["MinidoracatBuilder/plans/Alpha.txt"] == before and p.file == "Alpha Two.txt" and p.name == "Alpha Two"
            and PF.load(p.file).n == 4, "按另存新檔：存成新名稱的新檔（檔名照新名稱），原本的檔沒動 " .. tostring(p.file))
        three()
        local code = fresh(Plan.new("Charlie")) -- 分享碼讀進來的：沒有檔名
        imp(code, code.rev)
        local realChoose, said = L.choose, nil
        L.choose = function(pn, o)
            said = o.text
            return realChoose(pn, o)
        end
        L.imp:finish("store")
        L.choose = realChoose
        check(L.chooser ~= nil and said == "IGUI_MBLD_Imp_SameName", "分享碼：藍圖庫裡剛好一張同名（Charlie）＝先問，說已經有一張")
        press("IGUI_MBLD_SaveOverwrite")
        check(code.file == "Charlie.txt" and PF.load("Charlie.txt").n == 1, "按覆蓋：蓋掉同名那張")
        -- 複審第二次：同名覆蓋寫不進（磁碟滿、檔被占用）。這份還是分享碼來的：留著檔名的話，再按「存進藍圖庫」
        -- 會當成已經在藍圖庫、說已存好，其實藍圖庫裡還是舊的那張
        three()
        local code2 = fresh(Plan.new("Charlie"))
        imp(code2, code2.rev)
        L.imp:finish("store")
        local realWriter = getFileWriter
        getFileWriter = function() return { write = function() end, close = function() end } end
        press("IGUI_MBLD_SaveOverwrite")
        getFileWriter = realWriter
        check(code2.file == nil and L.imp ~= nil and PF.load("Charlie.txt").n ~= code2.n, "✗ 同名覆蓋寫不進：匯入框留著、這份不算已經在藍圖庫")
        if L.imp then L.imp:finish("store") end
        check(L.chooser ~= nil, "✗ 同名覆蓋寫不進後再按存進藍圖庫：照樣再問一次（不是直接說已存好）")
        if L.chooser then press("IGUI_MBLD_SaveOverwrite") end
        check(PF.load("Charlie.txt").n == code2.n, "✗ 重試覆蓋：藍圖庫裡是這份的內容")
        -- 同名分享碼的三選一也一樣：匯入框關了再按另存新檔不開名稱框
        three()
        local code3 = fresh(Plan.new("Charlie"))
        imp(code3, code3.rev)
        L.imp:finish("store")
        L.closeImport()
        dialogs = {}
        press("IGUI_MBLD_SaveAsNew")
        check(#dialogs == 0 and L.namer == nil, "✗ 同名分享碼的三選一開著時按匯入框的取消：再按另存新檔不開名稱框")
        L.closeChooser()
        three()
        local delta = fresh(Plan.new("Delta"))
        imp(delta, delta.rev)
        L.imp:finish("store")
        check(L.chooser == nil and delta.file ~= nil and PF.load(delta.file) ~= nil, "✗ 分享碼、藍圖庫裡沒有同名：照舊直接存成新的一張")
        local twin = Plan.new("Bravo")
        Plan.add(twin, 1, 1, 0, 0, 0, Plan.item(twin, "okay_01_0"))
        PF.save(twin, "Bravo9.txt")
        local b2 = fresh(Plan.new("Bravo"))
        imp(b2, b2.rev)
        L.imp:finish("store")
        check(L.chooser == nil and b2.file ~= nil and b2.file:lower() ~= "bravo.txt" and b2.file:lower() ~= "bravo9.txt",
            "✗ 分享碼、藍圖庫裡同名兩張：不問，照舊存成新的一張 " .. tostring(b2.file))
        L.closeImport()
        -- 審查 1118：從檔案讀的、換過項目按「擺到地上」也先問（定位後的存檔會寫回那個檔）
        three()
        ground, placed = nil, 0
        p = L.loadFile("Alpha.txt")
        imp(p, p.rev)
        fresh(p)
        L.imp:finish("place")
        check(L.chooser ~= nil and placed == 0, "從檔案讀的、換過項目按擺到地上：先問覆蓋或另存，還沒擺")
        press("IGUI_MBLD_SaveOverwrite")
        check(placed == 1 and ground == p and p.file == "Alpha.txt", "按覆蓋原本的：照舊擺到地上（之後存回同一個檔）")
        ground, placed = nil, 0
        p = L.loadFile("Bravo.txt")
        imp(p, p.rev)
        fresh(p)
        dialogs = {}
        L.imp:finish("place")
        press("IGUI_MBLD_SaveAsNew")
        dialogs[#dialogs].onResult(true, "Bravo Two")
        check(placed == 1 and ground == p and p.file == nil and p.name == "Bravo Two",
            "按另存新檔：擺到地上的那份沒有檔名（定位後存成新的一張）、名稱照輸入的")
        ground, placed = nil, 0
        p = L.loadFile("Alpha.txt")
        imp(p, p.rev)
        L.imp:finish("place")
        check(L.chooser == nil and placed == 1, "✗ 從檔案讀的、沒換過項目按擺到地上：不問")
        -- 審查第 9 輪：地上正在規劃同一個檔時不問覆蓋或另存（這份當成另一張、之後另取檔名，沒有檔會被蓋掉；
        -- 問了的話接著還會問地上那張怎麼存，兩個框長得一樣），只問要不要換掉地上那張
        ground, placed, dirty = L.loadFile("Alpha.txt"), 0, false
        B.PlanMode.state = function() return "edit" end
        p = L.loadFile("Alpha.txt")
        imp(p, p.rev)
        fresh(p)
        dialogs = {}
        L.imp:finish("place")
        check(L.chooser == nil and #dialogs == 1 and placed == 0, "✗ 換過項目按擺到地上、地上正在規劃同一個檔：不問覆蓋或另存")
        if dialogs[1] then dialogs[1].onResult(true) end
        B.PlanMode.state = nil
        check(placed == 1 and ground == p and p.file == nil, "✗ 確定換掉：擺下去的那份沒有檔名")
        L.closeChooser()
        L.closeImport()
        -- 沒換過項目按擺到地上：擺藍圖庫裡現在的那個檔（匯入框開著的時候它可能存了新的內容，擺手上這份定位時會寫回舊的）
        three()
        ground, placed = nil, 0
        p = L.loadFile("Alpha.txt")
        imp(p, p.rev)
        PF.save(fresh(L.loadFile("Alpha.txt")), "Alpha.txt")
        L.imp:finish("place")
        check(placed == 1 and ground ~= p and ground.n == p.n + 1, "✗ 匯入框開著時那個檔存了新內容、沒換過按擺到地上：擺的是藍圖庫裡現在的內容")
        L.closeImport()
        -- 藍圖庫刪檔、改名：匯入框手上那份不再算那個檔（檔名可能被別張重用；刪掉的也不能當成「已經在藍圖庫裡」）
        three()
        ground, placed = nil, 0
        p = L.loadFile("Bravo.txt")
        imp(p, p.rev)
        L.remove("Bravo.txt")
        check(p.file == nil, "✗ 藍圖庫刪檔：匯入框手上那份的檔名清掉")
        L.closeImport()
        p = L.loadFile("Charlie.txt")
        imp(p, p.rev)
        L.rename("Charlie.txt", "Zed")
        check(p.file == nil, "✗ 藍圖庫改名：匯入框手上那份的檔名清掉")
        L.closeImport()
        -- 第二條審查線（2026-11-19）：按「擺到地上」之後才關匯入框（取消鈕、右上角的 X）或換了一份，
        -- 還開著的確認框、地上那張的存檔三選一都不算數：不存地上那張、不擺
        do
            local old = sample("Old")
            old.file = "Old.txt"
            local saves, realSave3 = 0, B.PlanMode.save
            B.PlanMode.save = function()
                saves = saves + 1
                return true
            end
            B.PlanMode.state = function() return ground and "edit" or "none" end
            local function begin(isDirty)
                L.closeChooser()
                L.closeImport()
                three()
                ground, placed, dirty, saves, dialogs = old, 0, isDirty, 0, {}
                local c = fresh(Plan.new("Code"))
                imp(c, c.rev)
                L.imp:finish("place")
                return c
            end
            begin(false)
            L.closeImport()
            dialogs[#dialogs].onResult(true)
            check(placed == 0 and ground == old, "✗ 換一張的確認框開著時按匯入框的取消：按確定不擺")
            begin(false)
            L.imp.win:close() -- 右上角的 X：只藏起來，L.imp 還在
            dialogs[#dialogs].onResult(true)
            check(placed == 0 and ground == old, "✗ 換一張的確認框開著時按匯入框的 X：按確定不擺")
            begin(false)
            L.imp.plan = fresh(Plan.new("Another"))
            dialogs[#dialogs].onResult(true)
            check(placed == 0 and ground == old, "✗ 換一張的確認框開著時匯入框換了一份：按確定不擺")
            begin(true)
            dialogs[#dialogs].onResult(true)
            check(L.chooser ~= nil, "（準備）地上那張有沒存的改動：存檔三選一開著")
            L.closeImport()
            press("IGUI_MBLD_SaveOverwrite")
            check(saves == 0 and placed == 0 and ground == old, "✗ 地上那張的存檔三選一開著時按匯入框的取消：答了不存、不擺")
            -- 複審：作廢之後按「另存新檔」連名稱框都不開（輸入完才發現不算數，還會把別的確認框擠掉）
            begin(true)
            dialogs[#dialogs].onResult(true)
            L.closeImport()
            local nDlg = #dialogs
            press("IGUI_MBLD_SaveAsNew")
            check(#dialogs == nDlg and L.namer == nil and saves == 0 and placed == 0 and ground == old,
                "✗ 地上那張的存檔三選一開著時按匯入框的取消：再按另存新檔不開名稱框")
            L.closeChooser()
            local c2 = begin(false)
            Plan.replace(c2, 1, "swapped_01_0")
            dialogs[#dialogs].onResult(true)
            check(placed == 1 and ground == c2, "反面：分享碼來的、確認框開著時換了項目：按確定擺的就是手上這份（換過的）")
            local c = begin(true)
            dialogs[#dialogs].onResult(true)
            press("IGUI_MBLD_SaveOverwrite")
            check(saves == 1 and placed == 1 and ground == c, "反面：匯入框還開著同一份：存好地上那張、擺下去")
            -- 沒換過項目的檔（L.placeFile 那條路）也一樣
            L.closeImport()
            three()
            ground, placed, dirty, dialogs = old, 0, false, {}
            p = L.loadFile("Alpha.txt")
            imp(p, p.rev)
            L.imp:finish("place")
            L.closeImport()
            dialogs[#dialogs].onResult(true)
            check(placed == 0 and ground == old, "✗ 沒換過項目的檔、換一張的確認框開著時按匯入框的取消：按確定不擺")
            -- 複審：沒換過項目的檔走「擺藍圖庫裡現在那個檔」；確認框開著時才在匯入框換了項目（同一份、rev 變），
            -- 再按確定會擺沒換過的那份、關掉匯入框，剛換的就沒了：不算數，匯入框留著讓玩家再按一次
            three()
            ground, placed, dirty, dialogs = old, 0, false, {}
            p = L.loadFile("Alpha.txt")
            imp(p, p.rev)
            L.imp:finish("place")
            local nSwap = Plan.replace(p, 1, "swapped_01_0")
            dialogs[#dialogs].onResult(true)
            check(nSwap > 0 and placed == 0 and ground == old and L.imp ~= nil and L.imp.plan == p and L.imp.win:getIsVisible(),
                "✗ 沒換過項目的檔、換一張的確認框開著時才換項目：按確定不擺沒換過的那份、匯入框留著")
            -- 匯入自己的三選一（換過項目、問覆蓋或另存）也一樣：匯入框關了再按另存新檔不開名稱框
            L.closeImport()
            three()
            ground, placed, dialogs = nil, 0, {}
            p = L.loadFile("Alpha.txt")
            imp(p, p.rev)
            Plan.replace(p, 1, "swapped_01_0")
            L.imp:finish("place")
            check(L.chooser ~= nil, "（準備）換過項目擺到地上：問覆蓋或另存")
            L.closeImport()
            press("IGUI_MBLD_SaveAsNew")
            check(#dialogs == 0 and L.namer == nil and placed == 0, "✗ 匯入的三選一開著時按匯入框的取消：再按另存新檔不開名稱框")
            B.PlanMode.save, B.PlanMode.state = realSave3, nil
            dirty, ground, placed = false, nil, 0
            L.closeChooser()
            L.closeImport()
        end
        -- 從檔案讀的、沒換過：檔已經在藍圖庫裡，不重寫（匯入框開著的時候那個檔可能存了新的內容）
        ground, placed = nil, 0
        three()
        p = L.loadFile("Alpha.txt")
        imp(p, p.rev)
        local newer = fresh(L.loadFile("Alpha.txt"))
        PF.save(newer, "Alpha.txt")
        local onDisk = disk["MinidoracatBuilder/plans/Alpha.txt"]
        toasts = {}
        L.imp:finish("store")
        check(disk["MinidoracatBuilder/plans/Alpha.txt"] == onDisk and L.imp == nil and toasts[1]
            and toasts[1]:find("IGUI_MBLD_Imp_Stored", 1, true) == 1, "從檔案讀的、沒換過按存進藍圖庫：不重寫那個檔（不會蓋掉後來存的內容）")
        -- 三選一開著的時候藍圖庫變了：同名那張被刪掉、檔名被另一張重用，按覆蓋不能寫進去
        three()
        code = fresh(Plan.new("Charlie"))
        imp(code, code.rev)
        L.imp:finish("store")
        check(L.chooser ~= nil, "（準備）分享碼和藍圖庫的 Charlie 同名：三選一開著")
        check(PF.remove("Charlie.txt") == true, "（準備）這時刪掉藍圖庫的 Charlie")
        local reuse = Plan.new("Other")
        Plan.add(reuse, 1, 1, 0, 0, 0, Plan.item(reuse, "okay_01_0"))
        Plan.add(reuse, 2, 1, 0, 0, 0, Plan.item(reuse, "okay_01_0"))
        PF.save(reuse, "Charlie.txt")
        local reused = disk["MinidoracatBuilder/plans/Charlie.txt"]
        press("IGUI_MBLD_SaveOverwrite")
        check(disk["MinidoracatBuilder/plans/Charlie.txt"] == reused and code.file ~= nil and code.file ~= "Charlie.txt"
            and PF.load(code.file).n == 1, "✗ 按覆蓋時同名那張已經不是原本那張：不寫進去，存成新的一張 " .. tostring(code.file))
        -- 要蓋的那張正在地上規劃：不問（蓋不了），照舊另存成新的一張並說明
        three()
        ground = PF.load("Charlie.txt")
        B.PlanMode.state = function() return "edit" end
        code = fresh(Plan.new("Charlie"))
        imp(code, code.rev)
        toasts = {}
        L.imp:finish("store")
        check(L.chooser == nil and code.file ~= nil and code.file ~= "Charlie.txt" and toasts[1]
            and toasts[1]:find("IGUI_MBLD_Imp_Stored", 1, true) == 1, "✗ 同名那張正在規劃：不問覆蓋，直接存成新的一張 " .. tostring(code.file))
        B.PlanMode.state = nil
        ground = nil
        -- 匯入框關掉之後才按舊的三選一：不做
        three()
        p = L.loadFile("Alpha.txt")
        before = disk["MinidoracatBuilder/plans/Alpha.txt"]
        imp(p, p.rev)
        fresh(p)
        L.imp:finish("store")
        local staleWin = L.chooser.win
        L.closeImport()
        for _, c in ipairs(staleWin.children) do if c.title == "IGUI_MBLD_SaveOverwrite" then c.onClick() end end
        check(disk["MinidoracatBuilder/plans/Alpha.txt"] == before, "✗ 匯入框關掉之後才按舊框的覆蓋：不寫檔")
    end

    do -- 審查第 2 輪：面板存檔失敗只讓 PlanMode 說一次；跟著游標時不能存；拿不起來時面板留著
        local pl = sample("PanelSave")
        ground = pl
        P.open(0)
        local save = B.PlanMode.save
        B.PlanMode.save = function() return nil, "STORE" end
        toasts = {}
        P.v:act("save")
        check(#toasts == 0, "面板存檔失敗：不再說一次、不露出原因碼")
        B.PlanMode.save = save
        P.v:act("save")
        check(#toasts == 1 and toasts[1] == "IGUI_MBLD_Plan_Saved", "反面：存好說已存檔")
        B.PlanMode.state = function() return "place" end
        P.v:refresh()
        check(P.v.saveBtn.enabled == false, "跟著游標時：存檔鈕停用")
        B.PlanMode.state = function() return "fixed" end
        P.v:refresh()
        check(P.v.saveBtn.enabled == true, "反面：定住時能存")
        B.PlanMode.state = nil
        B.PlanMode.pickUp = function() return false, "WRITE" end
        P.v:act("move")
        check(P.visible(), "搬：拿不起來（存不了檔）時面板留著")
        B.PlanMode.pickUp = function() return true end
        P.v:act("move")
        check(not P.visible(), "反面：拿起來了就關面板")
        B.PlanMode.pickUp = noop
        ground = nil
    end

    getFileReader, getFileWriter, listFilesInZomboidLuaDirectory = real.reader, real.writer, real.list
    MinidoracatUI, ISPanel, getTextManager, UIFont, JoypadState, Keyboard = real.ui, real.panel, real.tm, real.font, real.joy, real.kb
    getPlayerScreenTop, getPlayerScreenLeft, getPlayerScreenWidth, getPlayerScreenHeight = real.top, real.left, real.sw, real.sh
    getWorld, getCore, getItemName = real.world, real.core, real.item
    if B.Window then B.Window.ui = real.wui end
    B.PlanMode, B.PlanCheck, B.Runner, B.PlanGhost, B.Capture = real.PM, real.PC, real.R, real.PG, real.cap
    B.Window.open, B.Window.close = real.wopen, real.wclose
    B.Messages.toast, PF.head, clockStep, handlers.OnTick = real.toast, real.head, real.step, real.ontick
    SandboxVars.MinidoracatBuilder.AllowAutoBuild = real.auto
    L.v, L.st, L.imp, L.pick, P.v, P.hooked = nil, nil, nil, nil, nil, nil
end)()

-- ===== 藍圖：照圖蓋與材料箱 =====
;(function()
    print("藍圖：照圖蓋與材料箱（Runner 六段順序、一批上限、跳過與總結、暫停、材料箱；選單）")
    local B = MinidoracatBuilder
    require "MinidoracatBuilder/Plan"
    require "MinidoracatBuilder/Queue"
    require "MinidoracatBuilder/PlanStore"
    require "MinidoracatBuilder/Messages"
    require "MinidoracatBuilder/Runner"
    require "MinidoracatBuilder/Menu"
    local Plan, R, Q, PS, Menu = B.Plan, B.Runner, B.Queue, B.PlanStore, B.Menu
    local real = { PM = B.PlanMode, PC = B.PlanCheck, rec = B.Recipes, push = Q.push, cancel = Q.cancel, busy = Q.busy,
        item = Check.item, summary = Materials.summary, resolve = Entry.resolve, face = Entry.face, cells = Entry.cells,
        doorSet = Entry.doorSet, group = Entry.groupCells, alt = Entry.alternate, load = PS.load, save = PS.save,
        step = clockStep, q = ISTimedActionQueue, lu = luautils, xfer = ISInventoryTransferAction, ui = MinidoracatUI,
        core = Core, kb = Keyboard, specific = getSpecificPlayer, auto = sb.AllowAutoBuild, max = sb.MaxCellsPerDrag }
    clockStep = 0
    sb.MaxCellsPerDrag, sb.AllowAutoBuild = 3, nil -- 缺鍵當開
    Core = { getTileScale = function() return 1 end }
    Keyboard = { KEY_ESCAPE = 1 }
    B.Recipes = nil
    local toasts = {}
    MinidoracatUI = { v1 = { Toast = { show = function(o) toasts[#toasts + 1] = o.message end } } }

    -- 本段自己的項目：每種一個代表（車庫門帶寬度，一扇一次）
    local ENT = {}
    for _, k in ipairs({ "floor", "wall", "stairs", "door", "roof", "furniture" }) do ENT["rn_" .. k] = { kind = k, spr = "rn_" .. k } end
    ENT.rn_garage = { kind = "door", spr = "rn_garage", garage = true }
    Entry.resolve = function(id) return ENT[id] end
    Entry.face = function(e) return e.spr end
    Entry.cells = function(spr) return { { 0, 0, 0, spr } } end
    Entry.doorSet = function(spr) return ENT[spr] and ENT[spr].garage and { garage = true } or nil end
    Entry.groupCells = function(_, w)
        local o = {}
        for i = 1, w do o[i] = { i - 1, 0, 0, "rn_garage" } end
        return o
    end
    Entry.alternate = function(s) return s end
    -- Check.item：CODE["x,y,z"]＝{ code, extra, need, pay }；沒列的能蓋。pay＝原地替換的差額（成本表照 Check 只帶 items、uses）
    local CODE = {}
    Check.item = function(_, id, _, a)
        local c = CODE[a[1] .. "," .. a[2] .. "," .. a[3]]
        local info = { entry = ENT[id], cells = { { x = a[1], y = a[2], z = a[3] } },
            total = { items = c and c.need or {}, uses = {}, tools = {} } }
        if c and c.pay then info.replace, info.pay = { had = {} }, c.pay end
        if c then return c.code, c.extra, info end
        return nil, nil, info
    end
    local zero = function() return 0 end
    Materials.summary = function()
        return { items = setmetatable({}, { __index = zero }), uses = setmetatable({}, { __index = zero }), tools = {}, levels = {} }
    end
    -- 假的 PlanMode、PlanCheck：狀態照 S 表
    local OX, OY = 100, 100
    local S, at, touched, cleared, clearOk, shift, editing = {}, {}, 0, 0, true, 0, false
    local pl
    B.PlanCheck = {
        resolve = function(p) local it = pl.items[p.it]; return it and it.id, p.x + OX, p.y + OY, p.z, p.d, p.o, p.w end,
        state = function(p) return S[p] end,
        touch = function() touched = touched + 1 end,
        counts = function()
            local n, d = 0, 0
            Plan.each(pl, function(p) n = n + 1; if S[p] == "done" then d = d + 1 end end)
            return { n = n, done = d }
        end,
        materials = function() return { need = { ["Base.Plank"] = 4 }, have = { ["Base.Plank"] = 1 }, tools = {} } end,
    }
    local PM = { plan = function() return pl end, origin = function() return OX + shift, OY, 0 end,
        state = function() return editing and "edit" or "fixed" end,
        clear = function() cleared = cleared + 1; return clearOk end }
    -- 假的 Queue：記下每次送的；cancel 照 Queue 同步叫 onDone（stopped）
    local pushes, busy = {}, 0
    Q.push = function(_, id, anchors, parts, overlap, opts)
        pushes[#pushes + 1] = { id = id, anchors = anchors, parts = parts, overlap = overlap, opts = opts }
        return #pushes
    end
    Q.cancel = function()
        local j = pushes[#pushes]
        if j and not j.done then
            j.done = true
            j.opts.onDone({ count = #j.anchors, placed = 0, stopped = true })
        end
    end
    Q.busy = function() return busy end
    local function finish(sum)
        local j = pushes[#pushes]
        j.done = true
        sum.count = sum.count or #j.anchors
        j.opts.onDone(sum)
    end
    local function buildAll() -- 最後一批全部蓋好：那幾片變成 done
        local j = pushes[#pushes]
        for _, a in ipairs(j.anchors) do S[at[a[1] .. "," .. a[2] .. "," .. a[3]]] = "done" end
        finish({ placed = #j.anchors, stopped = false })
    end
    -- 假玩家與動作佇列
    local K = player({ id = 77, x = OX + 0.5, y = OY + 0.5 })
    K.chase, K.moving, K.vehicle = 0, false, nil
    function K:isAsleep() return false end
    function K:getVehicle() return self.vehicle end
    function K:getStats() local me = self; return { getNumChasingZombies = function() return me.chase end } end
    function K:isAttackStarted() return false end
    function K:isAiming() return false end
    function K:isJustMoved() return self.moving end
    K.pad, K.cancel = -1, false -- 手把編號（-1＝鍵盤）、取消動作鍵是不是按著
    function K:getJoypadBind() return self.pad end
    function K:pressedCancelAction() return self.cancel end
    function K:getMaxWeight() return 3 end
    function K.inv:getCapacityWeight() return K.load or 0 end
    function K.inv:getCountTypeRecurse(ft) return self:count(ft) end
    getSpecificPlayer = function() return K end
    local doing, actions, walks, clears = false, {}, {}, 0
    ISTimedActionQueue = { isPlayerDoingAction = function() return doing end,
        clear = function() clears = clears + 1; actions = {} end,
        hasAction = function(a)
            for _, x in ipairs(actions) do if x == a then return true end end
            return false
        end,
        add = function(a) actions[#actions + 1] = a end }
    luautils = { walkToContainer = function(c) walks[#walks + 1] = c; return true end }
    ISInventoryTransferAction = { new = function(_, _, it, src, dst) return { item = it, src = src, dst = dst } end }
    local store = { boxes = {} }
    PS.load = function() return store end
    PS.save = function(s) store = s; return true end

    local function run(n)
        for _ = 1, n or 1 do
            nowMs = nowMs + 100
            R.tick()
        end
    end
    local function drive() -- 每送一批就整批蓋好，直到停下
        for _ = 1, 200 do
            run(1)
            local j = pushes[#pushes]
            if j and not j.done then buildAll() end
            local s = R.state()
            if s == "done" or s == "paused" then return end
        end
    end
    local function newPlan()
        pl, S, at, CODE, pushes, busy = Plan.new("run"), {}, {}, {}, {}, 0
        R.stop()
    end
    local function put(id, x, y, z, w)
        local p = Plan.add(pl, x, y, z, 0, 0, Plan.item(pl, id), w)
        at[(x + OX) .. "," .. (y + OY) .. "," .. z] = p
        S[p] = "ok"
        return p
    end
    -- 一串批次的（段, 層）有沒有倒退
    local function ordered(list)
        for i = 2, #list do
            local a, b = list[i - 1], list[i]
            local sa, sb2 = R.SEGMENT[ENT[a.id].kind], R.SEGMENT[ENT[b.id].kind]
            if sb2 < sa or (sb2 == sa and b.anchors[1][3] < a.anchors[1][3]) then return false end
        end
        return true
    end

    -- 每個種類都有段（植入：拿掉一種就抓得到）
    local function uncovered()
        local n = 0
        for _, k in ipairs(Entry.KINDS) do if not R.SEGMENT[k] then n = n + 1 end end
        return n
    end
    local keep = R.SEGMENT.light
    R.SEGMENT.light = nil
    local planted = uncovered()
    R.SEGMENT.light = keep
    check(uncovered() == 0 and planted == 1 and R.SEGMENT.floor == 1 and R.SEGMENT.roof == 5 and R.SEGMENT.furniture == 6,
        "Runner.SEGMENT：每個種類都有段，少一種會被抓到")

    -- 沒有藍圖、沙盒關掉
    newPlan()
    B.PlanMode = nil
    local s1, c1 = R.start(K)
    B.PlanMode = PM
    put("rn_floor", 0, 2, 0)
    sb.AllowAutoBuild = false
    local s2, c2 = R.start(K)
    sb.AllowAutoBuild = true
    local s3 = R.start(K)
    local s4, c4 = R.start(K)
    check(s1 == nil and c1 == "NO_PLAN" and s2 == nil and c2 == "OFF" and #pushes == 0 and s3 == true and s4 == nil and c4 == "BUSY",
        "start：沒有藍圖 NO_PLAN、沙盒關掉 OFF 且不送；開著能開始，再按回 BUSY")

    -- 六段順序、一批上限、車庫門一扇一次、缺料跳過並列進總結
    newPlan()
    put("rn_roof", 0, 0, 1)
    put("rn_furniture", 1, 0, 0)
    put("rn_door", 2, 0, 0)
    put("rn_stairs", 3, 0, 0)
    for x = 0, 4 do put("rn_wall", x, 1, 0) end
    put("rn_floor", 0, 2, 0)
    put("rn_floor", 1, 2, 0)
    put("rn_floor", 0, 3, 1)
    put("rn_garage", 5, 5, 0, 2)
    put("rn_garage", 8, 5, 0, 2)
    local shortWall = put("rn_wall", 6, 1, 0)
    S[shortWall] = "short"
    toasts = {}
    check(R.start(K) == true, "照圖蓋開始")
    drive()
    local ids, maxN, garageOk = {}, 0, true
    for i, j in ipairs(pushes) do
        ids[i] = j.id .. "@" .. #j.anchors
        if #j.anchors > maxN then maxN = #j.anchors end
        if j.id == "rn_garage" and (#j.anchors ~= 1 or j.anchors[1][5] ~= 2 or #j.parts[1] ~= 2) then garageOk = false end
        if j.opts.owner ~= "plan" then garageOk = false end
    end
    local seq = table.concat(ids, ",")
    check(seq == "rn_floor@2,rn_floor@1,rn_wall@3,rn_wall@2,rn_stairs@1,rn_door@1,rn_garage@1,rn_garage@1,rn_roof@1,rn_furniture@1",
        "六段順序：地板（先低層）→ 牆 → 樓梯 → 門與車庫門（近的先）→ 屋頂 → 家具：" .. seq)
    check(ordered(pushes) and maxN == 3 and garageOk, "一批不超過一次最多幾格（3）；車庫門一批一扇、帶寬度與整扇虛影；owner＝plan")
    local swapped = { pushes[3], pushes[1] }
    check(not ordered(swapped), "反面：牆排在地板前面會被順序檢查抓到")
    local sum = R.summary()
    check(R.state() == "done" and (R.reason()) == "LEFT" and sum.left == 1 and sum.short.n == 1
        and sum.short.need["Base.Plank"] == 3 and cleared == 0 and touched > 0,
        "缺料的片跳過；這一輪結束 LEFT，總結列 1 片缺料、還差 3 塊木板；沒全蓋好不收藍圖")
    check(toasts[#toasts] and toasts[#toasts]:find("IGUI_MBLD_Run_LEFT", 1, true)
        and toasts[#toasts]:find("IGUI_MBLD_Run_Short", 1, true), "結束時跳一則總結通知")
    -- 補齊後再按：只蓋剩下那片，全部蓋好就收起藍圖
    S[shortWall] = "ok"
    local before = #pushes
    R.start(K)
    drive()
    check(#pushes == before + 1 and (R.reason()) == "DONE" and cleared == 1, "再按照圖蓋：只送剩下的 1 片；全蓋好 DONE、收起藍圖")

    -- 手動拖曳取消照圖蓋的批次 → 暫停 MANUAL；沒有玩家的請求時（走不過去）跳過那一片接著蓋
    newPlan()
    put("rn_floor", 0, 2, 0)
    put("rn_floor", 1, 2, 0)
    R.start(K)
    run(1)
    busy = 1
    Q.cancel()
    run(1)
    check(#pushes == 1 and R.state() == "paused" and (R.reason()) == "MANUAL", "手拖時（Queue 取消照圖蓋那一批、排著玩家的）：暫停 MANUAL")
    busy = 0
    R.start(K)
    run(1)
    Q.cancel()
    run(2)
    check(R.state() ~= "paused" and #pushes == 3 and #pushes[3].anchors == 1, "反面：沒有玩家的請求（走不過去）不算手動，跳過那一片接著蓋")

    -- 伺服器拒絕整批：暫停且不再送；只拒一片：跳過那片繼續
    newPlan()
    put("rn_floor", 0, 2, 0)
    put("rn_floor", 1, 2, 0)
    R.start(K)
    run(1)
    finish({ placed = 0, refused = "NOT_ALLOWED", extra = { i = 0 }, stopped = true })
    local n0 = #pushes
    run(5)
    local code, text = R.reason()
    check(R.state() == "paused" and code == "REFUSED" and text and text:find("IGUI_MBLD_Run_REFUSED", 1, true) and #pushes == n0,
        "整批被拒（i＝0）：暫停 REFUSED、不再送")
    R.start(K)
    run(1)
    finish({ placed = 0, refused = "BLOCKED", extra = { i = 1 }, stopped = true })
    run(1)
    check(R.state() ~= "paused" and #pushes == n0 + 2 and #pushes[#pushes].anchors == 1, "只拒一片（i＞0）：那片跳過，其他接著送")

    -- 玩家站在要放家具的那一格（PlanCheck 判成 OCCUPIED）：先走到旁邊再蓋，不回報「這格有人」
    do
        local realState, realAF, realWalk, realHere = B.PlanCheck.state, AdjacentFreeTileFinder, ISWalkToTimedAction, K.getCurrentSquare
        local DET, movers, finds = {}, 1, 0
        B.PlanCheck.state = function(p) return S[p], DET[p] end
        K.getCurrentSquare = function(k)
            return { getX = function() return math.floor(k:getX()) end, getY = function() return math.floor(k:getY()) end,
                getZ = function() return 0 end,
                getMovingObjects = function() return { size = function() return movers end } end }
        end
        AdjacentFreeTileFinder = { Find = function() finds = finds + 1; return { side = true } end }
        ISWalkToTimedAction = { new = function(_, _, sq) return { walkTo = sq } end }

        newPlan()
        local chair = put("rn_furniture", 0, 0, 0) -- 世界 (100,100,0)＝K 站的那一格
        S[chair], DET[chair] = "blocked", "OCCUPIED"
        actions, movers = {}, 2
        local sA, cA = R.start(K)
        movers = 1
        local sB = R.start(K)
        run(1)
        local walked, stA, nA = #actions == 1 and actions[1].walkTo ~= nil, R.state(), #pushes
        doing = true
        run(3)
        doing = false
        S[chair], DET[chair] = "ok", nil -- 走開了：PlanCheck 重查後可蓋
        local t0 = touched
        drive()
        check(sA == nil and cA == "NOTHING", "反面：腳下那格還有別人，不讓位（沒有能蓋的）")
        check(sB == true and walked and stA == "build" and nA == 0 and finds == 1,
            "只剩腳下那一片：照圖蓋先排走路讓位（對外算在蓋），不回「沒有能蓋的」")
        check(touched > t0 and #pushes == 1 and pushes[1].id == "rn_furniture" and R.state() == "done" and (R.reason()) == "DONE",
            "走開後請 PlanCheck 重查，接著把那一片蓋好")

        newPlan()
        local sofa = put("rn_furniture", 0, 0, 0)
        S[sofa], DET[sofa] = "blocked", "OCCUPIED"
        actions, finds = {}, 0
        R.start(K)
        drive() -- 走開後還是 OCCUPIED（別人站上去）：不再讓
        local sum = R.summary()
        check(finds == 1 and #pushes == 0 and R.state() == "done" and (R.reason()) == "LEFT" and sum and sum.blocked.OCCUPIED == 1,
            "一片只讓一次：走開後還是有人就列進沒蓋的")

        B.PlanCheck.state, AdjacentFreeTileFinder, ISWalkToTimedAction, K.getCurrentSquare = realState, realAF, realWalk, realHere
    end

    -- 暫停條件：殭屍在追、自己走、Esc；藍圖收起就停止
    newPlan()
    put("rn_floor", 0, 2, 0)
    R.start(K)
    K.chase = 1
    run(1)
    local zombie = R.reason()
    K.chase = 0
    R.start(K)
    K.moving, doing = true, true
    run(3)
    local walkingAction = R.state()
    doing = false
    run(2)
    local moved = R.reason()
    K.moving = false
    R.start(K)
    local function key(ev, k) -- 別的模組的按鍵處理在假環境可能出錯：各自包 pcall
        for _, f in ipairs(handlers[ev] or {}) do pcall(f, k) end
    end
    -- 真鍵盤：角色正在做動作時，原版在按下那一刻取消動作並吃掉這次按鍵（MainScreen.lua 的 StartPressCancelActionKey），
    -- 只有 OnKeyStartPressed 會來，放開的 OnKeyPressed 不會來（實機 plan-mp --fg 抓到：只掛放開時照圖蓋接著蓋別片）
    key("OnKeyStartPressed", 30)
    local otherKey = R.state()
    key("OnKeyStartPressed", 1)
    local esc = R.reason()
    check(zombie == "ZOMBIE" and walkingAction ~= "paused" and moved == "MOVED" and otherKey ~= "paused" and esc == "ESC",
        "殭屍在追 → ZOMBIE；佇列走路不算自己走；佇列空著還在動 → MOVED；別的鍵不停；按下 Esc 那一刻（只來 OnKeyStartPressed）→ ESC")
    -- 「取消動作」改綁到別的鍵：按那個鍵也停，通知不寫「按了 Esc」
    R.start(K)
    local realCoreK, realKidK = getCore, KeybindId
    KeybindId = { CANCEL_ACTION = "CancelAction" }
    getCore = function() return { isKey = function(_, id, k) return id == "CancelAction" and k == 57 end } end
    key("OnKeyStartPressed", 57)
    getCore, KeybindId = realCoreK, realKidK
    check(R.state() == "paused" and (R.reason()) == "PAUSE", "「取消動作」綁在別的鍵：按下那個鍵也停，原因是 PAUSE 不是 ESC")
    -- 手把的 B（取消動作）沒有按鍵事件，每幀看：只認焦點在角色身上時按下的那一次；鍵盤玩家光是按著不走這條
    local realJoy = getJoypadData
    local joy = { focus = nil }
    getJoypadData = function() return joy end
    if not K.getPlayerNum then function K:getPlayerNum() return 0 end end
    R.start(K)
    K.cancel = true
    run(1)
    local kbHeld = R.state()
    K.cancel = false
    K.pad = 0
    run(1)
    K.cancel = true
    local toastsBefore = #toasts
    run(1)
    check(kbHeld ~= "paused" and R.state() == "paused" and (R.reason()) == "PAUSE" and #toasts == toastsBefore + 1,
        "手把：焦點在角色身上時按下 B → 暫停 PAUSE、跳一則通知；鍵盤玩家沒有按鍵事件時不停")
    -- 用 B 關面板：按下時焦點在面板，面板關掉後焦點回角色、B 還按著
    R.start(K)
    joy.focus, K.cancel = {}, false
    run(1)
    joy.focus, K.cancel = nil, true
    run(3)
    local bleed = R.state()
    K.cancel = false
    run(1)
    K.cancel = true
    run(1)
    check(bleed ~= "paused", "手把：用 B 關面板（面板關掉後 B 還按著）不暫停 got=" .. tostring(bleed))
    check(R.state() == "paused" and (R.reason()) == "PAUSE", "手把：放開後焦點在角色身上再按 B 才暫停")
    K.pad, K.cancel = -1, false
    getJoypadData = realJoy
    R.stop()
    R.start(K)
    B.PlanMode = { plan = function() return Plan.new("other") end, origin = PM.origin }
    run(1)
    B.PlanMode = PM
    check(R.state() == "done" and (R.reason()) == "PLAN_GONE", "地上的藍圖換掉：停止 PLAN_GONE")

    -- 材料箱：點名、只拿點名的、拿這一批缺的；選單只在有藍圖時列
    local function crate(sq, items)
        local c, obj = { items = items }, {}
        function c:getParent() return obj end
        function c:getItems() return javaList(self.items) end
        function c:getType() return "crate" end
        function c:getCustomName() return nil end
        function c:getDisplayType() return "crate" end
        function obj:getSquare() return sq end
        function obj:getContainerCount() return 1 end
        function obj:getContainerByIndex(i) return i == 0 and c or nil end
        sq.objects[#sq.objects + 1] = obj
        return c, obj
    end
    local function planks(n, ft)
        local out = {}
        for k = 1, n do
            out[k] = item(ft or "Base.Plank")
            out[k].getUnequippedWeight = function() return 1 end
        end
        return out
    end
    local boxA, objA = crate(square(130, 100, 0), planks(3))
    local boxB = crate(square(131, 100, 0), planks(5))
    newPlan()
    store = { boxes = {} }
    local menuOff = #Menu.planBoxes({ objA })
    B.PlanMode = PM
    put("rn_wall", 20, 0, 0)
    local i1, i2 = R.addBox(boxA), R.addBox(boxA)
    local listed = Menu.planBoxes({ objA })
    check(i1 == 1 and i2 == 1 and #store.boxes == 1 and R.boxOf(boxA) == 1 and R.boxOf(boxB) == nil
        and #listed == 1 and listed[1].i == 1 and listed[1].title == "crate",
        "點名材料箱：同一個不重複記；選單列出已點名的那個")
    B.PlanMode = nil
    check(#Menu.planBoxes({ objA }) == 0, "反面：地上沒有藍圖時選單不列材料箱")
    B.PlanMode = PM
    local wallAt = (20 + OX) .. "," .. OY .. ",0"
    S[at[wallAt]] = "short"
    CODE[wallAt] = { code = "NO_MATERIAL", extra = { need = { ["Base.Plank"] = 2 } }, need = { ["Base.Plank"] = 2 } }
    actions, walks = {}, {}
    check(R.start(K) == true, "缺料但有材料箱：照圖蓋開始")
    run(1)
    local took = #actions == 2 and actions[1].item.ft == "Base.Plank" and actions[1].src == boxA and actions[2].src == boxA
    check(R.state() == "fetch" and walks[1] == boxA and #walks == 1 and took, "缺料：走去點名的箱子，只拿這一批缺的 2 塊（沒點名的箱子不碰）")
    for _, a in ipairs(actions) do K.inv:add(a.item) end
    CODE[wallAt] = nil
    run(6)
    check(#pushes == 1 and pushes[1].id == "rn_wall", "拿到料後接著送那一批")
    -- 箱子不見、在沒載入的地方：跳過、列進總結，不會出錯
    newPlan()
    store = { boxes = { { x = 132, y = 100, z = 0, index = 0 }, { x = 999, y = 999, z = 0, index = 0 } } }
    square(132, 100, 0)
    put("rn_wall", 21, 0, 0)
    local w2 = (21 + OX) .. "," .. OY .. ",0"
    S[at[w2]] = "short"
    CODE[w2] = { code = "NO_MATERIAL", extra = { need = { ["Base.Plank"] = 2 } }, need = { ["Base.Plank"] = 2 } }
    walks = {}
    R.start(K)
    local okRun = pcall(run, 30)
    local s5 = R.summary()
    check(okRun and #walks == 0 and R.state() == "done" and s5.boxes[1] == "GONE" and s5.boxes[2] == "FAR" and s5.short.n == 1,
        "材料箱不見、沒載入：不走過去、不出錯，總結列出兩個箱子的原因")

    -- 配方片：交給 Recipes.runCells（段照配方的 kind）
    newPlan()
    store = { boxes = {} }
    local rc = {}
    B.Recipes = { get = function() return { kind = "wall", name = "W" } end, stopCells = function() end,
        runCells = function(_, id, cells, onDone) rc[#rc + 1] = { id = id, cells = cells, onDone = onDone }; return true end }
    local rp = put("recipe:Base.X", 2, 2, 0)
    put("rn_floor", 0, 2, 0)
    R.start(K)
    drive() -- 先送地板（第 1 段），再送配方牆（第 2 段）
    run(1)
    local recOk = #pushes == 1 and pushes[1].id == "rn_floor" and #rc == 1 and #rc[1].cells == 1 and rc[1].cells[1][1] == 102
    S[rp] = "done"
    rc[1].onDone({ count = 1, placed = 1, stopped = false })
    run(30)
    check(recOk and (R.reason()) == "DONE", "配方片：照 kind 排進牆那一段，交給 Recipes.runCells；蓋好後完成")

    -- 全蓋好但收起失敗（PlanMode.clear 存檔失敗回 false，藍圖留在地上）：說藍圖還在；收成了只說完成
    newPlan()
    B.Recipes = nil
    put("rn_floor", 0, 2, 0)
    clearOk, toasts = false, {}
    R.start(K)
    drive()
    local keepMsg = toasts[#toasts]
    clearOk = true
    newPlan()
    put("rn_floor", 0, 2, 0)
    toasts = {}
    R.start(K)
    drive()
    local doneMsg = toasts[#toasts]
    check(keepMsg and keepMsg:find("IGUI_MBLD_Run_DONE_KEEP", 1, true) and doneMsg
        and doneMsg:find("IGUI_MBLD_Run_DONE", 1, true) and not doneMsg:find("KEEP", 1, true),
        "全蓋好：PlanMode.clear 回 false 時說藍圖還在地上；反面：收成了只說完成")

    -- 批次送出後藍圖改了：結果不套到片上，那幾格重查、暫停 EDIT、不再送
    newPlan()
    put("rn_floor", 0, 2, 0)
    put("rn_floor", 1, 2, 0)
    R.start(K)
    run(1)
    local t8 = touched
    put("rn_wall", 5, 5, 0) -- 加片＝rev 加一（搬、轉、刪、換項目同樣加 rev）
    buildAll()
    local n8 = #pushes
    run(3)
    check(n8 == 1 and R.state() == "paused" and (R.reason()) == "EDIT" and #pushes == n8 and touched >= t8 + 2,
        "批次送出後藍圖改了：不套結果、那幾格重查、暫停 EDIT 不再送")
    -- 整張搬了（原點換了）、進入規劃：送出前就暫停
    newPlan()
    put("rn_floor", 0, 2, 0)
    R.start(K)
    shift = 1
    run(1)
    shift = 0
    local movedPlan = R.reason()
    R.start(K)
    editing = true
    run(1)
    editing = false
    local editCode, editText = R.reason()
    check(movedPlan == "EDIT" and editCode == "EDIT" and #pushes == 0 and editText:find("IGUI_MBLD_Run_EDIT", 1, true),
        "原點換了、進入規劃：照圖蓋送出前暫停 EDIT")

    -- 原地替換缺差額：用 Check.item 算好的差額去拿（真的 Materials.short 收到沒有 tools 的成本表會出錯）
    local boxC = crate(square(133, 100, 0), planks(4))
    newPlan()
    store = { boxes = {} }
    R.addBox(boxC)
    put("rn_wall", 22, 0, 0)
    local w3 = (22 + OX) .. "," .. OY .. ",0"
    S[at[w3]] = "short"
    CODE[w3] = { code = "NO_MATERIAL", extra = { need = { ["Base.Plank"] = 1 } }, need = { ["Base.Plank"] = 3 },
        pay = { ["Base.Plank"] = 1 } }
    actions, walks = {}, {}
    R.start(K)
    local okC6 = pcall(run, 1)
    check(okC6 and R.state() == "fetch" and walks[1] == boxC and #actions == 1, "原地替換缺差額：不出錯，去箱子只拿差的 1 塊")
    R.stop()

    -- 箱子在但沒有要的、負重放不下：跳過這個箱子，總結說原因，不出錯
    local boxE = crate(square(134, 100, 0), planks(2, "Base.Log"))
    local boxH = crate(square(135, 100, 0), planks(2))
    newPlan()
    store = { boxes = {} }
    R.addBox(boxE)
    R.addBox(boxH)
    put("rn_wall", 23, 0, 0)
    local w4 = (23 + OX) .. "," .. OY .. ",0"
    S[at[w4]] = "short"
    CODE[w4] = { code = "NO_MATERIAL", extra = { need = { ["Base.Plank"] = 2 } }, need = { ["Base.Plank"] = 2 } }
    K.load, walks, toasts = 3, {}, {}
    R.start(K)
    local okC7 = pcall(run, 30)
    K.load = 0
    local s7 = R.summary()
    check(okC7 and #walks == 0 and R.state() == "done" and s7.boxes[1] == "EMPTY" and s7.boxes[2] == "HEAVY"
        and toasts[#toasts] and toasts[#toasts]:find("IGUI_MBLD_Run_Box", 1, true), -- 假 getText 不帶參數：只看得到材料箱那一行
        "箱子沒有要的 EMPTY、負重放不下 HEAVY：不走過去、不出錯，總結列出")

    -- 一片一組地拿：箱子裡重的排前面（木板 3.0），負重只夠一片時要拿到配得齊的一組，不是照箱子順序只拿木板
    local function stock(ft, n, w)
        local out = {}
        for k = 1, n do
            out[k] = item(ft)
            out[k].getUnequippedWeight = function() return w end
        end
        return out
    end
    local function join(...)
        local out = {}
        for _, list in ipairs({ ... }) do
            for _, it in ipairs(list) do out[#out + 1] = it end
        end
        return out
    end
    local function shortAt(x, set)
        local k = (x + OX) .. "," .. OY .. ",0"
        CODE[k] = set and { code = "NO_MATERIAL", extra = { need = set }, need = set } or nil
        return at[k]
    end
    local maxW = K.getMaxWeight
    K.getMaxWeight = function() return 6 end
    local boxS = crate(square(137, 100, 0), join(stock("Base.Plank", 4, 3), stock("Base.Nails", 4, 0.1), stock("Base.ClayTile", 8, 0.5)))
    newPlan()
    store = { boxes = {} }
    R.addBox(boxS)
    local SET = { ["Base.Plank"] = 1, ["Base.Nails"] = 1, ["Base.ClayTile"] = 2 }
    for i = 0, 2 do
        put("rn_floor", 30 + i, 0, 0)
        S[shortAt(30 + i, SET)] = "short"
    end
    actions, walks = {}, {}
    R.start(K)
    run(1)
    local gotS = {}
    for _, a in ipairs(actions) do gotS[a.item.ft] = (gotS[a.item.ft] or 0) + 1 end
    check(R.state() == "fetch" and #actions == 4 and gotS["Base.Plank"] == 1 and gotS["Base.Nails"] == 1
        and gotS["Base.ClayTile"] == 2,
        "材料箱：負重只夠一片時拿配得齊的一組（木板 1、釘子 1、瓷磚 2），不是照箱子順序只拿木板")
    R.stop()

    -- 沒有散裝釘子：拿一盒，後面幾片的釘子用同一盒抵
    K.getMaxWeight = function() return 20 end
    local boxB = crate(square(138, 100, 0), join(stock("Base.Plank", 2, 3), stock("Base.NailsBox", 2, 0.5)))
    newPlan()
    store = { boxes = {} }
    R.addBox(boxB)
    local NB = { ["Base.Plank"] = 1, ["Base.Nails"] = 2 }
    for i = 0, 1 do
        put("rn_floor", 34 + i, 0, 0)
        S[shortAt(34 + i, NB)] = "short"
    end
    actions, walks = {}, {}
    R.start(K)
    run(1)
    local gotB = {}
    for _, a in ipairs(actions) do gotB[a.item.ft] = (gotB[a.item.ft] or 0) + 1 end
    check(R.state() == "fetch" and #actions == 3 and gotB["Base.Plank"] == 2 and gotB["Base.NailsBox"] == 1,
        "材料箱：沒有散裝釘子時拿一盒，後面幾片的釘子用同一盒抵（不多拿）")
    R.stop()

    -- 材料分在兩個箱子：一組的重量連別的箱子才有的那幾樣一起算；放不下的箱子不記成壞的，蓋掉一片、變輕了再回去拿
    K.getMaxWeight = function() return 3.5 end
    local boxP = crate(square(140, 100, 0), stock("Base.Plank", 2, 3))
    local boxN = crate(square(150, 100, 0), stock("Base.Nails", 2, 0.1))
    newPlan()
    store = { boxes = {} }
    R.addBox(boxP)
    R.addBox(boxN)
    local PN = { ["Base.Plank"] = 1, ["Base.Nails"] = 1 }
    put("rn_wall", 40, 0, 0)
    put("rn_wall", 41, 0, 0)
    local p1, p2 = shortAt(40, PN), shortAt(41, PN)
    S[p1], S[p2] = "short", "short"
    local function runUntil(done)
        for _ = 1, 20 do
            run(1)
            if done() then return end
        end
    end
    local function fetching() return #actions > 0 end
    actions, walks = {}, {}
    R.start(K)
    run(1)
    local trip1 = #actions == 1 and actions[1].item.ft == "Base.Plank" and actions[1].src == boxP
    K.inv:add(table.remove(boxP.items, 1)) -- 拿到那塊木板：負重剩 0.5
    K.load = 3
    shortAt(40, { ["Base.Nails"] = 1 })
    actions = {}
    runUntil(fetching)
    local trip2 = #actions == 1 and actions[1].item.ft == "Base.Nails" and actions[1].src == boxN
    K.inv:add(table.remove(boxN.items, 1))
    shortAt(40, nil) -- 第一片配齊了
    actions = {}
    runUntil(function() return #pushes > 0 end)
    local built1 = #pushes == 1 and #pushes[1].anchors == 1
    if built1 then buildAll() end
    K.load = 0 -- 蓋掉了：木板、釘子用掉
    actions = {}
    runUntil(fetching)
    check(trip1 and trip2 and built1 and R.state() == "fetch" and #actions == 1 and actions[1].item.ft == "Base.Plank"
        and actions[1].src == boxP,
        "材料箱：兩個箱子各放一種時一次拿一片的份（木板留位置給釘子）；放不下的箱子蓋掉一片後再回去拿")
    R.stop()

    -- 木板和整盒釘子分在兩個箱子：重量照真的那一盒算（2.0），不能當成散釘留位置而先拿兩片木板
    K.getMaxWeight = function() return 6.2 end
    K.load = 0
    local boxP2 = crate(square(142, 100, 0), stock("Base.Plank", 2, 3))
    local boxNB = crate(square(152, 100, 0), stock("Base.NailsBox", 1, 2))
    newPlan()
    store = { boxes = {} }
    R.addBox(boxP2)
    R.addBox(boxNB)
    put("rn_floor", 44, 0, 0)
    put("rn_floor", 45, 0, 0)
    S[shortAt(44, PN)], S[shortAt(45, PN)] = "short", "short"
    actions, walks = {}, {}
    R.start(K)
    run(1)
    local onePlank = #actions == 1 and actions[1].item.ft == "Base.Plank" and actions[1].src == boxP2
    K.inv:add(table.remove(boxP2.items, 1))
    K.load = 3
    shortAt(44, { ["Base.Nails"] = 1 })
    actions = {}
    runUntil(fetching)
    check(onePlank and #actions == 1 and actions[1].item.ft == "Base.NailsBox" and actions[1].src == boxNB,
        "材料箱：木板和整盒釘子分在兩個箱子、負重 6.2 時只先拿一片木板（留得下那一盒 2.0），再去拿釘子盒")
    R.stop()

    -- 開工時就背不動（身上只有第一片的料）：第二片先放著、不算跳過，第一片蓋好、背包輕了再回去拿。
    -- 箱子裡和這一批無關的東西不檢查、不進候選
    local looked = 0
    local junk = stock("Base.Log", 30, 9)
    for _, it in ipairs(junk) do
        it.isFluidContainer = function() looked = looked + 1; return false end
    end
    local function laterCase(lighter)
        K.getMaxWeight = function() return 3.5 end
        K.load = 3.1
        local box = crate(square(lighter and 143 or 144, 100, 0), join(junk, stock("Base.Plank", 1, 3), stock("Base.Nails", 1, 0.1)))
        newPlan()
        store = { boxes = {} }
        R.addBox(box)
        put("rn_floor", 46, 0, 0)
        put("rn_floor", 47, 0, 0)
        S[shortAt(47, PN)] = "short"
        actions, walks = {}, {}
        R.start(K)
        runUntil(function() return #pushes > 0 end)
        local firstOnly = #pushes == 1 and #pushes[1].anchors == 1 and #actions == 0
        if firstOnly then buildAll() end
        if lighter then K.load = 0 end
        runUntil(function() return #actions > 0 or R.state() == "done" end)
        return firstOnly, box
    end
    local first1, boxL = laterCase(true)
    local again = R.state() == "fetch" and #actions == 2 and actions[1].src == boxL
    R.stop()
    local first2 = laterCase(false)
    local sL = R.summary()
    check(first1 and again and first2 and R.state() == "done" and (R.reason()) == "LEFT" and #actions == 0
        and sL.boxes[1] == "HEAVY" and sL.short.n == 1 and looked == 0,
        "材料箱：開工時背不動的片先放著，前一片蓋好、背包輕了再回去拿；反面：還是背不動就收尾並寫背包太重；無關的東西不檢查")
    R.stop()

    -- 旁邊沒地方站的箱子：整輪跳過、改去下一個；每個箱子這一趟只掃一遍（不因前面的箱子走不到而重掃）
    local scans = {}
    local function counted(x)
        local c = crate(square(x, 100, 0), stock("Base.Plank", 1, 1))
        local get = c.getItems
        c.getItems = function(self)
            scans[self] = (scans[self] or 0) + 1
            return get(self)
        end
        return c
    end
    local n1, n2, n3 = counted(145), counted(146), counted(147)
    K.load = 0
    newPlan()
    store = { boxes = {} }
    R.addBox(n1)
    R.addBox(n2)
    R.addBox(n3)
    put("rn_wall", 48, 0, 0)
    S[shortAt(48, { ["Base.Plank"] = 1 })] = "short"
    local walk0 = luautils.walkToContainer
    luautils.walkToContainer = function(c) return c == n3 end
    actions = {}
    R.start(K)
    run(1)
    luautils.walkToContainer = walk0
    local sN = R.summary()
    check(R.state() == "fetch" and #actions == 1 and actions[1].src == n3 and sN.boxes[1] == "NO_ROOM"
        and sN.boxes[2] == "NO_ROOM" and sN.boxes[3] == nil and scans[n1] == 1 and scans[n2] == 1 and scans[n3] == 1,
        "材料箱：旁邊沒地方站的箱子整輪跳過、改去下一個；每個箱子一趟只掃一遍")
    R.stop()
    K.getMaxWeight, K.load = maxW, 0

    -- 遊戲暫停：暫停時引擎不送 OnTick，照圖蓋在 OnTickEvenPaused 看
    local gp, pausedNow = isGamePaused, false
    isGamePaused = function() return pausedNow end
    local function tickPaused() -- 照引擎的路：走事件，不直接叫 Runner（註冊行拿掉時要紅）
        for _, f in ipairs(handlers.OnTickEvenPaused or {}) do pcall(f) end
    end
    newPlan()
    put("rn_floor", 0, 2, 0)
    pausedNow = true
    tickPaused()
    local idleState = R.state()
    pausedNow = false
    R.start(K)
    tickPaused()
    local running = R.state()
    pausedNow = true
    tickPaused()
    check(idleState ~= "paused" and running == "pick" and R.state() == "paused" and (R.reason()) == "GAME_PAUSED",
        "遊戲暫停：按了照圖蓋或正在蓋時暫停 GAME_PAUSED；反面：沒暫停不動、沒在跑不動")
    isGamePaused = gp
    R.stop()

    -- 拿料途中玩家自己動手：暫停 MANUAL、不再送；玩家的建造已換掉拿料動作時不清佇列
    local boxM = crate(square(136, 100, 0), planks(4))
    newPlan()
    store = { boxes = {} }
    R.addBox(boxM)
    put("rn_wall", 24, 0, 0)
    local w5 = (24 + OX) .. "," .. OY .. ",0"
    S[at[w5]] = "short"
    CODE[w5] = { code = "NO_MATERIAL", extra = { need = { ["Base.Plank"] = 2 } }, need = { ["Base.Plank"] = 2 } }
    actions, clears = {}, 0
    R.start(K)
    run(1)
    local fetching = R.state() == "fetch"
    actions, busy = {}, 1 -- 手動建造：Client.build 清掉佇列、排上玩家的請求
    run(10)
    local manualCode, manualClears = (R.reason()), clears
    busy = 0
    R.start(K) -- 反面：拿料動作還在佇列時暫停要清掉
    run(1)
    local queued = #actions
    R.pause("ESC")
