        RC.byId[STAIR] = { id = STAIR, kind = "stairs", name = "S", info = { getFace = function() return face end }, recipe = REC }
        RC.byId[PAINT] = { id = PAINT, kind = "wallOverlay", name = "P", cover = true, recipe = REC }
