    check(face("rp_01_0", 1) == "rp_01_0" and face("rp_01_0", 2) == "rp_01_72" and face("rp_01_0", 3) == "rp_01_24"
        and face("rp_01_0", 4) == "rp_01_48" and face("rp_01_48", 1) == "rp_01_0" and face("rp_01_0", 5) == nil,
        "坡道（Ramp）轉向：1..4 回北、東、南、西的頭片；沒有配對面")
    check(face("rn_01_0", 1) == "rn_01_0" and face("rn_01_0", 2) == nil and face("rn_01_0", 3) == nil,
        "坡道（Ramp）轉向：✗ 圖塊組沒有那個方向回 nil")
    do -- 藍圖轉向接真的 Entry（PlanMode.turnPiece 的坡道分支）
        local tp = MinidoracatBuilder.PlanMode and MinidoracatBuilder.PlanMode.turnPiece
        check(tp and tp({ d = 0 }, { id = "rp_01_0" }) == 2 and tp({ d = 2 }, { id = "rp_01_0" }) == 3
            and tp({ d = 3 }, { id = "rp_01_0" }) == 4 and tp({ d = 4 }, { id = "rp_01_0" }) == 0
            and tp({ d = 0 }, { id = "rp_01_48" }) == 1 and tp({ d = 0 }, { id = "rn_01_0" }) == nil,
            "坡道（Ramp）藍圖轉向（真的 Entry）：北→東→南→西→回自己那張（0）；西向的頭片轉到北；✗ 沒有下一個方向回 nil")
    end
    -- 成本
    local sprs = {}
    for k, o in ipairs(Entry.cells(Entry.sprite("rp_01_0"))) do sprs[k] = o[4] end
    local c1, c0 = Cost.forCells("ramp", sprs, 1), Cost.forCells("ramp", sprs, 0)
    check(c1[1].items["Base.Plank"] == 20 and c1[1].items["Base.Nails"] == 20 and next(c1[2].items) == nil
        and next(c1[20].items) == nil and next(c1[21].items) == nil and Cost.refund("ramp", spriteMap.rp_01_5) == "builder",
        "坡道（Ramp）成本：倍率 1 第一格＝20 片合計（木板 20、釘子 20），其他片與平台不收；拆除照帳本（builder）")
    check(next(c0[1].items) == nil and c0[1].tools[1] == "HAMMER" and c1[1].tools[1] == "HAMMER",
        "坡道（Ramp）成本：✗ 倍率 0 材料是空的，工具（鐵鎚）還在")
    local ch = Cost.forCells("ramp", sprs, 0.5)
    check(ch[1].items["Base.Plank"] == 10 and ch[1].items["Base.Nails"] == 10,
        "坡道（Ramp）成本：倍率 0.5 整組收 10 份（整組一次算，不逐片進位成 20）")
    check(Entry.rampSet(Entry.sprite("rs_01_0")) == nil and Entry.why("rs_01_0") == "RAMP_SET"
        and Entry.rampSet(Entry.sprite("rm_01_0")) == nil and Entry.why("rm_01_0") == "RAMP_SET"
        and intentCode(90, "rs_01_0", { 445, 430, 0, 0 }) ~= nil and intentCode(91, "rm_01_0", { 445, 430, 0, 0 }) ~= nil,
        "坡道（Ramp）✗ 一組裡有片帶 CanScrap 或 IsMoveAble：湊不成整組（RAMP_SET），伺服器不收（目錄同用 Entry.rampSet）")

    -- 能不能蓋（第 424 欄；預覽先在上一層還沒有格子時查）
    local PV = { preview = true, walk = true }
    P.pos.x = 424.5
    check(Check.item(P, "rp_01_0", 0, { 424, 430, 0 }, PV) == nil,
        "坡道（Ramp）預覽：✗ 平台那格上一層還沒有格子也不回 NO_UPPER（平台有角色，伺服器會蓋）")
    esq(424, 410, 1)
    local function item424() return Check.item(P, "rp_01_0", 0, { 424, 430, 0 }) end
    check(item424() == nil, "坡道（Ramp）能不能蓋：乾淨的 20 格加平台通過")
    local s6, s7 = at(424, 425), at(424, 424)
    local rs, rv = s6.isSomethingTo, at(424, 426).isVehicleIntersecting
    function s6:isSomethingTo(o) return o == s7 end
    local code, e = item424()
    s6.isSomethingTo = rs
    check(code == "BLOCKED" and e.y == 424, "坡道（Ramp）✗ 第 6、7 格之間有牆：BLOCKED，指第 7 格（y=" .. tostring(e and e.y) .. "）")
    local s5 = at(424, 426)
    function s5:isVehicleIntersecting() return true end
    local cv, ev = item424()
    s5.isVehicleIntersecting = rv
    s7.moving = { {} }
    local co, eo = item424()
    s7.moving = {}
    s7.objects[#s7.objects + 1] = IsoObject.new(nil, s7, spriteMap.rn_01_3)
    local cs = item424()
    table.remove(s7.objects)
    local hole = at(424, 415)
    squares["424,415,0"] = nil
    local cl, el = item424()
    squares["424,415,0"] = hole
    check(cv == "VEHICLE" and ev.y == 426 and co == "OCCUPIED" and eo.y == 424 and cs == "BLOCKED" and cl == "NOT_LOADED"
        and el.y == 415 and item424() == nil,
        "坡道（Ramp）✗ 路線上有車 VEHICLE、有人 OCCUPIED、格上已有斜面 BLOCKED、伺服器某格沒載入 NOT_LOADED，都指那一格")
    do -- 路線格上原本就有的東西：站在地上的擋（會埋進斜面），地面上的覆蓋不擋
        local s9 = at(424, 421)
        s9.objects[#s9.objects + 1] = IsoObject.new(nil, s9, crateS)
        local cc, ec = item424()
        table.remove(s9.objects)
        s9.objects[#s9.objects + 1] = IsoObject.new(nil, s9, rugS)
        local cr = item424()
        table.remove(s9.objects)
        check(cc == "BLOCKED" and ec.y == 421 and Rules.classify(rugS) == "floorOverlay" and cr == nil,
            "坡道（Ramp）✗ 路線格上原本有容器：BLOCKED 指那一格；地毯（地面覆蓋）不擋")
        -- 最後一片往平台那條邊：這一層（坡頂往前那格）或上一層（坡頂正上方到平台）有牆、窗、門都擋。那條邊照持有它的
        -- 格子查（北、西邊由那格自己持有）：另一側格子不在（預覽時還沒載入）也查得到
        local function flagged(sq, name, f)
            local h = sq.has
            function sq:has(k) return (type(k) == "table" and k.name or k) == name or h(self, k) end
            local a, b = f()
            sq.has = h
            return a, b
        end
        local function prev424() return Check.item(P, "rp_01_0", 0, { 424, 430, 0 }, PV) end
        local top = at(424, 411)
        local cw, ew = flagged(top, "collideN", item424)
        local cd, ed = flagged(top, "doorN", item424)
        local up = esq(424, 411, 1)
        local cu, eu = flagged(up, "windowN", item424)
        check(cw == "BLOCKED" and ew.y == 411 and cd == "BLOCKED" and ed.y == 411 and cu == "BLOCKED" and eu.y == 411
            and item424() == nil,
            "坡道（Ramp）✗ 坡頂和平台之間有牆、門（這一層）或窗（上一層）：BLOCKED，指最後一片")
        -- 北向：牆在坡頂格（持有北邊），前方格、平台格不在（預覽）
        local aheadSq, deckSq = at(424, 410), at(424, 410, 1)
        squares["424,410,0"] = nil
        local pn, en = flagged(top, "collideN", prev424)
        squares["424,410,0"] = aheadSq
        squares["424,410,1"] = nil
        local pu, eu2 = flagged(up, "collideN", prev424)
        squares["424,410,1"], squares["424,411,1"] = deckSq, nil
        -- 南向（頭片 (424,411)，坡頂 (424,430)）：那條邊是前方格／平台格的北邊，坡頂正上方那格不在
        local deckS = esq(424, 431, 1)
        local function south() return Check.item(P, "rp_01_24", 0, { 424, 411, 0 }, PV) end
        local ps0 = south()
        local ps, es = flagged(deckS, "collideN", south)
        local pa, ea = flagged(at(424, 431), "collideN", south)
        squares["424,431,1"] = nil
        check(pn == "BLOCKED" and en.y == 411 and pu == "BLOCKED" and eu2.y == 411 and ps0 == nil and ps == "BLOCKED"
            and es.y == 430 and pa == "BLOCKED" and ea.y == 430 and prev424() == nil,
            "坡道（Ramp）✗ 預覽：出口那條邊的牆在持有那條邊的格子上（北向坡頂格、坡頂正上方；南向平台格、前方格），另一側格子還沒載入也 BLOCKED")
    end

    -- 放置（第 421 欄）：20 個一般物件、記號、頭片到最後一片的順序、平台、帳本整組一筆
    esq(421, 410, 1)
    -- 區域補推：這個情境的 tick 事件裡有別段留下的（跑不得），改數 Place.repush 排了幾格
    local realRepush, rPush = Place.repush, 0
    Place.repush = function(sq, kind) rPush = rPush + 1; return realRepush(sq, kind) end
    order = {}
    check(stock() == "200/200", "坡道（Ramp）起始材料 200/200")
    local okA = build(1, 421)
    Place.repush = realRepush
    check(rPush == 21, "坡道（Ramp）放置：20 片與補的平台那一格各排一次區域補推")
    local n, marked, plain = column(421)
    local A1, A10 = piece(421, 430, "rp_01_0"), piece(421, 421, "rp_01_9")
    local rec = Ledger.getRamp(421, 430, 0, "rp_01_0")
    check(okA == true and n == 20 and marked and plain and A1.sent and table.concat(order, " ") == table.concat(
        (function() local t = {} for i = 0, 19 do t[#t + 1] = "rp_01_" .. i end return t end)(), " ")
        and stock() == "180/180",
        "坡道（Ramp）放置：20 片都是一般物件（✗ 不是 IsoThumpable）、記號是頭片名、照頭片到最後一片的順序放、送給玩家、扣料")
    check(deck(421) ~= nil and Ledger.get(deck(421)) ~= nil and next(Ledger.get(deck(421))) == nil and rec
        and rec["Base.Plank"] == 20 and rec["Base.Nails"] == 20 and Place.refundOf(A10)
        and Place.refundOf(A10)["Base.Plank"] == 20 and Place.ramp(A10)
        and Dismantle.kindOf(A10) == "ramp",
        "坡道（Ramp）放置：平台在、帳本記平台空表；整組退料一筆（木板 20、釘子 20）記在頭片格，哪一片查都同一筆")
    -- ✗ 放到一半丟錯：撤回後格上 0 片、帳本沒有那筆、沒扣料
    esq(427, 410, 1)
    failAt = at(427, 421)
    local okU = build(2, 427)
    failAt = nil
    check(okU == false and column(427) == 0 and Ledger.getRamp(427, 430, 0, "rp_01_0") == nil and deck(427) == nil and stock() == "180/180",
        "坡道（Ramp）✗ 放到第 10 片丟錯：Place.undo 之後一片不留、帳本沒有那筆、沒有平台、沒扣料")

    -- 坡道格上只放格邊的東西（探針 2e）；地板換不掉坡道片、框選不把坡道片收成地板
    local s = at(421, 425)
    check(not Place.check("floor", floorS, s, P) and not Place.check("container", crateS, s, P)
        and not Place.check("furniture", crateS, s, P) and not Place.check("stairs", floorS, s, P, "bottom")
        and not Place.check("water", floorS, s, P) and not Place.check("ramp", spriteMap.rp_01_0, s, P)
        and Place.check("wall", wallS, s, P) and Place.check("container", crateS, at(419, 425), P),
        "坡道（Ramp）坡道格：✗ 地板、容器、家具、樓梯、水面、坡道都不放；牆（格邊）照放；平地照放容器")
    P.pos.x = 421.5
    check(Check.item(P, "rpf_01_0", 0, { 421, 425, 0 }) == "BLOCKED" and piece(421, 425, "rp_01_5") ~= nil,
        "坡道（Ramp）✗ 換地板：坡道格上蓋地板 BLOCKED，坡道片不被當成舊地板換掉")
    require "MinidoracatBuilder/Capture"
    local Cap = MinidoracatBuilder.Capture
    local res = { pieces = {}, n = 0, seen = {}, skip = {}, skipped = 0 }
    for i = 0, 19 do Cap.tile(res, "rp_01_" .. i, 421, 430 - i, 0, 0) end
    check(res.n == 1 and res.pieces[1].id == "rp_01_0" and res.pieces[1].y == 430 and res.skipped == 0,
        "坡道（Ramp）✗ 框選：整組只收頭片一項（坡道），其他片不收成地板、不算不收")
    local Names = MinidoracatBuilder.Names
    check(not Names or Names.of("rp_01_7", "ramp") == Names.of("rp_01_0", "ramp"), "坡道（Ramp）名稱：其他片照頭片叫")

    -- 拆除：點中間一片整組拆、照帳本退一次、平台跟著拆
    local okD, codeD = unbuild(3, 421, 421, "rp_01_9")
    local drop = P:getCurrentSquare().dropped
    check(okD == "dismantled" and column(421) == 0 and drop["Base.Plank"] == 20 and drop["Base.Nails"] == 20
        and Ledger.getRamp(421, 430, 0, "rp_01_0") == nil and deck(421) == nil and Ledger.get({ getSquare = function() return at(421, 410, 1) end,
            getSprite = function() return spriteMap.rp_01_23 end }) == nil,
        "坡道（Ramp）拆除：點第 10 片整組 20 片都拆、照帳本退一次（木板 20）、帳本清掉、平台拆掉（" .. tostring(codeD) .. "）")
    -- ✗ 舊版當地板蓋的坡道片（IsoThumpable、isFloor）照地板拆
    local old = { class = "IsoThumpable", md = { builderEntry = "rp_01_5" } }
    function old:getSprite() return spriteMap.rp_01_5 end
    function old:hasModData() return true end
    function old:getModData() return self.md end
    function old:isFloor() return true end
    function old:isDismantable() return true end
    check(Dismantle.kindOf(old) == "floor" and not Place.ramp(old), "坡道（Ramp）✗ 舊版當地板蓋的坡道片（IsoThumpable）照地板拆")
    if Names then -- 假的 getText 不帶參數，換成帶參數的才比得出編號；名稱有快取，前後各清一次
        local realText = getText
        getText = function(k, ...) return k .. "(" .. table.concat({ ... }, ",") .. ")" end
        Names.reset()
        local f5, f6 = Names.of("rp_01_5", "floor"), Names.of("rp_01_6", "floor")
        local r5, r0 = Names.of("rp_01_5", "ramp"), Names.of("rp_01_0", "ramp")
        getText = realText
        Names.reset()
        check(f5 ~= f6 and f5 ~= r5 and r5 == r0,
            "坡道（Ramp）名稱：舊版當地板蓋的坡道片照自己的編號叫（各片不同名）；坡道那一組照舊照頭片叫")
    end

    -- 拆除的反面：混了不是本 MOD 的片、少一片、缺片那格沒載入（殘組照拆剩下本 MOD 的片、不退料；沒載入照舊拒絕）
    esq(442, 410, 1)
    build(4, 442)
    local D1, D15 = piece(442, 430, "rp_01_0"), piece(442, 416, "rp_01_14")
    local function has(list, o) for _, v in ipairs(list) do if v == o then return true end end return false end
    D15.md.builderEntry = nil
    local pf = Dismantle.plan(D1, "ramp")
    D15.md.builderEntry = "rp_01_0"
    local hold = at(442, 416)
    hold.removeHere(D15)
    local pm = Dismantle.plan(piece(442, 420, "rp_01_10"), "ramp")
    squares["442,416,0"] = nil
    local pu = Dismantle.plan(D1, "ramp")
    local okU2, codeU2 = unbuild(5, 442, 430, "rp_01_0")
    squares["442,416,0"] = hold
    hold.objects[#hold.objects + 1] = D15
    local pok = Dismantle.plan(D1, "ramp")
    check(#pf.remove == 20 and has(pf.remove, D15) and not pf.partial and pf.refund[1] == D1 and pf.incomplete == nil
        and #pm.remove == 19 and pm.partial and pm.refund[1] ~= nil and pm.incomplete == nil and not pm.foreign,
        "坡道（Ramp）收片照位置與圖名：✗ 清掉一片記號不算殘組（20 片）；少一片時 remove 是剩下的 19 片、標殘組")
    check(pu.incomplete == "NOT_LOADED" and okU2 == "dismantleSkipped" and codeU2 == "NOT_LOADED" and column(442) == 20
        and next(P:getCurrentSquare().dropped) == nil and Ledger.getRamp(442, 430, 0, "rp_01_0") ~= nil,
        "坡道（Ramp）✗ 缺片那格沒載入：照舊 NOT_LOADED，一片都不拆、不退料、帳本還在")
    check(#pok.remove == 20 and pok.refund[1] == D1 and pok.incomplete == nil and not pok.foreign and #pok.landing == 1,
        "坡道（Ramp）完整：20 片加平台，照頭片那筆退")
    -- 完整的一組有一片記號被清掉：照常整組拆、退一次，帳本刪掉
    D15.md.builderEntry = nil
    local okP, _ = unbuild(6, 442, 430, "rp_01_0")
    local dropP = P:getCurrentSquare().dropped
    check(okP == "dismantled" and dropP["Base.Plank"] == 20 and column(442) == 0 and piece(442, 416, "rp_01_14") == nil
        and Ledger.getRamp(442, 430, 0, "rp_01_0") == nil and deck(442) == nil,
        "坡道（Ramp）✗ 清掉一片記號後拆：照常整組 20 片都拆、退一次（木板 20）、帳本刪掉")
    -- 少一片（被別的方式拆掉，帳本跟著清）：點中間任一片照拆剩下 19 片、0 退料
    esq(430, 410, 1)
    build(15, 430)
    at(430, 416):transmitRemoveItemFromSquare(piece(430, 416, "rp_01_14"))
    local voided = Ledger.getRamp(430, 430, 0, "rp_01_0")
    local okM = unbuild(16, 430, 420, "rp_01_10")
    check(voided and next(voided) == nil and okM == "dismantled" and column(430) == 0
        and next(P:getCurrentSquare().dropped) == nil and Ledger.getRamp(430, 430, 0, "rp_01_0") == nil and deck(430) == nil,
        "坡道（Ramp）殘組（少一片）：那一筆作廢成空表（鍵留著）；點任一片拆掉剩下 19 片和平台、不退料，最後一片拆掉才刪鍵")

    -- 平台留著：蓋之前那格已經有地板（不是本 MOD 補的）、上面有別的東西
    esq(433, 410, 1):addFloor("rp_01_23")
    esq(436, 410, 1)
    local okB = build(6, 433)
    local okC = build(7, 436)
    at(436, 410, 1).objects[#at(436, 410, 1).objects + 1] = { name = "chair" }
    unbuild(8, 433, 430, "rp_01_0")
    unbuild(9, 436, 430, "rp_01_0")
    -- 平台格原本就有 STAIR_FLOOR（玩家自己鋪的、帳本沒記）：deckOf 認這張圖，但不是本 MOD 補的，拆坡道時一樣留著
    do
        esq(437, 410, 1):addFloor(Entry.STAIR_FLOOR)
        for _ = 1, 20 do P.inv:add(item("Base.Plank")); P.inv:add(item("Base.Nails")) end -- 退料掉在地上，背包照舊
        local okS = build(120, 437)
        local okSU = unbuild(121, 437, 430, "rp_01_0")
        local keptS
        for _, o in ipairs(at(437, 410, 1).objects) do if o.name == Entry.STAIR_FLOOR then keptS = o end end
        check(okB and okC and column(433) == 0 and column(436) == 0 and deck(433) ~= nil and deck(436) ~= nil
            and okS and okSU == "dismantled" and column(437) == 0 and keptS ~= nil and #at(437, 410, 1).objects == 1,
            "坡道（Ramp）✗ 平台那格原本就有地板（坡道平台圖或 STAIR_FLOOR）、平台上有別的東西：拆坡道時平台留著")
    end

    -- ✗ 拆地板：坡道片底下本 MOD 的地板拆掉後，坡道片還在（格上還有 solidfloor，不補泥土、不 clearFloor）
    esq(439, 410, 1)
    build(10, 439)
    local fsq = at(439, 430)
    local fl = { class = "IsoThumpable", md = { builderEntry = "rpf_01_0" }, mats = { ["Base.Plank"] = "1" } }
    function fl:getSprite() return floorS end
    function fl:getProperties() return floorS:getProperties() end
    function fl:getSquare() return fsq end
    function fl:hasModData() return true end
    function fl:getModData() return self.md end
    function fl:isFloor() return true end
    function fl:isDismantable() return true end
    function fl:getBuildMaterials() return self.mats end
    function fl:hasBuildMaterials() return true end
    function fl:isObjectNoContainerOrEmpty() return true end
    function fl:isBarricaded() return false end
    function fl:getTextureName() return "rpf_01_0" end
    function fl:getType() return T.normal end
    function fl:isStairsObject() return false end
    function fl:getAttachedAnimSprite() return nil end
    function fl:getSpriteGridObjectsIncludingSelf() return javaList({ self }) end
    function fl:isConnectedSpriteGridObject(o) return o == self end
    table.insert(fsq.objects, 1, fl)
    if Floors then Floors.put(fl, { ["Base.Plank"] = 1 }) end
    local okF = unbuild(11, 439, 430, "rpf_01_0")
    check(okF == "dismantled" and piece(439, 430, "rp_01_0") ~= nil and column(439) == 20 and Ledger.getRamp(439, 430, 0, "rp_01_0") ~= nil,
        "坡道（Ramp）✗ 拆地板：拆掉坡道片底下的地板，坡道片不被當成地板一起拆、帳本那筆還在")

    for _ = 1, 200 do P.inv:add(item("Base.Plank")); P.inv:add(item("Base.Nails")) end
    -- 伺服器每人 5 秒 20 個請求（Server 的 rateOk），假時鐘不走：每一段換一個連線編號
    local pid = 9601
    local function fresh()
        pid = pid + 1
        function P:getOnlineID() return pid end
    end
    -- 帳本沒有那一筆（地圖原有的坡道寫上記號）：不拆，世界與帳本不動
    do
        fresh()
        local function mapPiece(x, y, name)
            local sq = at(x, y)
            local o = IsoObject.new(nil, sq, spriteMap[name])
            o.md.builderEntry = "rp_01_0"
            sq.objects[#sq.objects + 1] = o
            return o
        end
        for i = 0, 19 do mapPiece(445, 430 - i, "rp_01_" .. i) end
        local okW, codeW = unbuild(40, 445, 430, "rp_01_0")
        local whole = column(445)
        at(445, 425):transmitRemoveItemFromSquare(piece(445, 425, "rp_01_5")) -- 大錘砸掉一片：沒有那一筆，不新增
        local okH, codeH = unbuild(41, 445, 420, "rp_01_10")
        check(okW == "dismantleSkipped" and codeW == "NOT_OURS" and whole == 20 and okH == "dismantleSkipped"
            and codeH == "NOT_OURS" and column(445) == 19 and Ledger.getRamp(445, 430, 0, "rp_01_0") == nil
            and next(P:getCurrentSquare().dropped) == nil,
            "坡道（Ramp）✗ 地圖坡道寫上記號、帳本沒有那一筆：整組或缺一片都 NOT_OURS、一片不拆，帳本不多一筆")
    end
    -- 記號改過再用大錘砸一片：照圖與位置作廢那一筆，剩下的照拆、不退料
    do
        fresh()
        esq(427, 410, 1)
        build(42, 427)
        local hit = piece(427, 416, "rp_01_14")
        hit.md.builderEntry = "something_else"
        at(427, 416):transmitRemoveItemFromSquare(hit)
        local v = Ledger.getRamp(427, 430, 0, "rp_01_0")
        local okS = unbuild(43, 427, 430, "rp_01_0")
        check(v and next(v) == nil and okS == "dismantled" and column(427) == 0 and next(P:getCurrentSquare().dropped) == nil
            and Ledger.getRamp(427, 430, 0, "rp_01_0") == nil,
            "坡道（Ramp）✗ 記號改過的片被砸：那一筆照樣作廢（不留整筆退料），剩下的拆光、不退料、最後刪鍵")
    end
    -- 帳本寫不進去（還沒建、滿了）、平台引擎半途出錯回 nil：整組失敗、一片不留、不扣料
    do
        fresh()
        local start = stock()
        local inst = Ledger.instance
        Ledger.instance = nil
        esq(427, 410, 1)
        local okN = build(44, 427)
        Ledger.instance = inst
        local nN, dN = column(427), deck(427)
        local Store = MinidoracatBuilder.Store
        local realPut = Store.put
        Store.put = function() return false end
        esq(427, 410, 1)
        local okF = build(45, 427)
        Store.put = realPut
        check(okN == false and nN == 0 and dN == nil and okF == false and column(427) == 0 and deck(427) == nil
            and Ledger.getRamp(427, 430, 0, "rp_01_0") == nil and stock() == start,
            "坡道（Ramp）✗ 帳本還沒建、帳本滿了：放置失敗，20 片與平台都不留、不扣料")
        local s4 = esq(421, 410, 1) -- 另一欄：不受上面那一條的結果影響
        local af = s4.addFloor
        function s4:addFloor(name) af(self, name) return nil end -- 引擎例外被吞：地板已加進格子、回 nil
        local okL = build(46, 421)
        check(okL == false and column(421) == 0 and deck(421) == nil and Ledger.getRamp(421, 430, 0, "rp_01_0") == nil
            and stock() == start,
            "坡道（Ramp）✗ 平台 addFloor 加進格子卻回 nil：整組失敗，20 片、平台、帳本都不留，不扣料")
    end
    -- 安全屋：平台在別人的安全屋 → SAFEHOUSE、什麼都不放；殘組剩下的某片在別人的安全屋 → 一片都不拆
    do
        fresh()
        local start = stock()
        local s5 = esq(424, 410, 1)
        s5.owner = "other"
        local okO, codeO = build(47, 424)
        check(not okO and codeO == "SAFEHOUSE" and column(424) == 0 and deck(424) == nil and stock() == start,
            "坡道（Ramp）✗ 平台在別人的安全屋：SAFEHOUSE，什麼都不放")
        s5.owner = nil
        build(48, 424)
        at(424, 416):transmitRemoveItemFromSquare(piece(424, 416, "rp_01_14"))
        at(424, 425).owner = "other"
        local okQ, codeQ = unbuild(49, 424, 420, "rp_01_10")
        local left = column(424)
        at(424, 425).owner = nil
        local okR2 = unbuild(50, 424, 420, "rp_01_10")
        check(okQ ~= "dismantled" and codeQ == "SAFEHOUSE" and left == 19 and okR2 == "dismantled" and column(424) == 0,
            "坡道（Ramp）✗ 殘組剩下的一片在別人的安全屋：SAFEHOUSE，一片都不拆")
    end
    -- 共用平台：兩組坡道（北向 420 欄、西向 410 列）通到同一格平台，先拆的留平台、最後一組拆掉才收；樓梯頂通到也留
    do
        fresh()
        esq(420, 410, 1)
        local okA2 = build(51, 420)
        P.pos.y = 410.5
        P.pos.x = 440.5
        local codeB = intentCode(52, "rp_01_48", { 440, 410, 0, 0 })
        sent = {}
        local okB2 = codeB == nil and Server.complete(P, 52, 1)
        P.pos.y = 431.5
        unbuild(53, 420, 430, "rp_01_0")
        local kept = deck(420) ~= nil
        P.pos.y = 410.5
        local okB3 = unbuild(54, 440, 410, "rp_01_48")
        P.pos.y = 431.5
        local westLeft = 0
        for i = 0, 19 do if piece(440 - i, 410, "rp_01_" .. (48 + i)) then westLeft = westLeft + 1 end end
        check(okA2 and okB2 and kept and okB3 == "dismantled" and westLeft == 0 and deck(420) == nil,
            "坡道（Ramp）✗ 兩組坡道共用平台：拆第一組平台留著，拆最後一組才收")
        esq(418, 410, 1)
        build(55, 418)
        esq(419, 410, 0, { flags = { stairsTW = true } }) -- 往西爬的樓梯頂片在平台東邊
        unbuild(56, 418, 430, "rp_01_0")
        check(column(418) == 0 and deck(418) ~= nil, "坡道（Ramp）✗ 樓梯頂也通到平台：拆坡道時平台留著")
    end
    -- 樓梯那一邊：坡道最上面那片通到樓梯平台時，拆樓梯不收平台
    do
        fresh()
        local tsq, lsq, rsq = at(445, 434), esq(444, 434, 1), at(444, 435)
        local stairSpr = sprite("rps_01_0", 9795, { type = T.stairsTW })
        local st = { class = "IsoThumpable", md = { builderEntry = "rps_01_0" } }
        function st:getSprite() return stairSpr end
        function st:getSquare() return tsq end
        function st:hasModData() return true end
        function st:getModData() return self.md end
        function st:isStairsObject() return true end
        function st:isFloor() return false end
        local land = { class = "IsoObject" }
        function land:getSprite() return { getName = function() return Entry.STAIR_FLOOR end } end
        function land:isStairsObject() return false end
        lsq.objects[#lsq.objects + 1] = land
        local realGet = buildUtil.getStairObjects
        buildUtil.getStairObjects = function(o) return { o } end
        local alone = Dismantle.plan(st, "stairs")
        rsq.objects[#rsq.objects + 1] = IsoObject.new(nil, rsq, spriteMap.rp_01_19)
        local shared = Dismantle.plan(st, "stairs")
        buildUtil.getStairObjects = realGet
        table.remove(rsq.objects)
        check(alone.landing and alone.landing[1] == land and shared.landing == nil,
            "坡道（Ramp）✗ 坡道頂也通到樓梯平台：拆樓梯時平台不收（沒有坡道時照收）")
    end

    -- 伺服器找坡道片照圖與位置（不看記號）：被點那片、整組的記號清掉照常拆；地圖坡道照圖找得到、帳本沒有 → NOT_OURS
    do
        fresh()
        build(60, 427)
        piece(427, 420, "rp_01_10").md = {}
        local okC = unbuild(61, 427, 420, "rp_01_10")
        local dropC = P:getCurrentSquare().dropped["Base.Plank"]
        local goneC = column(427) == 0 and Ledger.getRamp(427, 430, 0, "rp_01_0") == nil and deck(427) == nil
        build(62, 427)
        for i = 0, 19 do piece(427, 430 - i, "rp_01_" .. i).md = {} end
        P:getCurrentSquare().dropped = {}
        sent = {}
        Server.dismantleIntent(P, { n = 63, t = { 427, 425, 0, "rp_01_5" } })
        local dur = Server.dismantleDuration(P, 63, 1)
        sent = {}
        Server.dismantle(P, 63, 1)
        local okA = sent[#sent] and sent[#sent].cmd
        local dropA = P:getCurrentSquare().dropped["Base.Plank"]
        check(okC == "dismantled" and dropC == 20 and goneC and dur == Entry.duration("ramp", P) and dur > 1
            and okA == "dismantled" and dropA == 20 and column(427) == 0 and Ledger.getRamp(427, 430, 0, "rp_01_0") == nil,
            "坡道（Ramp）✗ 被點那片、整組的記號都清掉：伺服器照圖與位置找到，施工時間照坡道，整組拆、退一次（木板 20）")
        for i = 0, 19 do
            local o = piece(445, 430 - i, "rp_01_" .. i)
            if o then o.md = {} end
        end
        local okN, codeN = unbuild(64, 445, 420, "rp_01_10")
        check(okN == "dismantleSkipped" and codeN == "NOT_OURS" and column(445) == 19,
            "坡道（Ramp）✗ 地圖坡道（沒有記號、帳本沒有那一筆）：伺服器照圖找到，NOT_OURS、一片不拆")
    end
    -- 共用平台的圖不同（先蓋的那組補、後蓋的不補）：最後一組拆掉時照樣收平台。引擎看到格上有地板就不補（sq:has 照格上
    -- 物件算），假格子的 has 只看旗標，這裡補上
    do
        fresh()
        local function floorAware(sq)
            local h = sq.has
            function sq:has(k)
                if k == F.solidfloor then
                    for _, o in ipairs(self.objects) do
                        local s = o.getSprite and o:getSprite()
                        if s and s:getProperties():has(F.solidfloor) then return true end
                    end
                end
                return h(self, k)
            end
            return sq
        end
        local function west(n)
            P.pos.x, P.pos.y = 440.5, 410.5
            local c = intentCode(n, "rp_01_48", { 440, 410, 0, 0 })
            sent = {}
            local ok = c == nil and Server.complete(P, n, 1)
            P.pos.y = 431.5
            return ok
        end
        local function north(n)
            P.pos.x = 420.5
            local c = intentCode(n, "rn_01_0", { 420, 430, 0, 0 })
            sent = {}
            return c == nil and Server.complete(P, n, 1)
        end
        local function unWest(n)
            P.pos.y = 410.5
            local ok = unbuild(n, 440, 410, "rp_01_48")
            P.pos.y = 431.5
            return ok
        end
        -- 西向 rp_01（平台 rp_01_23）先蓋、北向 rn_01（平台圖退回 STAIR_FLOOR）後蓋；先拆西向，再拆北向
        local dsq = floorAware(esq(420, 410, 1))
        local b1, b2 = west(70), north(71)
        local d1 = dsq.objects[1]
        local one = #dsq.objects == 1 and d1.name == "rp_01_23" and Ledger.get(d1) ~= nil
        local u1 = unWest(72)
        local kept1 = dsq.objects[1] == d1
        local u2 = unbuild(73, 420, 430, "rn_01_0")
        check(b1 and b2 and one and u1 == "dismantled" and kept1 and u2 == "dismantled" and #dsq.objects == 0
            and Ledger.get(d1) == nil,
            "坡道（Ramp）✗ 兩組平台圖不同的坡道共用平台（rp_01_23 那組先蓋先拆）：最後拆的那組照樣收平台、帳本清掉")
        -- 反過來：北向先蓋（平台 STAIR_FLOOR）、西向後蓋；先拆北向，再拆西向
        dsq = floorAware(esq(420, 410, 1))
        local c1, c2 = north(74), west(75)
        local d2 = dsq.objects[1]
        local two = #dsq.objects == 1 and d2.name == Entry.STAIR_FLOOR and Ledger.get(d2) ~= nil
        local v1 = unbuild(76, 420, 430, "rn_01_0")
        local kept2 = dsq.objects[1] == d2
        local v2 = unWest(77)
        check(c1 and c2 and two and v1 == "dismantled" and kept2 and v2 == "dismantled" and #dsq.objects == 0
            and Ledger.get(d2) == nil,
            "坡道（Ramp）✗ 反過來（STAIR_FLOOR 平台那組先蓋先拆）：最後拆的那組照樣收平台、帳本清掉")
        -- 坡道與樓梯：先蓋的坡道補了 rp_01_23、先拆了（第 418 欄，平台因樓梯頂留著）→ 拆樓梯時收它
        local tsq, d418 = at(419, 410), deck(418)
        local st = { class = "IsoThumpable", md = { builderEntry = "rps_01_0" } }
        local stairSpr = sprite("rps_01_1", 9796, { type = T.stairsTW })
        function st:getSprite() return stairSpr end
        function st:getSquare() return tsq end
        function st:hasModData() return true end
        function st:getModData() return self.md end
        function st:isStairsObject() return true end
        function st:isFloor() return false end
        local realGet = buildUtil.getStairObjects
        buildUtil.getStairObjects = function(o) return { o } end
        local sp = Dismantle.plan(st, "stairs")
        buildUtil.getStairObjects = realGet
        check(d418 and sp.landing and sp.landing[1] == d418 and Ledger.get(d418) ~= nil,
            "坡道（Ramp）✗ 坡道先拆、平台（rp_01_23）因樓梯頂留著：拆樓梯時收它（帳本有那筆，伺服器照帳本拆）")
        -- 樓梯先拆、留下的 STAIR_FLOOR 平台（帳本有）→ 拆接在上面的坡道時收它
        local ssq = floorAware(esq(427, 410, 1))
        local land = ssq:addFloor(Entry.STAIR_FLOOR)
        Ledger.put(land, {})
        local okB = build(78, 427)
        local only = #ssq.objects == 1
        local okU = unbuild(79, 427, 430, "rp_01_0")
        check(okB and only and okU == "dismantled" and #ssq.objects == 0 and Ledger.get(land) == nil and column(427) == 0,
            "坡道（Ramp）✗ 樓梯先拆、平台（STAIR_FLOOR）留著：拆接在上面的坡道時收它、帳本清掉")
    end
    -- 移除事件：同組有片所在的格子沒載入時只作廢、不刪鍵；作廢寫不進去時留著原筆、不刪鍵（剩下的照殘組拆、不退料）
    do
        fresh()
        esq(427, 410, 1)
        build(80, 427)
        -- 除了第 6 片（y=425）和要砸的第 15 片（y=416）都先悄悄拿掉（不觸發事件），再讓第 6 片那格沒載入：
        -- 載入的格子裡已經沒有同組的片，只剩沒載入那格說不準
        for i = 0, 19 do
            if i ~= 5 and i ~= 14 then
                local sq, o = at(427, 430 - i), piece(427, 430 - i, "rp_01_" .. i)
                for k = #sq.objects, 1, -1 do if sq.objects[k] == o then table.remove(sq.objects, k) end end
            end
        end
        local far = at(427, 425)
        squares["427,425,0"] = nil
        at(427, 416):transmitRemoveItemFromSquare(piece(427, 416, "rp_01_14"))
        squares["427,425,0"] = far
        local v = Ledger.getRamp(427, 430, 0, "rp_01_0")
        local okV = unbuild(81, 427, 425, "rp_01_5")
        check(v and next(v) == nil and okV == "dismantled" and column(427) == 0 and Ledger.getRamp(427, 430, 0, "rp_01_0") == nil,
            "坡道（Ramp）✗ 某片被砸時同組剩下的片所在的格子沒載入：只作廢（空表）、不刪鍵，之後照殘組拆光")
        esq(427, 410, 1)
        build(82, 427)
        local Store = MinidoracatBuilder.Store
        local realPut = Store.put
        Store.put = function() return false end
        at(427, 416):transmitRemoveItemFromSquare(piece(427, 416, "rp_01_14"))
        Store.put = realPut
        local kept = Ledger.getRamp(427, 430, 0, "rp_01_0")
        local okK = unbuild(83, 427, 420, "rp_01_10")
        check(kept and kept["Base.Plank"] == 20 and okK == "dismantled" and next(P:getCurrentSquare().dropped) == nil
            and column(427) == 0 and Ledger.getRamp(427, 430, 0, "rp_01_0") == nil,
            "坡道（Ramp）✗ 作廢寫不進帳本：留著原筆、不刪鍵；剩下的照殘組拆光、不退料")
    end
    -- 樓梯平台 addFloor 加進格子卻回 nil：整組失敗，三片、平台都不留，不扣料
    do
        fresh()
        for _ = 1, 20 do P.inv:add(item("Base.Plank")); P.inv:add(item("Base.Nails")) end -- 前面拆掉的退料掉在地上
        local start = stock()
        local lsq = esq(429, 433, 1)
        local af = lsq.addFloor
        function lsq:addFloor(name) af(self, name) return nil end
        P.pos.x, P.pos.y = 430.5, 432.5
        local c = intentCode(84, "rpt_01_0", { 430, 433, 0, 0 })
        sent = {}
        local ok = c == nil and Server.complete(P, 84, 1)
        local code = sent[1] and sent[1].args and sent[1].args.code
        P.pos.y = 431.5
        local left = #at(430, 433).objects + #at(431, 433).objects + #at(432, 433).objects + #lsq.objects
        check(c == nil and ok == false and code == "INTERNAL" and left == 0 and stock() == start,
            "坡道（Ramp）✗ 樓梯平台 addFloor 加進格子卻回 nil：整組失敗（INTERNAL），三片、平台都不留，不扣料")
    end

    -- 帳本鍵含方向：頭片不在時，同一格可以放別方向的頭片，兩組的頭片格相同、帳本各自一筆
    do
        for x = 460, 516 do for y = 399, 436 do if not at(x, y) then esq(x, y, 0) end end end
        for _ = 1, 60 do P.inv:add(item("Base.Plank")); P.inv:add(item("Base.Nails")) end
        local function east(n, x, y)
            P.pos.x, P.pos.y = x + 0.5, y + 1.5
            local c = intentCode(n, "rp_01_72", { x, y, 0, 0 })
            sent = {}
            return c == nil and Server.complete(P, n, 1)
        end
        local function unAt(n, x, y, name)
            P.pos.y = y + 1.5
            local ok, code = unbuild(n, x, y, name)
            P.pos.y = 431.5
            return ok, code
        end
        local function eastLeft(x, y)
            local k = 0
            for i = 0, 19 do if piece(x + i, y, "rp_01_" .. (72 + i)) then k = k + 1 end end
            return k
        end
        -- 自己的北向坡道頭片被別的方式移走（那一筆作廢），同一格蓋東向坡道；拆北向殘組不動東向那一筆
        fresh()
        esq(470, 410, 1)
        esq(490, 430, 1)
        local okN = build(90, 470)
        at(470, 430):transmitRemoveItemFromSquare(piece(470, 430, "rp_01_0"))
        local okE = east(91, 470, 430)
        local eRec = Ledger.getRamp(470, 430, 0, "rp_01_72")
        local nRec = Ledger.getRamp(470, 430, 0, "rp_01_0")
        fresh()
        local uN = unAt(92, 470, 420, "rp_01_10")
        local northLeft = 0
        for i = 1, 19 do if piece(470, 430 - i, "rp_01_" .. i) then northLeft = northLeft + 1 end end
        local eAfter = Ledger.getRamp(470, 430, 0, "rp_01_72")
        fresh()
        local uE = unAt(93, 470, 430, "rp_01_72")
        local dropE = P:getCurrentSquare().dropped["Base.Plank"]
        check(okN and okE and nRec and next(nRec) == nil and eRec and eRec["Base.Plank"] == 20 and uN == "dismantled"
            and northLeft == 0 and eAfter == eRec and uE == "dismantled" and dropE == 20 and eastLeft(470, 430) == 0
            and Ledger.getRamp(470, 430, 0, "rp_01_72") == nil and Ledger.getRamp(470, 430, 0, "rp_01_0") == nil,
            "坡道（Ramp）✗ 北向殘組和同一頭片格的東向新組：拆殘組不動東向那一筆，東向照常整組拆、退一次（木板 20）")
        -- 地圖上的北向坡道片（沒有頭片、沒有記號、帳本沒有）＋在它推算的頭片格蓋東向坡道：地圖的片 NOT_OURS、一片不動
        for i = 1, 19 do
            local sq = at(495, 420 - i)
            sq.objects[#sq.objects + 1] = IsoObject.new(nil, sq, spriteMap["rp_01_" .. i])
        end
        esq(515, 420, 1)
        fresh()
        local okC = east(94, 495, 420)
        local cRec = Ledger.getRamp(495, 420, 0, "rp_01_72")
        fresh()
        local uM, cM = unAt(95, 495, 410, "rp_01_10")
        local mapLeft = 0
        for i = 1, 19 do if piece(495, 420 - i, "rp_01_" .. i) then mapLeft = mapLeft + 1 end end
        local cAfter = Ledger.getRamp(495, 420, 0, "rp_01_72")
        fresh()
        local uC = unAt(96, 495, 420, "rp_01_72")
        local dropC = P:getCurrentSquare().dropped["Base.Plank"]
        check(okC and cRec and uM == "dismantleSkipped" and cM == "NOT_OURS" and mapLeft == 19 and cAfter == cRec
            and Ledger.getRamp(495, 420, 0, "rp_01_0") == nil and uC == "dismantled" and dropC == 20 and eastLeft(495, 420) == 0,
            "坡道（Ramp）✗ 地圖坡道殘片（沒有頭片）＋頭片格蓋了別方向的本 MOD 坡道：拆地圖的片 NOT_OURS、19 片都在、那組帳本不變，那組照常拆")
        P.pos.x, P.pos.y = 421.5, 431.5
    end

    -- 帳本鍵含頭片圖名：同方向、同頭片格，但圖塊包或長度不同的兩組（rp_01 北向 20 片、rh_01 北向 5 片）各自一筆
    do
        local function un(n, x, y, name)
            P.pos.y = y + 1.5
            local ok, code = unbuild(n, x, y, name)
            P.pos.y = 431.5
            return ok, code
        end
        local function short(n, x)
            P.pos.x, P.pos.y = x + 0.5, 431.5
            local c = intentCode(n, "rh_01_0", { x, 430, 0, 0 })
            sent = {}
            return c == nil and Server.complete(P, n, 1)
        end
        local function count(x, from, to)
            local k = 0
            for i = from, to do if piece(x, 430 - i, "rp_01_" .. i) then k = k + 1 end end
            return k
        end
        local function shortLeft(x)
            local k = 0
            for i = 0, 4 do if piece(x, 430 - i, "rh_01_" .. i) then k = k + 1 end end
            return k
        end
        for _ = 1, 40 do P.inv:add(item("Base.Plank")); P.inv:add(item("Base.Nails")) end
        -- 地圖上的北向 rp_01 少了頭片那一段（第 1–5 片），在推算的頭片格蓋一組 rh_01；拆地圖的片 NOT_OURS、一片不動
        for i = 5, 19 do
            local sq = at(500, 430 - i)
            sq.objects[#sq.objects + 1] = IsoObject.new(nil, sq, spriteMap["rp_01_" .. i])
        end
        esq(500, 425, 1)
        fresh()
        local okH = short(130, 500)
        local hRec = Ledger.getRamp(500, 430, 0, "rh_01_0")
        local hPlank = hRec and hRec["Base.Plank"]
        fresh()
        local uM, cM = un(131, 500, 420, "rp_01_10")
        local mapLeft, hAfter = count(500, 5, 19), Ledger.getRamp(500, 430, 0, "rh_01_0")
        fresh()
        local uH = un(132, 500, 430, "rh_01_0")
        local dropH = P:getCurrentSquare().dropped["Base.Plank"]
        check(okH and hPlank and hPlank > 0 and uM == "dismantleSkipped" and cM == "NOT_OURS" and mapLeft == 15
            and hAfter == hRec and hAfter["Base.Plank"] == hPlank and uH == "dismantled" and dropH == hPlank and shortLeft(500) == 0
            and Ledger.getRamp(500, 430, 0, "rh_01_0") == nil and Ledger.getRamp(500, 430, 0, "rp_01_0") == nil,
            "坡道（Ramp）✗ 地圖北向坡道少了頭片那段＋頭片格蓋了另一組北向短坡道：拆地圖的片 NOT_OURS、15 片都在、短坡道那筆不變，之後照常整組退料")
        -- 自己的北向 rp_01 少了頭片那段（那一筆作廢），同一格蓋 rh_01；拆殘組不動 rh_01 那一筆，之後照常整組退料
        esq(505, 410, 1)
        esq(505, 425, 1)
        fresh()
        P.pos.x = 505.5
        local okN = build(133, 505)
        for i = 0, 4 do at(505, 430 - i):transmitRemoveItemFromSquare(piece(505, 430 - i, "rp_01_" .. i)) end
        local nRec = Ledger.getRamp(505, 430, 0, "rp_01_0")
        fresh()
        local okH2 = short(134, 505)
        local h2Rec = Ledger.getRamp(505, 430, 0, "rh_01_0")
        local h2Plank = h2Rec and h2Rec["Base.Plank"]
        fresh()
        local uN = un(135, 505, 420, "rp_01_10")
        local nLeft, h2After = count(505, 5, 19), Ledger.getRamp(505, 430, 0, "rh_01_0")
        fresh()
        local uH2 = un(136, 505, 430, "rh_01_0")
        local dropH2 = P:getCurrentSquare().dropped["Base.Plank"]
        check(okN and nRec and next(nRec) == nil and okH2 and h2Plank and h2Plank > 0 and uN == "dismantled" and nLeft == 0
            and Ledger.getRamp(505, 430, 0, "rp_01_0") == nil and h2After == h2Rec and h2After["Base.Plank"] == h2Plank
            and uH2 == "dismantled" and dropH2 == h2Plank and shortLeft(505) == 0 and Ledger.getRamp(505, 430, 0, "rh_01_0") == nil,
            "坡道（Ramp）✗ 自己的北向殘組＋同一頭片格的另一組北向短坡道：拆殘組不動短坡道那一筆，短坡道之後照常整組退料")
        P.pos.x, P.pos.y = 421.5, 431.5
    end

    -- 帳本鍵的前綴在最前面：平台圖名是「ramp:<頭片名>」時，記在某組坡道的頭片格也不會和那組坡道同鍵
    do
        local function unZ(n, x, y, z, name)
            P.pos.x, P.pos.y, P.pos.z = x + 0.5, y + 1.5, z
            P:getCurrentSquare().dropped = {}
            sent = {}
            Server.dismantleIntent(P, { n = n, t = { x, y, z, name } })
            local cmd, code = sent[1] and sent[1].cmd, sent[1] and sent[1].args.code
            if cmd == "dismantleAccepted" then
                sent = {}
                Server.dismantle(P, n, 1)
                local last = sent[#sent]
                cmd, code = last and last.cmd, last and last.args.code
            end
            P.pos.x, P.pos.y, P.pos.z = 421.5, 431.5, 0
            return cmd, code
        end
        local function weirdDeck()
            for _, o in ipairs(at(510, 430, 1).objects) do
                if (o.name or (o.spr and o.spr:getName())) == "ramp:rp_01_0" then return o end
            end
            return nil
        end
        local function mapLeft()
            local k = 0
            for i = 1, 19 do
                for _, o in ipairs(at(510, 430 - i, 1).objects) do
                    if o.spr and o.spr:getName() == "rp_01_" .. i then k = k + 1 end
                end
            end
            return k
        end
        for _ = 1, 20 do P.inv:add(item("Base.Plank")); P.inv:add(item("Base.Nails")) end
        -- 地圖在 z=1 留著北向 rp_01 第 1–19 片（頭片格 (510,430,1) 空著）
        for i = 1, 19 do
            local sq = esq(510, 430 - i, 1)
            sq.objects[#sq.objects + 1] = IsoObject.new(nil, sq, spriteMap["rp_01_" .. i])
        end
        esq(510, 430, 1)
        -- 本工具在 (511,430,0) 蓋朝西的 ramp:rp_01_1：平台 ramp:rp_01_0 補在 (510,430,1)，帳本記一筆空表
        fresh()
        P.pos.x, P.pos.y = 511.5, 431.5
        local c = intentCode(150, "ramp:rp_01_1", { 511, 430, 0, 0 })
        sent = {}
        local okW = c == nil and Server.complete(P, 150, 1)
        local wd = weirdDeck()
        local wdRec = wd and Ledger.get(wd)
        local wRec = Ledger.getRamp(511, 430, 0, "ramp:rp_01_1")
        local wPlank = wRec and wRec["Base.Plank"]
        -- 拆地圖殘片：那一格的平台帳本不能被當成北向 rp_01 那組的授權
        fresh()
        local uM, cM = unZ(151, 510, 420, 1, "rp_01_10")
        local left, wdAfter = mapLeft(), wd and Ledger.get(wd)
        -- 自己蓋的那組照常拆、照常退料，平台跟著收
        fresh()
        local uW = unZ(152, 511, 430, 0, "ramp:rp_01_1")
        local dropW = P:getCurrentSquare().dropped["Base.Plank"]
        check(okW and wd ~= nil and wdRec ~= nil and next(wdRec) == nil and wPlank and wPlank > 0
            and uM == "dismantleSkipped" and cM == "NOT_OURS" and left == 19 and wdAfter == wdRec and next(wdAfter) == nil
            and uW == "dismantled" and dropW == wPlank and weirdDeck() == nil and Ledger.getRamp(511, 430, 0, "ramp:rp_01_1") == nil
            and Ledger.get(wd) == nil and mapLeft() == 19,
            "坡道（Ramp）✗ 平台圖名是「ramp:<頭片名>」、補在地圖殘組的頭片格：拆地圖的片 NOT_OURS、19 片都在、平台那筆不變，自己那組照常拆、照常退料")
    end

    -- 轉向蓋（按 R、藍圖轉向）：送北向頭片＋d＝2（東），伺服器換成東向頭片，帳本記東向頭片名
    do
        esq(485, 402, 1)
        for _ = 1, 20 do P.inv:add(item("Base.Plank")); P.inv:add(item("Base.Nails")) end
        fresh()
        P.pos.x, P.pos.y = 465.5, 403.5
        local c = intentCode(160, "rp_01_0", { 465, 402, 0, 2 })
        sent = {}
        local okR = c == nil and Server.complete(P, 160, 1)
        local rE, rN = Ledger.getRamp(465, 402, 0, "rp_01_72"), Ledger.getRamp(465, 402, 0, "rp_01_0")
        local function eastRow()
            local k = 0
            for i = 0, 19 do if piece(465 + i, 402, "rp_01_" .. (72 + i)) then k = k + 1 end end
            return k
        end
        local built = eastRow()
        fresh()
        P.pos.y = 403.5
        local uR = unbuild(161, 470, 402, "rp_01_77")
        local dropR = P:getCurrentSquare().dropped["Base.Plank"]
        P.pos.x, P.pos.y = 421.5, 431.5
        check(okR and built == 20 and rE ~= nil and rE["Base.Plank"] == 20 and rN == nil and uR == "dismantled" and dropR == 20
            and eastRow() == 0 and Ledger.getRamp(465, 402, 0, "rp_01_72") == nil and Ledger.getRamp(465, 402, 0, "rp_01_0") == nil,
            "坡道（Ramp）轉向蓋：送北向頭片＋d＝東，帳本記東向頭片名（北向那個鍵沒有）；拆一片整組退料一次、兩個鍵都不在")
    end

    -- 框選含平台的坡道：頭片在框裡時藍圖只有頭片一項（平台跟著整組蓋）；照藍圖蓋回來整組含平台都在、只扣一組的料。
    -- 頭片在框外時平台照一般地板收；沒有坡道通到的同圖地板也照一般地板收
    do
        fresh()
        local Cap, Plan = MinidoracatBuilder.Capture, MinidoracatBuilder.Plan
        local function capture(x1, y1, x2, y2, ...)
            local job = Cap.scan(x1, y1, x2, y2, 0)
            while not Cap.step(job) do end
            local r = Cap.build(job, "t", ...)
            local got = {}
            Plan.each(r.plan, function(p)
                got[#got + 1] = { id = r.plan.items[p.it].id, x = job.x1 + p.x, y = job.y1 + p.y, z = job.z0 + p.z, d = p.d }
            end)
            return got, r
        end
        for _ = 1, 40 do P.inv:add(item("Base.Plank")); P.inv:add(item("Base.Nails")) end
        esq(480, 410, 1)
        local okB = build(100, 480)
        local whole, r1 = capture(479, 409, 481, 431)
        local part = capture(480, 405, 480, 415)
        P.pos.y = 431.5
        local okU = unbuild(101, 480, 430, "rp_01_0")
        local gone = column(480) == 0 and deck(480) == nil
        esq(480, 410, 1) -- 假格子拆掉地板後 solidfloor 旗標不清（引擎照格上物件重算）：換一格新的
        local p1 = whole[1]
        local start = P.inv:count("Base.Plank")
        P.pos.x = p1 and p1.x + 0.5 or P.pos.x
        local c = p1 and intentCode(102, p1.id, { p1.x, p1.y, p1.z, p1.d })
        sent = {}
        local okR = p1 and c == nil and Server.complete(P, 102, 1)
        check(okB and #whole == 1 and p1.id == "rp_01_0" and p1.x == 480 and p1.y == 430 and p1.z == 0 and r1.kinds == 1
            and okU == "dismantled" and gone and okR and column(480) == 20 and deck(480) ~= nil
            and start - P.inv:count("Base.Plank") == 20 and Ledger.getRamp(480, 430, 0, "rp_01_0")["Base.Plank"] == 20,
            "坡道（Ramp）✗ 框選含平台的坡道：藍圖只有頭片一項；照藍圖蓋回來 20 片加平台都在、只扣一組的料（木板 20）")
        local own = esq(485, 410, 1)
        own:addFloor("rp_01_23")
        local lone = capture(484, 405, 486, 431)
        check(#part == 1 and part[1].id == "rp_01_23" and part[1].y == 410 and part[1].z == 1
            and #lone == 1 and lone[1].id == "rp_01_23" and lone[1].x == 485,
            "坡道（Ramp）✗ 框選：頭片在框外時平台照一般地板收（只框到坡頂的片不收）；沒有坡道通到的同圖地板照一般地板收")
        -- 審查第 5 輪 R5-4：頭片不在了（被砸、被燒）、頂片與平台還在的殘組：坡道收不進藍圖，平台照一般地板收
        local hsq, hObj = at(480, 430), piece(480, 430, "rp_01_0")
        for i, o in ipairs(hsq.objects) do
            if o == hObj then
                table.remove(hsq.objects, i)
                break
            end
        end
        local headless = capture(479, 409, 481, 431)
        hsq.objects[#hsq.objects + 1] = hObj -- 放回去：後面的情境還要這一組
        check(hObj ~= nil and piece(480, 411, "rp_01_19") ~= nil and #headless == 1 and headless[1].id == "rp_01_23"
            and headless[1].x == 480 and headless[1].y == 410 and headless[1].z == 1,
            "坡道（Ramp）✗ 框選：頭片不在、頂片與平台還在的殘組，平台照一般地板收（藍圖不會坡道和平台都沒有）")
        -- 樓梯（W 型 rpt_01：頂片 470、中片 471、底片 472，平台 469,405,1 補 STAIR_FLOOR）：同坡道，樓梯在框裡時不另收平台；
        -- 底片不在框裡（樓梯不收）時平台照一般地板收
        local function stair(x, y)
            for dx = 0, 2 do -- 前面情境的 IsoThumpable 假物件沒有這兩個方法（Capture.square 會呼叫）
                for _, o in ipairs(at(x + dx, y).objects) do
                    o.getAttachedAnimSprite = o.getAttachedAnimSprite or function() return nil end
                    o.getOverlaySprite = o.getOverlaySprite or function() return nil end
                end
            end
            return #at(x, y).objects == 1 and #at(x + 1, y).objects == 1 and #at(x + 2, y).objects == 1
        end
        local function landing(sq)
            for _, o in ipairs(sq.objects) do if o.name == Entry.STAIR_FLOOR then return o end end
        end
        fresh()
        for _ = 1, 20 do P.inv:add(item("Base.Plank")); P.inv:add(item("Base.Nails")) end
        local lsq = esq(469, 405, 1)
        P.pos.x, P.pos.y = 471.5, 406.5
        local s0 = P.inv:count("Base.Plank")
        local sc = intentCode(110, "rpt_01_0", { 470, 405, 0, 0 })
        sent = {}
        local okS = sc == nil and Server.complete(P, 110, 1) and stair(470, 405) and landing(lsq) ~= nil
        local cost = s0 - P.inv:count("Base.Plank")
        local sWhole = capture(468, 404, 473, 406)
        local sPart = capture(468, 404, 470, 406)
        -- 勾層：只勾樓上（樓梯那層沒勾）時平台照地板收、記在第 0 層；兩層都勾時只有樓梯一項
        local sUp, sBoth = capture(468, 404, 473, 406, { [1] = true }), capture(468, 404, 473, 406, { [0] = true, [1] = true })
        check(#sUp == 1 and sUp[1].id == Entry.STAIR_FLOOR and sUp[1].x == 469 and sUp[1].z == 0
            and #sBoth == 1 and sBoth[1].id == "rpt_01_0",
            "坡道（Ramp）✗ 框選勾層：只勾樓上時樓梯口的平台照地板收（第 0 層）；兩層都勾時只收樓梯、不重複收平台")
        fresh()
        -- 拿掉原來那座（前面情境的 IsoThumpable 假物件走不了本工具的拆除，直接從格子移除，照樣觸發移除事件）
        for dx = 0, 2 do
            local sq = at(470 + dx, 405)
            for k = #sq.objects, 1, -1 do sq:transmitRemoveItemFromSquare(sq.objects[k]) end
        end
        lsq:transmitRemoveItemFromSquare(landing(lsq))
        local sGone = not stair(470, 405) and landing(lsq) == nil
        lsq = esq(469, 405, 1) -- 同上：假格子的 solidfloor 旗標不清
        local q = sWhole[1]
        local s1 = P.inv:count("Base.Plank")
        local qc = q and intentCode(112, q.id, { q.x, q.y, q.z, q.d })
        sent = {}
        local okSR = q and qc == nil and Server.complete(P, 112, 1)
        check(okS and cost > 0 and #sWhole == 1 and q.id == "rpt_01_0" and q.x == 470 and q.y == 405 and q.z == 0
            and sGone and okSR and stair(470, 405) and landing(lsq) ~= nil
            and s1 - P.inv:count("Base.Plank") == cost
            and #sPart == 1 and sPart[1].id == Entry.STAIR_FLOOR and sPart[1].x == 469 and sPart[1].z == 1,
            "坡道（Ramp）✗ 框選含平台的樓梯：藍圖只有樓梯一項，照藍圖蓋回來三片加平台都在、料和第一次一樣；底片在框外時平台照一般地板收")
        local hx, hy, hz, px, py, pn = Place.deckOwner(Entry.STAIR_FLOOR, lsq)
        local rx, _, _, _, _, rn = Place.deckOwner("rp_01_23", at(480, 410, 1))
        local kindWas = sb.KindRamp
        sb.KindRamp = false
        local off = capture(479, 409, 481, 431)
        sb.KindRamp = kindWas
        check(hx == 470 and hy == 405 and hz == 0 and px == 472 and py == 405 and pn == "rpt_01_0" and rx == 480 and rn == "rp_01_0"
            and Place.deckOwner(Entry.STAIR_FLOOR, at(480, 410, 1)) == nil and Place.deckOwner("rp_01_23", lsq) == nil
            and #off == 1 and off[1].id == "rp_01_23" and off[1].z == 1,
            "坡道（Ramp）✗ 平台認哪一組：圖和那一組會補的不同（坡道平台格查 STAIR_FLOOR、樓梯平台格查坡道平台圖）不算；坡道種類關掉（頭片收不進）時平台照一般地板收")
        -- N 型（往北爬）：頂片 475,404、中片 405、底片 406，平台 475,403,1
        fresh()
        local nsq = esq(475, 403, 1)
        P.pos.x, P.pos.y = 476.5, 405.5
        local nc = intentCode(113, "rptn_01_0", { 475, 404, 0, 0 })
        sent = {}
        local okN = nc == nil and Server.complete(P, 113, 1) and landing(nsq) ~= nil
        for y = 404, 406 do
            for _, o in ipairs(at(475, y).objects) do
                o.getAttachedAnimSprite = o.getAttachedAnimSprite or function() return nil end
                o.getOverlaySprite = o.getOverlaySprite or function() return nil end
            end
        end
        local nWhole = capture(474, 402, 476, 407)
        local nPart = capture(474, 402, 476, 405)
        local nx, ny, nz, nbx, nby = Place.deckOwner(Entry.STAIR_FLOOR, nsq)
        check(okN and nx == 475 and ny == 404 and nz == 0 and nbx == 475 and nby == 406
            and #nWhole == 1 and nWhole[1].id == "rptn_01_0" and nWhole[1].x == 475 and nWhole[1].y == 404
            and #nPart == 1 and nPart[1].id == Entry.STAIR_FLOOR and nPart[1].y == 403 and nPart[1].z == 1,
            "坡道（Ramp）✗ 框選含平台的 N 型樓梯：藍圖只有樓梯一項；底片在框外時平台照一般地板收")
        P.pos.x, P.pos.y = 421.5, 431.5
    end

    -- 伺服器
    fresh()
    check(intentCode(12, "rp_01_0", { 445, 430, 0, 0, 445, 420, 0, 0 }) == "BAD_REQUEST",
        "坡道（Ramp）✗ 一個請求帶兩個錨點：BAD_REQUEST")
    local d1 = Entry.digest()
    sb.KindRamp = false
    local d2 = Entry.digest()
    check(intentCode(13, "rp_01_0", { 445, 430, 0, 0 }) == "DISABLED" and d1 ~= d2,
        "坡道（Ramp）✗ 沙盒 KindRamp=false：DISABLED，Entry.digest() 跟著變")

    instanceof, IsoObject, sb.MaxCellsPerDrag, sb.MaxDistance, HARNESS_ROLL, sb.KindRamp = real.inst, real.obj, real.max,
        real.dist, real.roll, real.kind
    local gone = {}
    for _, name in ipairs(added) do spriteMap[name], gone[name] = nil, true end
    for i = #spriteOrder, 1, -1 do if gone[spriteOrder[i].name] then table.remove(spriteOrder, i) end end
end)()

-- ===== 屋頂助手（Roof） =====
;(function()
    print("屋頂助手（Roof 認整套與排法、RoofPanel 預覽與整批加進藍圖）")
    local B = MinidoracatBuilder
    require "MinidoracatBuilder/Roof"
    require "MinidoracatBuilder/RoofPanel"
    local Roof, RP = B.Roof, B.RoofPanel
    local F30, F45 = Roof.FAM["30"], Roof.FAM["45"]
    local real = { tiles = sb.DisabledTilesets, PM = B.PlanMode, toast = B.Messages.toast }
    -- 假圖：外形照模板位置 k 給一個固定的 8×8 點陣（同一片種在各款相同）；flip＝整個反過來（外形差 64 點）
    local added, nextId = {}, 40000
    local lateMask = {} -- 圖名 → true：貼圖的遮罩還沒建好（getMask 回 nil，同引擎貼圖資料還沒載入）
    local function add(name, o)
        nextId = nextId + 1
        local s = sprite(name, nextId, o)
        local getTex = s.getTextureForCurrentFrame
        function s:getTextureForCurrentFrame(d) -- 假貼圖補 getMask（Texture.getMask，Texture.java:780）
            local tex = getTex(self, d)
            if tex then tex.getMask = function() if lateMask[name] then return nil end return true end end
            return tex
        end
        spriteMap[name], added[#added + 1] = s, name
        spriteOrder[#spriteOrder + 1] = s
        return s
    end
    local function mask(k, flip)
        return function(x, y)
            local v = ((k * 1103 + math.floor(x / 8) * 151 + math.floor(y / 8) * 37) * 2654435) % 1000 < 500
            if flip then return not v end
            return v
        end
    end
    local function roof(name, k, flip) add(name, { type = T.WestRoofT, keys = { RoofGroup = "1" }, mask = mask(k, flip) }) end
    local function roofSet(ts, base, off, extra, skip, flipK)
        for k, o in pairs(off) do
            if k ~= skip then roof(ts .. "_" .. (base + o), o, k == flipK) end
        end
        for rel, k in pairs(extra or {}) do roof(ts .. "_" .. (base + rel), k) end
    end
    roofSet("roofs_30_01", 0, F30.off)
    roofSet("mymod_roofs_30", 7, F30.off)
    roofSet("bad30_miss", 0, F30.off, nil, "Q3")
    roofSet("bad30_flip", 0, F30.off, nil, nil, "PNS2")
    for i = 0, 7 do roof("roofs_shallow_x_" .. i, i) end
    -- 45 度：roofs_01 兩套（@0 半格片在 64–71、@32 在 41–47），MOD 套沒有半格片
    roofSet("roofs_01", 0, F45.off, { [64] = 64, [65] = 65, [66] = 66, [70] = 70, [71] = 71 })
    roofSet("roofs_01", 32, F45.off, { [41] = 65, [42] = 66, [46] = 70, [47] = 71 })
    roofSet("mymod_roofs_45", 100, F45.off)
    -- 平頂片（TOP1，+22）同遊戲帶 solidfloor：Rules.classify 先看 solidfloor，所以分類是地板（實機 b100-roof-ch2 kind=floor）
    for _, n in ipairs({ "roofs_01_22", "roofs_01_54", "mymod_roofs_45_122" }) do
        add(n, { type = T.WestRoofT, flags = { "solidfloor" }, keys = { RoofGroup = "1" }, mask = mask(22) })
    end
    -- 山牆片同遊戲：E 系列（RiseE／FallE／PeakE）在格子西邊帶 WallW，S 系列（RiseS／FallS／PeakS）在北邊帶 WallN
    local function capFlags(k, o, m)
        if k:find("S%d*$") then
            return { type = T.wall, flags = { "collideN", "cutN", "WallN" }, keys = { WallN = "" }, mask = mask(m) }
        end
        return { type = T.wall, flags = { "collideW", "cutW", "WallW" }, keys = { WallW = "" }, mask = mask(m) }
    end
    for k, o in pairs(F30.gable.off) do add("walls_exterior_roofs_30_01_" .. o, capFlags(k, o, 1000 + o)) end
    for k, o in pairs(F45.gable.off) do add("walls_exterior_roofs_01_" .. o, capFlags(k, o, 2000 + o)) end
    -- 屋脊頭第二種外形（同原版 walls_exterior_roofs_01@72）：PeakE1／PeakS1 換外形，其他同 @0。穀倉款是這種；
    -- bad_gable_01 的屋脊頭兩種都不像；late_gable_01 同 @0 但屋脊頭那張的遮罩晚到
    local function gableSet(ts, base, peak)
        for k, o in pairs(F45.gable.off) do
            local p1 = k == "PeakE1" or k == "PeakS1"
            add(ts .. "_" .. (base + o), capFlags(k, o, (p1 and peak or 2000) + o))
        end
    end
    gableSet("walls_exterior_roofs_01", 72, 2500)
    gableSet("location_barn_01", 24, 2500)
    gableSet("bad_gable_01", 0, 2250) -- 假遮罩差 500 的倍數是整個反過來；2250 和 2000、2500 都差 31 點以上
    gableSet("late_gable_01", 0, 2000)
    gableSet("late_gable_02", 0, 2000) -- RoofPanel：選了山牆時遮罩還沒好
    roofSet("late_roofs_30b", 0, F30.off) -- Window／RoofPanel.available：第一次還沒載好
    roofSet("late_roofs_30", 0, F30.off)
    lateMask["late_gable_01_15"], lateMask["late_roofs_30_3"] = true, true
    lateMask["late_gable_02_15"], lateMask["late_roofs_30b_3"] = true, true
    add(Roof.FILL, { flags = { "solidfloor" } })
    check(Rules.classify(spriteMap["roofs_30_01_0"]) == "roof" and Rules.classify(spriteMap["walls_exterior_roofs_30_01_0"]) == "wall"
        and Rules.classify(spriteMap[Roof.FILL]) == "floor", "屋頂（Roof）假圖的種類：屋頂片、山牆片、天花板")

    local function L(set, shape, dir, w, h, gable)
        return Roof.layout(set, shape, dir, 100, 200, 100 + w - 1, 200 + h - 1, 1, gable)
    end
    local function grid(groups) -- "x,y,z"（相對 100,200,1）→ { 圖名, … }
        local t = {}
        for _, g in ipairs(groups or {}) do
            for _, c in ipairs(g.cells) do
                local k = (c[1] - 100) .. "," .. (c[2] - 200) .. "," .. (c[3] - 1)
                t[k] = t[k] or {}
                table.insert(t[k], g.id)
            end
        end
        return t
    end
    local function at(t, x, y, z, name) -- 那一格有沒有這張
        for _, n in ipairs(t[x .. "," .. y .. "," .. z] or {}) do if n == name then return true end end
        return false
    end
    local function only(t, x, y, z, name)
        local l = t[x .. "," .. y .. "," .. z]
        return l ~= nil and #l == 1 and l[1] == name
    end
    local function both(t, x, y, name) -- 屋頂那一層這格剛好是 name 加一片天花板
        local l = t[x .. "," .. y .. ",0"]
        return l ~= nil and #l == 2 and at(t, x, y, 0, name) and at(t, x, y, 0, Roof.FILL)
    end
    local function total(groups)
        local n = 0
        for _, g in ipairs(groups or {}) do n = n + #g.cells end
        return n
    end
    local function n30(o) return "roofs_30_01_" .. o end
    local function n45(o) return "roofs_01_" .. o end

    -- 辨識
    local s30, m30 = Roof.family("roofs_30_01_5"), Roof.family("mymod_roofs_30_10")
    check(s30 and s30.fam == "30" and s30.ts == "roofs_30_01" and s30.base == 0 and m30 and m30.base == 7,
        "屋頂（Roof）辨識：原版 30 度整套基準 0；MOD 整套平移到 7 也認得出")
    check(Roof.family("bad30_miss_0") == nil and Roof.family("bad30_flip_0") == nil and Roof.family("roofs_shallow_x_0") == nil
        and Roof.family("walls_exterior_roofs_30_01_0") == nil,
        "屋頂（Roof）✗ 模板少一片、一片外形差超過容許、緩坡（只有 8 片）、牆組：都認不出")
    local s45, s45b, m45 = Roof.family("roofs_01_3"), Roof.family("roofs_01_40"), Roof.family("mymod_roofs_45_105")
    check(s45 and s45.fam == "45" and s45.base == 0 and s45b and s45b.base == 32 and s45.half and s45b.half
        and s45.pieces.RS3[1] == 71 and s45b.pieces.RS3[1] == 47 and s45b.pieces.OP3[1] == 42 and s45.top,
        "屋頂（Roof）辨識 45 度：roofs_01 兩套照編號給包住的那套，半格片在 64–71／41–47 各自找到")
    check(m45 and m45.base == 100 and not m45.half and m45.pieces.RS3[1] == 15 and m45.pieces.RS3[2] == -1
        and m45.pieces.RS3[3] == -1, "屋頂（Roof）45 度沒有半格片的款：half＝false，TwoPt5 用 +15 往西北移一格")
    local g30, g45 = Roof.gableFamily("walls_exterior_roofs_30_01"), Roof.gableFamily("walls_exterior_roofs_01")
    check(g30 and g30.fam == "30" and g45 and g45.fam == "45" and Roof.gableFamily("roofs_30_01") == nil,
        "屋頂（Roof）山牆：30、45 度牆組各認成自己那族；✗ 屋頂組不是山牆")
    local barn = Roof.gableFamily("location_barn_01")
    check(barn and barn.fam == "45" and barn.base == 24 and Roof.gableFamily("bad_gable_01") == nil,
        "屋頂（Roof）山牆：屋脊頭是第二種外形（原版 @72 那種，穀倉、二手衣店）的組也認得出；✗ 屋脊頭兩種都不像：認不出")
    local lateG1, lateGw = Roof.gableFamily("late_gable_01")
    local lateR1, lateRw = Roof.family("late_roofs_30_0")
    local notR, notRw = Roof.family("roofs_shallow_x_0")
    lateMask["late_gable_01_15"], lateMask["late_roofs_30_3"] = nil, nil
    local lateG2, lateR2 = Roof.gableFamily("late_gable_01"), Roof.family("late_roofs_30_0")
    check(lateG1 == nil and lateGw == true and lateR1 == nil and lateRw == true and notR == nil and not notRw
        and lateG2 and lateG2.base == 0 and lateR2 and lateR2.fam == "30",
        "屋頂（Roof）✗ 貼圖遮罩還沒建好：山牆、屋頂這次都回 nil, true（還沒載好，和認不出的 nil 分得開）也不快取；遮罩好了再問就認得出")

    -- 30 度：同 45 度，屋頂那一層每格都補一片天花板（不補時整間不算室內、牆畫成黑色，實機 b100f-roof-ch）
    local g, w = L(s30, "gable", "EW", 6, 8)
    local t = grid(g)
    local rows = true
    for x = 0, 5 do
        rows = rows and both(t, x, 0, n30(29)) and both(t, x, 3, n30(26)) and both(t, x, 4, n30(3))
            and both(t, x, 7, n30(0))
    end
    check(g and w and w.HALF and total(g) == 96 and rows,
        "屋頂（Roof）30 度雙斜 6×8：48 片同一層加每格一片天花板（共 96），北簷 N1、往內 N4，南半 S4、南簷 S1，warn.HALF")
    t = grid((L(s30, "gable", "EW", 4, 7)))
    check(both(t, 0, 3, n30(99)) and both(t, 3, 3, n30(99)), "屋頂（Roof）30 度雙斜奇數跨距 7：中間那排是屋脊 PNS4")
    local _, c1 = L(s30, "gable", "EW", 4, 12)
    local _, c2 = L(s30, "gable", "NS", 1, 5)
    check(c1 == "TOO_WIDE" and c2 == "TOO_SMALL", "屋頂（Roof）30 度 ✗ 跨距 12：TOO_WIDE；✗ 1×5：TOO_SMALL")
    t = grid((L(s30, "hip", nil, 7, 7)))
    check(both(t, 3, 3, n30(115)) and both(t, 0, 0, n30(93)) and both(t, 6, 6, n30(64))
        and both(t, 0, 6, n30(80)) and both(t, 6, 0, n30(77)), "屋頂（Roof）30 度四坡 7×7：中心 Q4，四角各自的外角片")
    t = grid((L(s30, "hip", nil, 5, 9)))
    local ridge = true
    for y = 2, 6 do ridge = ridge and both(t, 2, y, n30(107)) end
    check(ridge and both(t, 2, 1, n30(28)), "屋頂（Roof）30 度四坡 5×9：中間一條屋脊 PWE3（兩端照屋脊），屋脊外是斜面")
    local tS, tN = grid((L(s30, "shed", "S", 3, 4))), grid((L(s30, "shed", "N", 3, 4)))
    local tE, tW = grid((L(s30, "shed", "E", 4, 3))), grid((L(s30, "shed", "W", 4, 3)))
    check(both(tS, 1, 3, n30(0)) and both(tS, 1, 0, n30(3)) and both(tN, 1, 0, n30(29))
        and both(tE, 3, 1, n30(13)) and both(tW, 0, 1, n30(16)), "屋頂（Roof）30 度單斜四個方向：低邊是 1 號片，往高處遞增")
    local hi, ch = L(s30, "shed", "S", 2, 25)
