    check(hi == nil and ch == "TOO_HIGH" and only(t, 0, 17, 1, n30(0)) and only(t, 0, 17, 0, Roof.FILL)
        and only(t, 0, 0, 3, n30(5)) and only(t, 0, 0, 0, Roof.FILL),
        "屋頂（Roof）30 度單斜每 6 格往上一層接（往上接的片底下那層只有天花板）；✗ 25 格要 5 層：TOO_HIGH")
    sb.DisabledTilesets = "roofs_30_01"
    local dg, dc = L(s30, "hip", nil, 4, 4)
    sb.DisabledTilesets = real.tiles
    check(dg == nil and dc == "DISABLED", "屋頂（Roof）✗ 沙盒關掉要用的圖塊組：DISABLED，一片都不給")
    g = L(s30, "gable", "EW", 6, 8, g30)
    t = grid(g)
    local walls = 0
    for _, gg in ipairs(g) do if gg.id:find("^walls_") then walls = walls + #gg.cells end end
    check(walls == 16 and at(t, 0, 0, 0, "walls_exterior_roofs_30_01_13") and at(t, 0, 7, 0, "walls_exterior_roofs_30_01_0")
        and at(t, 6, 0, 0, "walls_exterior_roofs_30_01_13") and total(g) == 112,
        "屋頂（Roof）30 度雙斜配山牆：兩端各一列 8 片（北端 FallE1、南端 RiseE1，東端在範圍外一格）")
    walls = 0
    for _, gg in ipairs(L(s30, "gable", "EW", 6, 8)) do if gg.id:find("^walls_") then walls = walls + 1 end end
    check(walls == 0, "屋頂（Roof）山牆選不放：沒有牆片")

    -- 45 度
    local ids, dirs = {}, {}
    for _, s in ipairs(Roof.shapes(s45)) do
        ids[#ids + 1] = s.id
        if s.id == "shed" then dirs = s.dirs end
    end
    check(table.concat(ids, ",") == "gable,hip,shed,flat" and table.concat(dirs, ",") == "S,E",
        "屋頂（Roof）45 度形狀：雙斜、四坡、單斜、平頂；✗ 單斜沒有朝北、朝西")
    g, w = L(s45, "gable", "EW", 4, 6)
    t = grid(g)
    rows = true
    for x = 0, 3 do
        rows = rows and only(t, x, 0, 0, Roof.FILL) and only(t, x, 2, 0, Roof.FILL) and both(t, x, 3, n45(2))
            and both(t, x, 5, n45(0))
    end
    check(rows and total(g) == 36 and w and w.HALF, "屋頂（Roof）45 度雙斜 6 格：南半 S3..S1，每格都補天花板（24＋12 片），warn.HALF")
    t = grid((L(s45, "gable", "EW", 3, 8)))
    check(only(t, 1, 3, 1, n45(22)) and only(t, 1, 4, 1, n45(22)) and only(t, 1, 3, 0, Roof.FILL) and only(t, 1, 2, 0, Roof.FILL)
        and both(t, 1, 5, n45(2)), "屋頂（Roof）45 度雙斜跨距 8：中間兩排平頂片在上一層，正下方那層補天花板")
    t = grid((L(s45, "gable", "EW", 2, 5)))
    local tm = grid((L(m45, "gable", "EW", 2, 5)))
    check(at(t, 0, 2, 0, n45(71)) and at(t, 0, 2, 0, Roof.FILL) and both(t, 0, 3, n45(1))
        and at(tm, -1, 1, 0, "mymod_roofs_45_115") and at(tm, 0, 2, 0, Roof.FILL),
        "屋頂（Roof）45 度雙斜奇數跨距 5：中間 TwoPt5＋同格天花板；沒有專用片的款用 +15 往西北移一格")
    t = grid((L(s45, "gable", "NS", 6, 2)))
    check(both(t, 3, 0, n45(3)) and both(t, 5, 1, n45(5)) and only(t, 0, 0, 0, Roof.FILL),
        "屋頂（Roof）45 度雙斜南北向：東半 E3..E1，每格補天花板")
    t = grid((L(s45, "hip", nil, 6, 6)))
    check(both(t, 5, 5, n45(8)) and both(t, 0, 5, n45(24)) and both(t, 5, 0, n45(29)) and only(t, 0, 0, 0, Roof.FILL)
        and both(t, 3, 3, n45(10)) and only(t, 2, 2, 0, Roof.FILL), "屋頂（Roof）45 度四坡 6×6：東南 Outer、西南 CornerSW、東北 CornerNE，西北只有天花板")
    t = grid((L(s45, "hip", nil, 5, 5)))
    local _, odd = L(m45, "hip", nil, 5, 5)
    local t7 = grid((L(m45, "hip", nil, 7, 7)))
    check(at(t, 2, 2, 0, n45(66)) and at(t, 2, 2, 0, Roof.FILL) and odd == "ODD_SPAN" and only(t7, 3, 3, 1, "mymod_roofs_45_122"),
        "屋頂（Roof）45 度四坡 5×5 中心 OuterTwoPt5；✗ 沒有半格轉角片的款：ODD_SPAN；7×7 中心是上一層的平頂")
    t = grid((L(s45, "shed", "S", 2, 4)))
    check(both(t, 0, 3, n45(0)) and both(t, 0, 1, n45(2)) and only(t, 0, 0, 1, n45(0)) and only(t, 0, 0, 0, Roof.FILL),
        "屋頂（Roof）45 度單斜朝南：每 3 格往上一層接，往上接那格的下面一層補天花板")
    g, w = L(s45, "flat", nil, 3, 3)
    t = grid(g)
    check(total(g) == 9 and only(t, 1, 1, 0, n45(22)) and w == nil, "屋頂（Roof）45 度平頂 3×3：每格一張平頂片")
    t = grid((L(s45, "gable", "EW", 2, 5, g45)))
    local g8, w8 = L(s45, "gable", "EW", 2, 8, g45)
    local tg = grid(g8)
    local gw = 0
    for k, l in pairs(tg) do
        if k:find("^0,") then for _, n in ipairs(l) do if n:find("^walls_") then gw = gw + 1 end end end
    end
    check(at(t, 0, 0, 0, "walls_exterior_roofs_01_8") and at(t, 0, 1, 0, "walls_exterior_roofs_01_9")
        and at(t, 0, 2, 0, "walls_exterior_roofs_01_16") and at(t, 0, 3, 0, "walls_exterior_roofs_01_1")
        and at(t, 0, 4, 0, "walls_exterior_roofs_01_0") and gw == 6 and w8 and w8.GAP == 4,
        "屋頂（Roof）45 度山牆：跨距 5 是 FallE1、FallE2、PeakTwoPt5E、RiseE2、RiseE1；跨距 8 中段底下沒有房子的牆可接時"
            .. "不放、warn.GAP 記 4 格（兩端各 2 排）")
    sb.DisabledTilesets = "ceilings_01"
    t = grid((L(s45, "gable", "EW", 2, 4)))
    sb.DisabledTilesets = "ceilings_01;roofs_01"
    local left = {}
    for _, s in ipairs(Roof.shapes(s45)) do left[#left + 1] = s.id end
    local left30 = #Roof.shapes(s30)
    sb.DisabledTilesets = real.tiles
    check(only(t, 0, 0, 0, n45(22)) and table.concat(left, ",") == "flat" and left30 == 0 and #Roof.shapes(s30) == 3,
        "屋頂（Roof）天花板被關掉改鋪平頂片；兩種都關掉時 45 度不給斜屋頂形狀；30 度沒有平頂片，天花板被關掉時一種都不給")

    do -- fix3 (4)：30、45 度每種斜形狀、奇偶跨距，屋頂那一層每格都有天花板；平頂沒有（平頂片自己是地板）
        local miss, fills = nil, {}
        local shapes = { { s45, "45", { { "gable", "EW" }, { "gable", "NS" }, { "hip" }, { "shed", "S" }, { "shed", "E" } } },
            { s30, "30", { { "gable", "EW" }, { "gable", "NS" }, { "hip" }, { "shed", "N" }, { "shed", "E" }, { "shed", "S" },
                { "shed", "W" } } } }
        for _, f in ipairs(shapes) do
            for _, c in ipairs(f[3]) do
                for _, sz in ipairs({ { 3, 3 }, { 4, 8 }, { 5, 5 }, { 5, 9 }, { 6, 6 }, { 7, 7 } }) do
                    local gr, ww = L(f[1], c[1], c[2], sz[1], sz[2])
                    local tt, n = grid(gr), 0
                    for _, gg in ipairs(gr or {}) do if gg.id == Roof.FILL then n = n + #gg.cells end end
                    fills[f[2] .. c[1] .. (c[2] or "") .. sz[1] .. "x" .. sz[2]] = n
                    for x = 0, sz[1] - 1 do
                        for y = 0, sz[2] - 1 do
                            if not miss and (not gr or not (ww and ww.HALF) or not at(tt, x, y, 0, Roof.FILL)) then
                                miss = f[2] .. " " .. c[1] .. "/" .. tostring(c[2]) .. " " .. sz[1] .. "x" .. sz[2] .. " @" .. x .. "," .. y
                            end
                        end
                    end
                end
            end
        end
        local fl = grid((L(s45, "flat", nil, 4, 4)))
        check(miss == nil and fills["45hip5x5"] == 25 and fills["45gableEW4x8"] == 32 and fills["30hip7x7"] == 49
            and fills["30shedS5x9"] == 45 and not at(fl, 0, 0, 0, Roof.FILL),
            "屋頂（Roof）30、45 度雙斜、四坡、單斜（奇偶跨距）屋頂層每格都補天花板、都有 warn.HALF（45 度四坡 5×5 補 25 片、"
                .. "30 度四坡 7×7 補 49 片）；✗ 平頂不補" .. (miss and "；第一個漏的 " .. miss or ""))
    end

    do -- fix3 (1)(2)：樓上的牆疊在正下方同一條邊的牆上、往上一層接的屋頂片靠下面撐；助手排的片不管照什麼順序都蓋得起來
        local Place = B.Place
        local opts = {}
        local function cellAt(x, y, z) -- 建或拿格子；回 格子, 它的選項（flags、wallN、wallW、floor）
            local k = x .. "," .. y .. "," .. z
            if not opts[k] then
                opts[k] = { flags = { solidfloor = z == 0 or nil } } -- 一樓的地面帶 solidfloor，同真遊戲
                square(x, y, z, opts[k])
            end
            return squares[k], opts[k]
        end
        local function obj(spr) return { getSprite = function() return spr end } end
        local function put(kind, spr, x, y, z)
            local sq, o = cellAt(x, y, z)
            local it = obj(spr)
            sq.objects[#sq.objects + 1] = it
            if kind == "floor" then
                o.flags.solidfloor, o.floor = true, it
            elseif kind == "wall" then
                local n, w = Entry.edges(kind, spr)
                if n then o.wallN = it end
                if w then o.wallW = it end
            end
        end
        local function fits(kind, spr, x, y, z)
            return Place.check(kind, spr, (cellAt(x, y, z)), nil, nil, nil, nil, false) == true
        end
        -- 牆：一樓的西牆上面疊山牆片／一般牆；靠著同一層的屋頂片（伺服器分不出兩種牆，見 Place.lua wallHeld）
        local gw, r30 = spriteMap["walls_exterior_roofs_30_01_13"], spriteMap["roofs_30_01_0"]
        local plain = add("p2_plain_wall_0", { type = T.wall, flags = { "collideW", "cutW", "WallW" }, keys = { WallW = "" } })
        local _, o0 = cellAt(3900, 3000, 0)
        o0.wallW = obj(plain)
        local _, oN = cellAt(3902, 3000, 0)
        oN.wallN = obj(plain)
        local _, oF = cellAt(3904, 3000, 1)
        oF.flags.solidfloor, oF.floor = true, obj(spriteMap[Roof.FILL])
        put("roof", r30, 3920, 3000, 2)
        put("roof", r30, 3925, 3001, 2)
        check(fits("wall", gw, 3900, 3000, 1) and fits("wall", plain, 3900, 3000, 1)
            and not fits("wall", gw, 3901, 3000, 1) and not fits("wall", plain, 3901, 3000, 1)
            and not fits("wall", gw, 3902, 3000, 1) and fits("wall", plain, 3904, 3000, 1),
            "屋頂（Place）二樓沒有地板的牆：正下方同一條邊有牆可以蓋（山牆片、一般牆同規則）；✗ 底下沒有牆（浮空）、"
                .. "✗ 底下的牆在另一條邊：擋；有地板照舊可以")
        check(fits("wall", gw, 3920, 3000, 2) and fits("wall", gw, 3921, 3000, 2) and not fits("wall", gw, 3922, 3000, 2)
            and not fits("wall", plain, 3925, 3000, 2),
            "屋頂（Place）三樓沒有地板的西牆：這條邊兩側的格子同一層有屋頂片可以蓋（端牆）；✗ 屋頂片隔一格、在南邊那格：擋")
        -- 屋頂：正下方有屋頂片、斜下方鄰格有屋頂片可以；✗ 正下方只有天花板、斜下方只有天花板、什麼都沒有：擋
        put("floor", spriteMap[Roof.FILL], 3910, 3000, 1)
        put("roof", r30, 3912, 3000, 1)
        put("roof", r30, 3914, 3001, 1)
        put("floor", spriteMap[Roof.FILL], 3916, 3001, 1)
        check(not Place.roofAt(3910, 3000, 2) and Place.roofAt(3912, 3000, 2) and Place.roofAt(3914, 3000, 2)
            and not Place.roofAt(3916, 3000, 2) and not Place.roofAt(3918, 3000, 2),
            "屋頂（Place）二樓以上的屋頂片：正下方有屋頂片、斜下方鄰格有屋頂片可以；✗ 正下方只有天花板（同樓板，不算撐）、"
                .. "✗ 斜下方只有天花板、✗ 下面和旁邊都沒東西：擋")
        -- 那一層還沒有格子（實機 b100-roof-ch2 的 check=nosq）：預覽不補格子，Check.item 改照座標問 roofAt／floorAt；
        -- 伺服器 Place.square 補出格子後照 Place.check 逐片查（fits 先建格子，同伺服器）。45 度平頂片分類是地板
        local cellZ2 = getCell()
        local noSq = cellZ2:getGridSquare(3912, 3000, 2) == nil and cellZ2:getGridSquare(3914, 3000, 2) == nil
            and cellZ2:getGridSquare(3930, 3000, 2) == nil and cellZ2:getGridSquare(3936, 3000, 2) == nil
        put("roof", spriteMap["roofs_01_3"], 3930, 3001, 1)
        put("floor", spriteMap[Roof.FILL], 3936, 3001, 1)
        local flat = spriteMap["roofs_01_22"]
        local preview = Place.floorAt(3930, 3000, 2) and not Place.floorAt(3936, 3000, 2)
            and Place.roofAt(3914, 3000, 2) and not Place.roofAt(3918, 3000, 2)
        check(noSq and Rules.classify(flat) == "floor" and preview and fits("floor", flat, 3930, 3000, 2)
            and not fits("floor", flat, 3936, 3000, 2) and fits("roof", r30, 3914, 3000, 2),
            "屋頂（Place）上一層還沒有格子：平頂片（地板）四鄰往下一層有斜片、屋頂片斜下方有屋頂片，預覽照座標判可蓋、"
                .. "補出格子後也放得下；✗ 四鄰往下一層只有天花板：兩端都擋")
        -- 屋頂浮空（實機 plan-sp wrBefore／roBefore，0d1d2f2 起回 ok）：一樓地面帶 solidfloor（同真遊戲）不能當二樓屋頂的撐；
        -- 二樓以上正下方只有樓板或天花板也不算（同 0a4b161）。撐得住：正下方有牆或屋頂片、斜下方鄰格有屋頂片、
        -- 同一層四鄰有屋頂或地板（照圖蓋的順序靠 WAIT，不靠放寬）
        for x = 3959, 3965 do for y = 2999, 3003 do cellAt(x, y, 0) end end
        local loneOk = Place.roofAt(3962, 3001, 1) or fits("roof", r30, 3962, 3001, 1)
        select(2, cellAt(3964, 3001, 0)).wallW = obj(plain)
        local onWall = Place.roofAt(3964, 3001, 1)
        put("roof", r30, 3964, 3001, 1)
        local chain = Place.roofAt(3963, 3001, 1)
        local slab = add("p2_slab_floor_0", { flags = { "solidfloor" } })
        put("floor", slab, 3970, 3000, 1)
        put("floor", spriteMap[Roof.FILL], 3972, 3000, 1)
        local onSlab = Place.roofAt(3970, 3000, 2) or Place.roofAt(3972, 3000, 2)
        check(not loneOk and onWall and chain and not onSlab,
            "屋頂（Place）一樓地面帶 solidfloor：✗ 二樓孤零零的屋頂（正下方沒牆、四周沒屋頂或地板）擋；正下方有牆可以、"
                .. "挨著蓋好的屋頂可以；✗ 三樓正下方只有樓板或天花板：擋（同 0a4b161）")
        -- 審查第 5 輪 R5-1：平屋頂地板片（roofs_01_22：帶 RoofGroup 的 solidfloor 片，分類是地板）是樓板、不是斜片：
        -- 鋪在一樓後，正上方二樓的屋頂、旁邊二樓的地板都不能靠它浮空蓋
        for x = 3979, 3985 do for y = 2999, 3003 do cellAt(x, y, 0) end end
        put("floor", flat, 3982, 3001, 0)
        local overFlat = Place.roofAt(3982, 3001, 1) or fits("roof", r30, 3982, 3001, 1)
        local besideFlat = Place.floorAt(3983, 3001, 1) or fits("floor", slab, 3983, 3001, 1)
        check(flat:getProperties():has("RoofGroup") and not overFlat and not besideFlat,
            "屋頂（Place）平屋頂地板片鋪在一樓：✗ 正上方二樓的屋頂、✗ 旁邊二樓的地板都擋（它是樓板，不算屋頂片）")
        -- 審查第 5 輪：上一層那格還沒有時，格邊的東西也照座標查撐不撐得住（Place.edgeHeldAt，Check.item 預覽用），
        -- 和伺服器補出格子後的 Place.check 同一個答案（✗ 預覽說能蓋、伺服器回 BLOCKED）
        select(2, cellAt(3940, 3000, 0)).wallW = obj(plain) -- 正下方同一條邊有牆
        put("roof", r30, 3943, 3000, 1)                     -- 西邊那格同一層有屋頂片
        put("floor", slab, 3946, 3000, 1)                   -- 西邊那格同一層有地板（引擎 hasFloor(north) 看鄰格）
        cellAt(3949, 3000, 0)                               -- 什麼都沒有
        local cw = getCell()
        local noUp = cw:getGridSquare(3940, 3000, 1) == nil and cw:getGridSquare(3944, 3000, 1) == nil
            and cw:getGridSquare(3947, 3000, 1) == nil and cw:getGridSquare(3949, 3000, 1) == nil
        local pre = { Place.edgeHeldAt("wall", plain, 3940, 3000, 1), Place.edgeHeldAt("wall", plain, 3944, 3000, 1),
            Place.edgeHeldAt("wall", plain, 3947, 3000, 1), Place.edgeHeldAt("wall", plain, 3949, 3000, 1),
            Place.edgeHeldAt("wall", plain, 3949, 3000, 0) }
        check(noUp and pre[1] and pre[2] and pre[3] and not pre[4] and pre[5]
            and fits("wall", plain, 3940, 3000, 1) and fits("wall", plain, 3944, 3000, 1) and not fits("wall", plain, 3949, 3000, 1),
            "屋頂（Place）上一層還沒有格子的牆照座標查：正下方同邊有牆、旁邊同層有屋頂片、旁邊同層有地板可以；"
                .. "✗ 都沒有：擋；一樓不查。補出格子後 Place.check 同一個答案")
        -- 複核：框、柵欄、門窗也一樣。柵欄與門框靠鄰格的地板（不靠正下方的牆、旁邊的屋頂片）；一般的門要門框、
        -- 一般的窗要窗框，空格子一定沒有
        local fenceW = add("p2_fence_0", { flags = { "HoppableW" } })
        local frameW = add("p2_frame_0", { flags = { "DoorWallW" } })
        local doorW = add("p2_door_0", { flags = { "doorW" } })
        local winW = add("p2_win_0", { flags = { "windowW" } })
        local e = Place.edgeHeldAt
        check(e("fence", fenceW, 3947, 3000, 1) and e("doorFrame", frameW, 3947, 3000, 1)
            and not e("fence", fenceW, 3940, 3000, 1) and not e("doorFrame", frameW, 3944, 3000, 1)
            and not e("fence", fenceW, 3949, 3000, 1) and not e("door", doorW, 3947, 3000, 1)
            and not e("window", winW, 3947, 3000, 1) and e("door", doorW, 3949, 3000, 0)
            and not fits("fence", fenceW, 3950, 3000, 1) and not fits("door", doorW, 3950, 3000, 1)
            and not fits("window", winW, 3950, 3000, 1),
            "屋頂（Place）上一層還沒有格子的柵欄、門框照座標查：旁邊同層有地板可以；✗ 只有正下方的牆、旁邊的屋頂片、"
                .. "都沒有：擋；✗ 一般的門、窗（要框）：擋；一樓不查。補出空格子後 Place.check 同樣擋")
        -- 不要框的特例不能被一般門窗那兩句擋掉：柵欄門、車庫門、牆型窗、柱子（看西鄰）照樣只看鄰格地板
        local gateW = add("p2_gate_0", { flags = { "doorW", "HoppableW" } })
        local garageW = add("p2_garage_0", { flags = { "doorW" }, keys = { GarageDoor = "" } })
        local fwinW = add("p2_fwin_0", { type = T.wall, flags = { "windowW" } })
        local postS = add("p2_post_0", { flags = { "WallSE" } })
        check(e("door", gateW, 3947, 3000, 1) and e("door", garageW, 3947, 3000, 1) and e("window", fwinW, 3947, 3000, 1)
            and e("post", postS, 3947, 3000, 1) and not e("door", gateW, 3949, 3000, 1) and not e("door", garageW, 3949, 3000, 1)
            and not e("window", fwinW, 3949, 3000, 1) and not e("post", postS, 3949, 3000, 1),
            "屋頂（Place）上一層還沒有格子的柵欄門、車庫門、牆型窗、柱子：旁邊同層有地板可以（✗ 當成一般門窗要框而擋）；✗ 都沒有：擋")

        -- 照圖蓋：一樓四面牆圍好，助手排的片反覆照「現在蓋得起來的先蓋」，最後要一片不剩（同照圖蓋等旁邊先蓋好）
        local plainN = add("p2_plain_wall_1", { type = T.wall, flags = { "collideN", "cutN", "WallN" }, keys = { WallN = "" } })
        local function house(x0, y0, w, h)
            for x = x0 - 1, x0 + w do for y = y0 - 1, y0 + h do cellAt(x, y, 0) end end -- 地面（帶 solidfloor）
            for x = x0, x0 + w - 1 do
                select(2, cellAt(x, y0, 0)).wallN = obj(plainN)
                select(2, cellAt(x, y0 + h, 0)).wallN = obj(plainN)
            end
            for y = y0, y0 + h - 1 do
                select(2, cellAt(x0, y, 0)).wallW = obj(plain)
                select(2, cellAt(x0 + w, y, 0)).wallW = obj(plain)
            end
        end
        local function buildAll(groups)
            local todo = {}
            for _, gg in ipairs(groups or {}) do
                local spr = spriteMap[gg.id]
                for _, c in ipairs(gg.cells) do
                    todo[#todo + 1] = { spr = spr, kind = Rules.classify(spr), x = c[1], y = c[2], z = c[3] }
                end
            end
            local moved = true
            while moved do
                moved = false
                for _, p in ipairs(todo) do
                    if not p.done and fits(p.kind, p.spr, p.x, p.y, p.z) then
                        put(p.kind, p.spr, p.x, p.y, p.z)
                        p.done, moved = true, true
                    end
                end
            end
            for _, p in ipairs(todo) do
                if not p.done then return p.spr:getName() .. "@" .. p.x .. "," .. p.y .. "," .. p.z end
            end
            return #todo > 0 and "ok" or "empty"
        end
        local cases = { { "30 雙斜 6×5＋山牆", s30, "gable", "EW", 6, 5, g30 }, { "30 單斜朝南 4×8＋山牆", s30, "shed", "S", 4, 8, g30 },
            { "45 雙斜 6×8", s45, "gable", "EW", 6, 8 }, { "45 雙斜 6×5＋山牆", s45, "gable", "EW", 6, 5, g45 },
            { "45 單斜朝南 4×4", s45, "shed", "S", 4, 4 }, { "45 單斜朝東 4×4", s45, "shed", "E", 4, 4 },
            { "45 四坡 5×5", s45, "hip", nil, 5, 5 }, { "45 四坡 7×7", s45, "hip", nil, 7, 7 },
            { "45 雙斜 3×7＋山牆", s45, "gable", "EW", 3, 7, g45 }, { "45 雙斜 3×8＋山牆", s45, "gable", "EW", 3, 8, g45 },
            { "45 雙斜 3×9＋山牆", s45, "gable", "EW", 3, 9, g45 }, { "45 雙斜南北 8×3＋山牆", s45, "gable", "NS", 8, 3, g45 },
            { "45 單斜朝南 3×7＋山牆", s45, "shed", "S", 3, 7, g45 }, { "45 單斜朝東 7×3＋山牆", s45, "shed", "E", 7, 3, g45 } }
        local stuck
        for i, c in ipairs(cases) do
            local x0, y0 = 4000 + i * 20, 4000
            house(x0, y0, c[5], c[6])
            local r = buildAll((Roof.layout(c[2], c[3], c[4], x0, y0, x0 + c[5] - 1, y0 + c[6] - 1, 1, c[7])))
            if r ~= "ok" and not stuck then stuck = c[1] .. "：" .. r end
        end
        check(stuck == nil, "屋頂（Roof＋Place）照圖蓋：30／45 度雙斜、單斜、四坡（含山牆、往上一層接、上一層平頂）"
            .. "每一片都蓋得起來" .. (stuck and "；卡住的 " .. stuck or ""))
        -- 屋頂浮空修正後（正下方只有地板、天花板不算撐）：30／45 度每種形狀 × 方向 × 有／沒有山牆，地面帶 solidfloor 的房子上
        -- 照圖蓋到一片不剩（往上一層接的片靠斜下方的屋頂片與同一層先蓋好的片，順序靠反覆挑蓋得起來的）
        local allStuck, allRuns, idx = nil, 0, 0
        for _, c in ipairs({ { s30, g30 }, { s45, g45 } }) do
            for _, sh in ipairs(Roof.shapes(c[1])) do
                for _, dd in ipairs(#sh.dirs > 0 and sh.dirs or { false }) do
                    for _, gb in ipairs({ false, c[2] }) do
                        for _, sz in ipairs({ { 4, 8 }, { 7, 7 }, { 9, 5 } }) do
                            idx = idx + 1
                            local x0, y0 = 4000 + idx * 12, 6000
                            house(x0, y0, sz[1], sz[2])
                            local gr = Roof.layout(c[1], sh.id, dd or nil, x0, y0, x0 + sz[1] - 1, y0 + sz[2] - 1, 1, gb or nil)
                            if gr then
                                allRuns = allRuns + 1
                                local r = buildAll(gr)
                                if r ~= "ok" and not allStuck then
                                    allStuck = c[1].fam .. " " .. sh.id .. " " .. tostring(dd) .. (gb and "＋山牆 " or " ")
                                        .. sz[1] .. "×" .. sz[2] .. "：" .. r
                                end
                            end
                        end
                    end
                end
            end
        end
        check(allStuck == nil and allRuns >= 40, "屋頂（Roof＋Place）地面帶 solidfloor：30／45 度每種形狀、方向、有／沒有山牆、"
            .. "4×8／7×7／9×5 照圖蓋都一片不剩（" .. allRuns .. " 種）" .. (allStuck and "；卡住的 " .. allStuck or ""))

        -- 缺口（Main 2026-11-17，實機 roof-45-gable-8-gw）：配山牆時側面每一格從屋簷到屋頂線都要有牆。幾何條件：側面那格旁邊
        -- 那格（範圍裡最靠那一邊的那格）有斜片在第 L 層＝第 0..L 層都要有牆類；只有上一層的平頂片（地板，第 1 層以上）在第 L 層
        -- ＝第 0..L-1 層要有牆；那格沒有片（45 度朝北、朝西的坡面）照對稱那一格算
        local function holes(groups, x0, y0, w, h, ns)
            local kinds = {}
            for _, gg in ipairs(groups or {}) do
                local kd = Rules.classify(spriteMap[gg.id])
                for _, c in ipairs(gg.cells) do
                    local k = c[1] .. "," .. c[2]
                    kinds[k] = kinds[k] or {}
                    kinds[k][#kinds[k] + 1] = { kd, c[3] - 1 }
                end
            end
            local function need(x, y) -- 這格的屋頂線：要牆的最高一層，沒有片回 nil
                local top
                for _, it in ipairs(kinds[x .. "," .. y] or {}) do
                    local lv = it[1] == "roof" and it[2] or (it[1] == "floor" and it[2] >= 1 and it[2] - 1) or nil
                    if lv and (top == nil or lv > top) then top = lv end
                end
                return top
            end
            local function hasWall(x, y, lv)
                for _, it in ipairs(kinds[x .. "," .. y] or {}) do
                    if it[1] == "wall" and it[2] == lv then return true end
                end
                return false
            end
            local n, len = 0, ns and w or h
            for i = 0, len - 1 do
                local sides = ns and { { x0 + i, y0, x0 + i, y0 }, { x0 + i, y0 + h, x0 + i, y0 + h - 1 } } -- 側面格, 旁邊那格
                    or { { x0, y0 + i, x0, y0 + i }, { x0 + w, y0 + i, x0 + w - 1, y0 + i } }
                for _, s in ipairs(sides) do
                    local top = need(s[3], s[4])
                    if top == nil then -- 對稱那一格（沿側面方向鏡射）
                        local mx, my = s[3], s[4]
                        if ns then mx = x0 + w - 1 - i else my = y0 + h - 1 - i end
                        top = need(mx, my)
                    end
                    for lv = 0, top or -1 do
                        if not hasWall(s[1], s[2], lv) then n = n + 1 end
                    end
                end
            end
            return n
        end
        local gapBad
        for i, c in ipairs({ { "45 雙斜 3×7", "gable", "EW", 3, 7 }, { "45 雙斜 3×8", "gable", "EW", 3, 8 },
            { "45 雙斜 3×9", "gable", "EW", 3, 9 }, { "45 雙斜南北 9×3", "gable", "NS", 9, 3 },
            { "45 單斜朝南 3×8", "shed", "S", 3, 8 }, { "45 單斜朝東 8×3", "shed", "E", 8, 3 } }) do
            local x0, y0 = 4000 + i * 20, 4400
            house(x0, y0, c[4], c[5])
            local gr, ww = Roof.layout(s45, c[2], c[3], x0, y0, x0 + c[4] - 1, y0 + c[5] - 1, 1, g45)
            local hn = holes(gr, x0, y0, c[4], c[5], c[3] == "NS" or c[3] == "E")
            local before = gapBad
            gapBad = gapBad or ((hn > 0 or (ww and ww.GAP)) and c[1] .. " 缺 " .. hn .. " 格" or nil)
            if not before and not gapBad then
                local r = buildAll(gr)
                if r ~= "ok" then gapBad = c[1] .. " 照圖蓋卡住 " .. r end
            end
        end
        local x0, y0 = 4000, 4800
        house(x0, y0, 3, 8)
        local g30s, w30s = Roof.layout(s30, "shed", "S", x0, y0, x0 + 2, y0 + 7, 1, g30)
        local h30 = holes(g30s, x0, y0, 3, 8, false)
        local r30s = buildAll(g30s)
        -- 往下一層那格的牆是門框、牆角或沒有：用同一邊最近的直牆（顏色同房子）
        local fx, fy = 4000, 5200
        house(fx, fy, 3, 8)
        select(2, cellAt(fx, fy + 3, 0)).wallW = nil
        local gf, wf = Roof.layout(s45, "gable", "EW", fx, fy, fx + 2, fy + 7, 1, g45)
        local tf = {}
        for _, gg in ipairs(gf or {}) do for _, cc in ipairs(gg.cells) do tf[cc[1] .. "," .. cc[2] .. "," .. cc[3] .. gg.id] = true end end
        check(gapBad == nil and h30 == 0 and not (w30s and w30s.GAP) and r30s == "ok"
            and tf[fx .. "," .. (fy + 3) .. ",1" .. plain:getName()] and holes(gf, fx, fy, 3, 8, false) == 0 and not (wf and wf.GAP),
            "屋頂（Roof）45 度跨距 7、8、9 配山牆（東西、南北向）、45／30 度單斜往上接：側面每一格從屋簷到屋頂線都有牆或山牆片、"
                .. "沒有 warn.GAP，照圖蓋每片都蓋得起來；底下那格沒有直牆時用同一邊最近的直牆" .. (gapBad and "；" .. gapBad or ""))

        -- 屋頂範圍裡已經有地板的格子不補天花板（玩家鋪的、地圖原有的；Main 2026-11-17）：照圖蓋後地板圖沒被換掉
        local floorSpr = add("p2_player_floor_0", { flags = { "solidfloor" } })
        local px, py = 4000, 5600
        house(px, py, 4, 4)
        local own = { { px, py }, { px + 1, py + 2 }, { px + 3, py + 3 } }
        for _, p in ipairs(own) do put("floor", floorSpr, p[1], p[2], 1) end
        local gp, wp = Roof.layout(s30, "gable", "EW", px, py, px + 3, py + 3, 1, nil)
        local fills, onOwn = 0, false
        for _, gg in ipairs(gp or {}) do
            if gg.id == Roof.FILL then
                fills = #gg.cells
                for _, cc in ipairs(gg.cells) do
                    for _, p in ipairs(own) do if cc[1] == p[1] and cc[2] == p[2] then onOwn = true end end
                end
            end
        end
        local rb = buildAll(gp)
        local kept = true
        for _, p in ipairs(own) do
            local s, o = cellAt(p[1], p[2], 1)
            local nFill = 0
            for _, ob in ipairs(s.objects) do if ob:getSprite() == spriteMap[Roof.FILL] then nFill = nFill + 1 end end
            kept = kept and o.floor ~= nil and o.floor:getSprite() == floorSpr and nFill == 0
        end
        check(fills == 13 and not onOwn and wp and wp.HALF and rb == "ok" and kept,
            "屋頂（Roof）範圍裡先有 3 格地板：那 3 格不補天花板（16 格補 13 片）；照圖蓋後那 3 格還是原本的地板")
        -- 審查第 5 輪：補天花板的圖不成立（圖塊組被沙盒關掉）時 30 度回 DISABLED（面板有句子可說），不丟錯
        local realResolveF = Entry.resolve
        Entry.resolve = function(name)
            if name == Roof.FILL then return nil end
            return realResolveF(name)
        end
        local okD, gd, cd = pcall(Roof.layout, s30, "gable", "EW", px, py, px + 3, py + 3, 1, nil)
        Entry.resolve = realResolveF
        check(okD and gd == nil and cd == "DISABLED", "屋頂（Roof）✗ 補天花板的圖被關掉：30 度回 DISABLED，不丟錯（" .. tostring(cd) .. "）")
        for k in pairs(opts) do squares[k] = nil end
    end

    -- RoofPanel
    local calls, toasts, ret, last = 0, {}, { 5 }, nil
    B.PlanMode = { addMany = function(_, groups)
            calls, last = calls + 1, groups
            return ret[1], ret[2]
        end, planning = function() return true end, level = function() return 1 end, toggle = function() return true end,
        setLevel = function() end }
    B.Messages.toast = function(_, text) toasts[#toasts + 1] = text end
    local av = RP.available("roofs_30_01_5") and RP.available("roofs_01_3") and not RP.available("roofs_shallow_x_0")
    B.PlanMode.addMany = nil
    local noAdd = RP.available("roofs_30_01_5")
    B.PlanMode.addMany = function(_, groups)
        calls, last = calls + 1, groups
        return ret[1], ret[2]
    end
    check(av and noAdd == false, "屋頂（RoofPanel）available：認得出整套才給；✗ 沒有 PlanMode.addMany 不給")
    local st = RP.st
    st.pn, st.set, st.shape, st.dir, st.gable, st.gableTs = 0, s30, "gable", "EW", nil, ""
    local okR = RP.release(100, 200, 105, 207)
    check(okR and calls == 1 and total(last) == 96 and #toasts == 0, "屋頂（RoofPanel）放開：整批只叫一次 addMany（30 度 6×8 含天花板 96 片），不跳通知")
    local why = {}
    for _, code in ipairs({ "FULL", "TOO_WIDE", "TOO_HIGH", "OFF" }) do
        ret = { nil, code }
        toasts = {}
        RP.release(100, 200, 105, 207)
        why[#why + 1] = toasts[1]
    end
    ret = { 5 }
    toasts = {}
    local before = calls
    RP.release(100, 200, 100, 205)
    check(table.concat(why, ",") == "IGUI_MBLD_Roof_Err_FULL,IGUI_MBLD_Roof_Err_PLAN_WIDE,IGUI_MBLD_Roof_Err_TOO_HIGH,"
        .. "IGUI_MBLD_Roof_Err_OFF" and toasts[1] == "IGUI_MBLD_Roof_Err_TOO_SMALL" and calls == before,
        "屋頂（RoofPanel）✗ addMany 失敗：面板自己說屋頂的句子；排不出來不叫 addMany")
    local p1, p2 = RP.preview(100, 200, 105, 207), RP.preview(100, 200, 105, 207)
    st.set, st.shape, st.dir = s45, "shed", "N"
    RP.fix()
    local fixed = st.dir
    st.shape, st.dir = "gable", "EW"
    local p3 = RP.preview(100, 200, 103, 205)
    check(p1 == p2 and #p1.cells == 48 and p1.cells[1].z == 1 and #p1.lines == 3 and p1.lines[2] == "IGUI_MBLD_Roof_Warn_HALF"
        and fixed == "S" and #p3.lines == 3 and p3.lines[2] == "IGUI_MBLD_Roof_Warn_HALF",
        "屋頂（RoofPanel）預覽：同一範圍回同一份、天花板同格不重複畫；30、45 度都補天花板多一行提示；✗ 45 度單斜選朝北夾回朝南")
    -- 審查第 5 輪 R5-6：排法照世界現況（屋頂層已有地板的格子不補天花板）。同一範圍再問一次時世界沒變回同一份，
    -- 變了（中間鋪了一格地板）要重排，不回舊的那份
    st.set, st.shape, st.dir, st.gable, st.gableTs = s30, "gable", "EW", nil, ""
    local q1 = RP.preview(100, 200, 105, 207)
    square(100, 200, 1, { flags = { solidfloor = true } })
    local q2, q3 = RP.preview(100, 200, 105, 207), RP.preview(100, 200, 105, 207)
    squares["100,200,1"] = nil
    local q4 = RP.preview(100, 200, 105, 207)
    check(q1 ~= q2 and q2 == q3 and q4 ~= q3, "屋頂（RoofPanel）預覽：同一範圍中間鋪了一格地板，再問要重排（✗ 一直回舊的片數）；世界沒變回同一份")
    -- 複核 R5V-1：兩格地板換位置、片數不變：預覽的格子要跟著換（✗ 鍵只比片數，一直回舊的格子）
    local function hasCell(res, x, y, z)
        for _, c in ipairs(res.cells) do
            if c.x == x and c.y == y and c.z == z then return true end
        end
        return false
    end
    st.set = s45 -- 45 度往上疊：屋頂層有只補天花板、沒有屋頂片的格子（那格鋪了地板，預覽就沒有那一格）
    local only = {}
    for x = 100, 103 do
        for y = 200, 205 do
            if #only < 2 then
                square(x, y, 1, { flags = { solidfloor = true } })
                if not hasCell(RP.preview(100, 200, 103, 205), x, y, 1) then only[#only + 1] = { x, y } end
                squares[x .. "," .. y .. ",1"] = nil
            end
        end
    end
    local ca, cb = only[1] or { 0, 0 }, only[2] or { 0, 0 }
    square(ca[1], ca[2], 1, { flags = { solidfloor = true } })
    local sa = RP.preview(100, 200, 103, 205)
    squares[ca[1] .. "," .. ca[2] .. ",1"] = nil
    square(cb[1], cb[2], 1, { flags = { solidfloor = true } })
    local sb = RP.preview(100, 200, 103, 205)
    squares[cb[1] .. "," .. cb[2] .. ",1"] = nil
    st.set = s30
    check(#only == 2 and #sa.cells == #sb.cells and not hasCell(sa, ca[1], ca[2], 1) and hasCell(sa, cb[1], cb[2], 1)
        and hasCell(sb, ca[1], ca[2], 1) and not hasCell(sb, cb[1], cb[2], 1),
        "屋頂（RoofPanel）預覽：兩格地板換位置、片數不變，預覽的格子跟著換（✗ 只比片數，一直回舊的格子；找到 " .. #only .. " 格）")
    -- 大範圍（排一次超過 SLOW_MS）不每秒重排：SLOW_EVERY 內世界變了也回上一份，過了才重排
    local realLayoutR = Roof.layout
    Roof.layout = function(...)
        nowMs = nowMs + 10 -- 這一次排了 10 ms
        return realLayoutR(...)
    end
    local w1 = RP.preview(100, 200, 104, 207)
    square(100, 200, 1, { flags = { solidfloor = true } })
    local w2 = RP.preview(100, 200, 104, 207)
    nowMs = nowMs + RP.SLOW_EVERY
    local w3 = RP.preview(100, 200, 104, 207)
    Roof.layout = realLayoutR
    squares["100,200,1"] = nil
    check(w1 == w2 and w3 ~= w2, "屋頂（RoofPanel）預覽：排一次超過 SLOW_MS 的範圍，SLOW_EVERY 內再問回上一份（不每秒頓一下）；過了才照世界重排")
    st.set, st.shape, st.dir = s45, "gable", "EW" -- 後面的情境照 45 度雙斜
    -- 缺口補不了（底下沒有房子的牆）：預覽多一行說幾格；放開後也跳通知
    st.gable, st.gableTs = g45, "walls_exterior_roofs_01"
    local p4 = RP.preview(100, 200, 102, 207)
    toasts = {}
    local okGap = RP.release(100, 200, 102, 207)
    local gapToast = toasts[1]
    -- 選了山牆但它的貼圖還沒載好：留著選擇、不排（GABLE_WAIT），遮罩好了下一次預覽就認出來、照常排
    local pickLate = RP.pickGable("late_gable_02")
    local waitTs, waitG = st.gableTs, st.gable
    local p5 = RP.preview(100, 200, 102, 207)
    toasts = {}
    local before5 = calls
    local relLate = RP.release(100, 200, 102, 207)
    local lateToast, lateCalls = toasts[1], calls - before5
    lateMask["late_gable_02_15"] = nil
    local p6 = RP.preview(100, 200, 102, 207)
    check(p4.lines[3] == "IGUI_MBLD_Roof_Warn_GAP" and okGap and gapToast == "IGUI_MBLD_Roof_Warn_GAP",
        "屋頂（RoofPanel）跨距 8 配山牆、底下沒有房子的牆：預覽多一行「有幾格要自己補牆」，放開加進藍圖後也跳這句")
    check(pickLate and waitTs == "late_gable_02" and waitG == nil and p5.lines[1] == "IGUI_MBLD_Roof_Err_GABLE_WAIT"
        and relLate == false and lateToast == "IGUI_MBLD_Roof_Err_GABLE_WAIT" and lateCalls == 0
        and st.gable and st.gable.ts == "late_gable_02" and not st.gableWait and p6.lines[1] ~= "IGUI_MBLD_Roof_Err_GABLE_WAIT",
        "屋頂（RoofPanel）選了山牆但貼圖還沒載好：選擇留著（不退回不放）、預覽與放開說「還在載入」、不加進藍圖；"
            .. "遮罩好了下一次預覽就認出來照常排，不用重選")
    st.gable, st.gableTs, st.gableWait = nil, "", false
    B.PlanMode.addMany = nil
    local avNo, avNoLate = RP.available("late_roofs_30b_0")
    B.PlanMode.addMany = function(_, groups)
        calls, last = calls + 1, groups
        return ret[1], ret[2]
    end
    local av1, av1Late = RP.available("late_roofs_30b_0")
    local avBad, avBadLate = RP.available("roofs_shallow_x_0")
    lateMask["late_roofs_30b_3"] = nil
    local av2, av2Late = RP.available("late_roofs_30b_0")
    check(avNo == false and avNoLate == false and av1 == false and av1Late == true and avBad == false and avBadLate == false
        and av2 == true and av2Late == false,
        "屋頂（RoofPanel）available 第二個回傳：貼圖還沒載好是 true（呼叫的不要記住），認不出、沒有 addMany 是 false；載好後回 true")

    do -- 審查 RB1：平頂、四坡已選山牆；每一族 × 形狀 × 方向 × 有／沒有山牆 × 跨距都不丟錯
        local LEGAL = { TOO_SMALL = true, TOO_WIDE = true, ODD_SPAN = true, TOO_HIGH = true, DISABLED = true }
        local SIZES = { 1, 2, 3, 5, 6, 7, 8, 11, 12, 13, 25 }
        local runs, bad = 0, nil
        for _, c in ipairs({ { s30, g30 }, { m30, g30 }, { s45, g45 }, { s45b, g45 }, { m45, g45 } }) do
            for _, sh in ipairs(Roof.shapes(c[1])) do
                for _, dd in ipairs(#sh.dirs > 0 and sh.dirs or { false }) do
                    for _, gb in ipairs({ false, c[2] }) do
                        for _, w in ipairs(SIZES) do
                            for _, h in ipairs(SIZES) do
                                runs = runs + 1
                                local okL, gr, code = pcall(L, c[1], sh.id, dd or nil, w, h, gb or nil)
                                if not (okL and (gr ~= nil or LEGAL[code])) and not bad then
                                    bad = c[1].ts .. "@" .. c[1].base .. " " .. sh.id .. "/" .. tostring(dd) .. "/"
                                        .. tostring(gb and gb.ts) .. " " .. w .. "x" .. h .. "：" .. tostring(gr)
                                end
                            end
                        end
                    end
                end
            end
        end
        check(bad == nil and runs > 2000, "屋頂（Roof）矩陣 " .. runs .. " 種（30／45 度 × 形狀 × 方向 × 山牆 × 跨距 1–25）："
            .. "不丟錯，回 groups 或合法的錯誤碼" .. (bad and "；第一個壞的 " .. bad or ""))
        local function walls(groups)
            local n = 0
            for _, gg in ipairs(groups or {}) do if gg.id:find("^walls_") then n = n + #gg.cells end end
            return n
        end
        local fg, hg, h0 = L(s45, "flat", nil, 3, 3, g45), L(s45, "hip", nil, 6, 6, g45), L(s45, "hip", nil, 6, 6)
        local hg30 = L(s30, "hip", nil, 5, 7, g30)
        check(fg and total(fg) == 9 and walls(fg) == 0 and hg and total(hg) == total(h0) and walls(hg) == 0
            and hg30 and walls(hg30) == 0, "屋頂（Roof）✗ 平頂、四坡已選山牆：照常排出整個屋頂，沒有牆片")
    end

    do -- 審查 RB2、RB3、RB8：面板的建構、選項、山牆保護、建不起來、開關不留視窗、手把
        local realG = { spec = getSpecificPlayer, joy = JoypadState, font = UIFont, tm = getTextManager, panel = ISPanel,
            left = getPlayerScreenLeft, top = getPlayerScreenTop, sw = getPlayerScreenWidth, sh = getPlayerScreenHeight,
            wui = B.Window.ui }
        local player = { getZ = function() return 2 end }
        getSpecificPlayer = function() return player end
        JoypadState = { players = {} }
        UIFont = UIFont or { Small = 0 }
        getTextManager = function()
            return { getFontHeight = function() return 16 end, MeasureStringX = function(_, _, s) return #s * 7 end }
        end
        getPlayerScreenLeft, getPlayerScreenTop = function() return 0 end, function() return 0 end
        getPlayerScreenWidth, getPlayerScreenHeight = function() return 1920 end, function() return 1080 end
        -- 假框架（同 HotbarImport 段）：元件只記狀態；inUI＝UIManager 裡的視窗；close 照框架 Window:close（只隱藏、叫 onClose）
        local noop, inUI = function() end, {}
        local E = { initialise = noop, bringToTop = noop }
        function E.addToUIManager(s) inUI[s] = true end
        function E.removeFromUIManager(s) inUI[s] = nil end
        function E.addChild(s, c) s.children[#s.children + 1] = c end
        function E.setX(s, v) s.x = v end
        function E.setY(s, v) s.y = v end
        function E.getX(s) return s.x end
        function E.setHeight(s, v) s.height = v end
        function E.setVisible(s, v) s.visible = v end
        function E.setEnabled(s, v) s.enabled = v end
        function E.setTooltip(s, t) s.tooltip = t end
        function E.contentTop() return 24 end
        function E.setOptions(s, o) s.options = o end
        function E.setSelected(s, id) s.selected = id end
        function E.close(s)
            s.visible = false
            if s.onClose then s.onClose(s) end
        end
        local function el(o)
            o.x, o.y, o.width, o.height = o.x or 0, o.y or 0, o.width or 30, o.height or 20
            o.children, o.visible, o.enabled = {}, true, true
            return setmetatable(o, { __index = E })
        end
        local col = { r = 1, g = 1, b = 1 }
        local theme = function() return { colors = { text = col, textMuted = col, warning = col } } end
        local UI = { Theme = { create = theme }, Text = { wrap = function(s) return { s } end },
            Window = { new = function(o) return el({ width = o.width, height = o.height, title = o.title, onClose = o.onClose }) end },
            Button = { new = function(o) return el({ title = o.title, onClick = o.onClick }) end },
            Dropdown = { new = function(o)
                return el({ width = o.width, options = o.options, selected = o.selected, target = o.target, onChange = o.onChange })
            end, close = noop } }
        B.Window.ui = function() return UI end
        ISPanel = { new = function(_, x, y, w, h) return el({ x = x, y = y, width = w, height = h }) end }
        local function shown()
            local n = 0
            for _ in pairs(inUI) do n = n + 1 end
            return n
        end
        local pm = { on = false, toggles = 0, levels = 0 }
        ret, calls = { 9 }, 0
        B.PlanMode = { addMany = function(_, groups)
                calls, last = calls + 1, groups
                return ret[1], ret[2]
            end, planning = function() return pm.on end, level = function() return 1 end,
            toggle = function()
                pm.toggles, pm.on = pm.toggles + 1, true
                return true
            end, setLevel = function(n) pm.levels, pm.lastLevel = pm.levels + 1, n end }

        -- RB2：建窗丟錯 → 回 false、跳通知；規劃、樓層、選擇都不動
        st.pn, st.set, st.shape, st.dir, st.gable, st.gableTs = 0, s30, "hip", nil, nil, ""
        UI.Theme.create = function() error("boom") end
        toasts = {}
        local failed = RP.open(0, "roofs_01_3")
        UI.Theme.create = theme
        check(failed == false and toasts[1] == "IGUI_MBLD_Roof_BuildFailed" and pm.toggles == 0 and pm.levels == 0
            and st.set == s30 and st.shape == "hip" and RP.panel == nil and shown() == 0,
            "屋頂（RoofPanel）✗ 面板建不起來：回 false、跳通知，規劃、樓層、上次的選擇都不動")

        -- RB8：建出面板、換形狀與方向、山牆保護
        toasts = {}
        local opened = RP.open(0, "roofs_01_3")
        local p = RP.panel
        check(opened == true and p and p.win.visible and inUI[p.win] and pm.toggles == 1 and pm.lastLevel == 3
            and st.set == s45 and #toasts == 0, "屋頂（RoofPanel）open：建出面板、加進畫面，再開規劃、樓層設成玩家那層加 1")
        p.shapeDD.onChange(p.shapeDD.target, "shed")
        local shedDirs = #p.dirDD.options
        p.dirDD.onChange(p.dirDD.target, "E")
        local shedOk = st.shape == "shed" and st.dir == "E" and shedDirs == 2 and p.dirDD.enabled and p.gableDD.enabled
        p.shapeDD.onChange(p.shapeDD.target, "flat")
        check(shedOk and st.shape == "flat" and st.dir == nil and p.dirDD.enabled == false and p.gableDD.enabled == false,
            "屋頂（RoofPanel）換形狀、方向：RP.st 跟著變；45 度單斜只有兩個方向；平頂停用方向與山牆下拉")
        p.gableDD.onChange(p.gableDD.target, "walls_exterior_roofs_01")
        local pickedOk = st.gableTs == "walls_exterior_roofs_01" and st.gable == g45 and not p.gableBad
        p.gableDD.onChange(p.gableDD.target, "walls_exterior_roofs_30_01")
        check(pickedOk and p.gableBad == true and st.gableTs == "" and st.gable == nil and p.gableDD.selected == ""
            and RP.pickGable("walls_exterior_roofs_30_01") == false,
            "屋頂（RoofPanel）山牆：同坡度的組選得到；✗ 坡度不同的組回 false，選擇清回不放、跳警告")
        -- RB1 從面板：選了山牆再切平頂，預覽與放開照常
        RP.pickGable("walls_exterior_roofs_01")
        local pv = RP.preview(300, 300, 302, 302)
        calls, toasts = 0, {}
        local rel = RP.release(300, 300, 302, 302)
        check(#pv.cells == 9 and rel and calls == 1 and total(last) == 9 and #toasts == 0,
            "屋頂（RoofPanel）選了山牆再切平頂：預覽 9 格、放開整批加進藍圖")

        -- RB3：開關幾次、開著再開，畫面裡最多一個屋頂面板
        for _ = 1, 4 do
            RP.open(0, "roofs_01_3")
            RP.panel.win:close()
        end
        local afterClose = shown()
        RP.open(0, "roofs_01_3")
        RP.open(0, "roofs_01_3")
        check(afterClose == 0 and shown() == 1 and RP.panel and inUI[RP.panel.win],
            "屋頂（RoofPanel）開關 4 次後畫面裡沒有留下視窗；開著再開只剩新的一個")
        RP.panel.win:close()

        -- RB8：手把玩家
        JoypadState = { players = { true } }
        toasts = {}
        RP.open(0, "roofs_01_3")
        local dragBtn
        for _, c in ipairs(RP.panel.win.children) do if c.title == "IGUI_MBLD_Roof_Drag" then dragBtn = c end end
        local o = RP.drag(0)
        check(o == nil and toasts[#toasts] == "IGUI_MBLD_Roof_Drag_Pad" and dragBtn and dragBtn.enabled == false
            and dragBtn.tooltip == "IGUI_MBLD_Roof_Drag_Pad", "屋頂（RoofPanel）✗ 手把：拖出範圍鈕停用並附說明；RP.drag 回 nil、跳通知")
        RP.panel.win:close()

        getSpecificPlayer, JoypadState, UIFont, getTextManager, ISPanel = realG.spec, realG.joy, realG.font, realG.tm,
            realG.panel
        getPlayerScreenLeft, getPlayerScreenTop, getPlayerScreenWidth, getPlayerScreenHeight = realG.left, realG.top,
            realG.sw, realG.sh
        B.Window.ui = realG.wui
    end

    st.pn, st.set, st.shape, st.dir, st.gable, st.gableTs = nil, nil, nil, nil, nil, ""
    B.PlanMode, B.Messages.toast, sb.DisabledTilesets = real.PM, real.toast, real.tiles
    local gone = {}
    for _, name in ipairs(added) do spriteMap[name], gone[name] = nil, true end
    for i = #spriteOrder, 1, -1 do if gone[spriteOrder[i].name] then table.remove(spriteOrder, i) end end
end)()

-- ===== 建造時顯示同層屋頂（RoofShow） =====
;(function()
    print("建造時顯示同層屋頂（RoofShow：游標渲染前換替身、同一段繪製的 DoBuilding 換回、存檔不換、各玩家分開掃與重畫、載入格子修正）")
    local B = MinidoracatBuilder
    require "MinidoracatBuilder/Rules"
    require "MinidoracatBuilder/RoofShow"
    local RS, Rules = B.RoofShow, B.Rules
    local function roof(name, id, t)
        local o = { type = t } -- 不帶 RoofGroup：分類只能靠型別
        local s = sprite(name, id, o)
        function s:setTileType(v) o.type = v end
        return s
    end
    local sB, sM, sT = roof("rs_01_0", 41000, T.WestRoofB), roof("rs_01_1", 41001, T.WestRoofM), roof("rs_01_2", 41002, T.WestRoofT)
    local flat = roof("rs_01_3", 41003, T.WestRoofB) -- 擺在不是斜屋頂的格子：不掃
    local tiled = roof("rs_01_4", 41004, T.UNUSED10) -- 圖塊包合法用的 UNUSED10（引擎接受的 tiledef 型別），和斜屋頂同格
    local function obj(s) return { getSprite = function() return s end } end
    local function sq(slope, list)
        local objs = {}
        for i, s in ipairs(list) do objs[i] = obj(s) end
        return { HasSlopedRoof = function() return slope end, getObjects = function() return javaList(objs) end }
    end
    local sqs = { ["10,10,1"] = sq(true, { sprite("rs_02_0", 41010, {}), sB, sM }), ["14,12,1"] = sq(true, { sT }),
        ["11,10,1"] = sq(false, { flat }), ["12,9,0"] = sq(true, { flat }) }
    local real = { cell = getCell, spec = getSpecificPlayer, clock = getTimestampMs, opts = B.Window and B.Window.options,
        fbo = FBORenderChunk }
    local px, now, tick = 10, 1000, { v = false, getValue = function(t) return t.v end }
    local p = { getX = function() return px + 0.5 end, getY = function() return 10.5 end, getZ = function() return 1 end }
    local p1 = { getX = function() return 200.5 end, getY = function() return 200.5 end, getZ = function() return 1 end }
    local inval = {}
    local function chunkMap(pn)
        return {
            getWidthInTiles = function() return 8 * 13 end,
            getChunk = function(_, i, j)
                return { invalidateRenderChunkLevel = function(_, z, f) inval[#inval + 1] = pn .. ":" .. i .. "," .. j .. "," .. z .. "," .. f end }
            end,
        }
    end
    local cellObj = {
        getGridSquare = function(_, x, y, z) return sqs[x .. "," .. y .. "," .. z] end,
        getChunkMap = function(_, pn) return chunkMap(pn) end,
    }
    getCell = function() return cellObj end
    getSpecificPlayer = function(pn) return (pn == 0 and p) or (pn == 1 and p1) or nil end
    getTimestampMs = function() return now end
    FBORenderChunk = { DIRTY_REDRAW = 7 }
    B.Window = B.Window or {}
    B.Window.options = { getOption = function(_, id) return id == "ShowRoofs" and tick or nil end }
    local cur = { player = 0 }
    local function types() return { sB:getType(), sM:getType(), sT:getType(), flat:getType() } end
    local function same(a, b) return a[1] == b[1] and a[2] == b[2] and a[3] == b[3] and a[4] == b[4] end
    local orig = { T.WestRoofB, T.WestRoofM, T.WestRoofT, T.WestRoofB }
    local swappedTypes = { T.UNUSED9, T.UNUSED10, T.UNUSED24, T.WestRoofB }
    local function hooked(name, fn)
        for _, f in ipairs(handlers[name] or {}) do if f == fn then return true end end
        return false
    end
    local function mine(name) -- RoofShow.lua 掛的那一個（別的模組也可能掛在同一事件）
        for _, f in ipairs(handlers[name] or {}) do
            if debug.getinfo(f, "S").source:find("RoofShow", 1, true) then return f end
        end
    end
    local function count(name)
        local n = 0
        for _, f in ipairs(handlers[name] or {}) do
            if debug.getinfo(f, "S").source:find("RoofShow", 1, true) then n = n + 1 end
        end
        return n
    end
    local tickFn, saveFn = mine("OnTickEvenPaused"), mine("OnSave")

    check(type(B.Cursor.beforeWorldRender) == "function", "建造游標掛了 beforeWorldRender（Cursor.lua 的 base 會複製過去）")
    B.Cursor.beforeWorldRender(cur)
    check(same(types(), orig), "選項關著：渲染前不換型別")
    tickFn()
    check(count("LoadGridsquare") == 0, "選項沒開過：不掛 LoadGridsquare（每載入一格叫一次）")

    tick.v = true
    B.Cursor.beforeWorldRender(cur)
    check(same(types(), swappedTypes), "選項開著：同層斜屋頂格的 WestRoofB/M/T 換成替身，不是斜屋頂的格子、別層不動")
    local loadFn = mine("LoadGridsquare")
    check(count("LoadGridsquare") == 1, "換過型別才掛 LoadGridsquare")
    check(Rules.typeCode(T.UNUSED9) == nil, "Rules 不認替身：游標 render 在換回之後")
    B.Cursor.beforeWorldRender(cur)
    check(sB:getType() == T.UNUSED9, "同一段繪製再叫一次照樣是換著的")
    -- 換回要排在原版 DoTileBuilding（server 資料夾，較晚註冊）前面：它會補建游標格子、叫游標 render
    check(hooked("OnDoTileBuilding2", RS.restore) and hooked("OnDoTileBuilding3", RS.restore)
        and hooked("OnPostRender", RS.restore), "換回掛在 DoBuilding（滑鼠、手把）與世界畫完（OnPostRender）")
    local seenInBuild
    local vanilla = function() seenInBuild = sB:getType() end
    Events.OnDoTileBuilding2.Add(vanilla)
    fire("OnDoTileBuilding2", cur, true, 10, 10, 1, nil)
    Events.OnDoTileBuilding2.Remove(vanilla)
    check(seenInBuild == T.WestRoofB and same(types(), orig), "DoBuilding 時先換回，之後註冊的處理（原版補建格子、游標 render）讀到原型別")

    B.Cursor.beforeWorldRender(cur)
    check(sM:getType() == T.UNUSED10, "下一幀沿用清單再換")
    RS.restore()
    RS.restore()
    check(same(types(), orig), "連叫兩次換回不出錯、還是原型別")

    -- 存檔：OnSave 之後畫縮圖（只叫 beforeWorldRender、不發 OnPostRender），到下一次世界更新前都不換
    check(type(saveFn) == "function" and type(tickFn) == "function", "掛了 OnSave、OnTickEvenPaused")
    B.Cursor.beforeWorldRender(cur)
    saveFn()
    check(same(types(), orig), "存檔先換回")
    B.Cursor.beforeWorldRender(cur)
    check(same(types(), orig), "存檔縮圖的那段繪製不換")
    tickFn()
    B.Cursor.beforeWorldRender(cur)
    check(sB:getType() == T.UNUSED9, "下一次世界更新後照常換")
    RS.restore()

    -- 換回中途出錯：沒換回的下次還要換回
    local boom = true
    local realSet = sM.setTileType
    function sM:setTileType(v) if boom and v == T.WestRoofM then boom = false error("boom") end realSet(self, v) end
    B.Cursor.beforeWorldRender(cur)
    check(not pcall(RS.restore), "（植入）換回時 setTileType 出錯")
    RS.restore()
    check(same(types(), orig), "換回中途出錯後，下一次換回把剩下的也換回")
    sM.setTileType = realSet

    -- 移動了但未滿重掃間隔：新格子的屋頂不收；圖塊包本來就是 UNUSED10 的 sprite 從來不算替身
    local late = roof("rs_01_7", 41007, T.WestRoofM)
    sqs["13,10,1"] = sq(true, { tiled, late })
    px = 11
    B.Cursor.beforeWorldRender(cur)
    check(late:getType() == T.WestRoofM, "移動了但未滿重掃間隔：不重掃")
    RS.restore()
    check(late:getType() == T.WestRoofM and tiled:getType() == T.UNUSED10, "不在清單裡的不動：換回只換回自己換的")
    now = now + 500
    B.Cursor.beforeWorldRender(cur)
    check(late:getType() == T.UNUSED10 and tiled:getType() == T.UNUSED10, "重掃後新格子的屋頂也換；本來就是 UNUSED10 的不收")
    RS.restore()
    check(late:getType() == T.WestRoofM and same(types(), orig), "自己換過的都換回原型別")
    check(tiled:getType() == T.UNUSED10, "從沒換過、型別剛好是替身的 sprite 保持原樣（不改成 WestRoofM）")

    -- 站著不動：附近新出現的屋頂款式也收進來
    local fresh = roof("rs_01_5", 41005, T.WestRoofT)
    sqs["12,11,1"] = sq(true, { fresh })
    now = now + 500
    B.Cursor.beforeWorldRender(cur)
    check(fresh:getType() == T.UNUSED24, "站著不動滿重掃間隔：新出現的屋頂也換")
    RS.restore()

    -- 分割畫面：玩家 1 的掃描位置與計時器自己一份
    local far = roof("rs_01_6", 41006, T.WestRoofB)
    sqs["200,200,1"] = sq(true, { far })
    B.Cursor.beforeWorldRender(cur)
    B.Cursor.beforeWorldRender({ player = 1 })
    check(far:getType() == T.UNUSED9, "玩家 1 剛換手也馬上掃自己附近（不被玩家 0 的計時器擋住）")
    check(same(types(), orig), "輪到玩家 1 時先換回玩家 0 換的（玩家 0 那段沒走到 DoBuilding）")
    B.Cursor.beforeWorldRender(cur)
    check(far:getType() == T.WestRoofB and sB:getType() == T.UNUSED9, "再輪回玩家 0：換回玩家 1 的、換玩家 0 的")
    RS.restore()

    -- 收起游標後：那位玩家 chunk map 裡每一塊、換著時的那一層標髒重畫（sprite 全圖共用，視野內哪一塊重畫都可能烤到）
    tickFn()
    tickFn()
    inval = {}
    px = 10
    now = now + 500
    B.Cursor.beforeWorldRender(cur)
    RS.restore()
    tickFn()
    check(#inval == 0, "游標還拿著：不重畫")
    tickFn()
    local function hits()
        local h, n0, n1 = {}, 0, 0
        for _, k in ipairs(inval) do
            h[k] = true
            if k:sub(1, 2) == "0:" then n0 = n0 + 1 else n1 = n1 + 1 end
        end
        return h, n0, n1
    end
    local hit, n0, n1 = hits()
    check(n0 == 169 and n1 == 0 and hit["0:0,0,1,7"] and hit["0:12,12,1,7"] and hit["0:6,6,1,7"],
        "收起游標後下一次世界更新：那位玩家 chunk map 13x13 塊（含 7x7 以外）的那一層標 DIRTY_REDRAW")
    inval = {}
    tickFn()
    check(#inval == 0, "只重畫一次")

    -- 分割畫面：一人還拿著、另一人收起 → 收起的那位照樣重畫
    now = now + 500
    B.Cursor.beforeWorldRender(cur)
    B.Cursor.beforeWorldRender({ player = 1 })
    RS.restore()
    tickFn()
    inval = {}
    B.Cursor.beforeWorldRender(cur)
    RS.restore()
    tickFn()
    hit, n0, n1 = hits()
    check(n0 == 0 and n1 == 169 and hit["1:12,0,1,7"], "分割畫面：玩家 0 還拿著、玩家 1 收起了 → 只重畫玩家 1 的 chunk map")
    inval = {}
    tickFn()
    hit, n0, n1 = hits()
    check(n0 == 169 and n1 == 0, "玩家 0 也收起 → 再重畫玩家 0 的")

    -- 載入格子：換著時串流執行緒算的型別帶替身，主執行緒載入時重算；算好的 chunk 何時交付沒有上限，掛上就不拿掉
    local recalc = 0
    local function loadSq(bits)
        return { has = function(_, t) return bits[t] == true end, RecalcProperties = function() recalc = recalc + 1 end }
    end
    loadFn(loadSq({ [T.UNUSED10] = true }))
    loadFn(loadSq({ [T.WestRoofB] = true }))
    check(recalc == 1, "載入的格子帶替身才重算")
    now = now + 600000 -- 收起游標後暫停十分鐘（OnTickEvenPaused 照跑）
    for _ = 1, 50 do tickFn() end
    local late2 = mine("LoadGridsquare")
    check(count("LoadGridsquare") == 1 and late2 ~= nil, "用過一次：暫停很久之後還掛著")
    if late2 then late2(loadSq({ [T.UNUSED24] = true })) end
    check(recalc == 2, "換著時算好、很久之後才交付的格子照樣重算")
    B.Cursor.beforeWorldRender(cur)
    RS.restore()
    check(count("LoadGridsquare") == 1, "再拿游標換型別：不重複掛")

    -- 接線游標（Wiring.lua 的 MinidoracatBuilderWireCursor）也照樣換
    require "MinidoracatBuilder/Wiring"
    local function upv(f, name)
        for i = 1, 200 do
            local n, v = debug.getupvalue(f, i)
            if n == nil then return nil end
            if n == name then return v end
        end
    end
    local WC = upv(upv(B.Wiring.open, "newCursor"), "WireCursor")
    check(WC ~= nil and type(WC.beforeWorldRender) == "function", "接線游標掛了 beforeWorldRender")
    if WC and WC.beforeWorldRender then
        now = now + 500
        WC.beforeWorldRender({ player = 0 })
        check(same(types(), swappedTypes), "接線游標：渲染前同樣換替身")
        RS.restore()
    end
    tickFn()
    tickFn()

    for _, s in ipairs({ "10,10,1", "14,12,1", "11,10,1", "12,9,0", "13,10,1", "12,11,1", "200,200,1" }) do sqs[s] = nil end
    getCell, getSpecificPlayer, getTimestampMs, B.Window.options, FBORenderChunk = real.cell, real.spec, real.clock, real.opts, real.fbo
end)()

-- ===== 藍圖檢查分幀（PlanPerf） =====
;(function()
    print("藍圖檢查分幀（PlanCheck 重排分幀、busy、sweep；Runner 重排中不誤判沒得蓋、坡道一批一片）")
    local B = MinidoracatBuilder
    require "MinidoracatBuilder/Plan"
    require "MinidoracatBuilder/PlanCheck"
    require "MinidoracatBuilder/Queue"
    require "MinidoracatBuilder/PlanStore"
    require "MinidoracatBuilder/Runner"
    local Plan, PC, R, Q, PS = B.Plan, B.PlanCheck, B.Runner, B.Queue, B.PlanStore
    local real = { PM = B.PlanMode, PC = B.PlanCheck, rec = B.Recipes, cell = getCell, clock = getTimestampMs,
        inst = instanceof, item = Check.item, summary = Materials.summary, same = Materials.same, resolve = Entry.resolve,
        face = Entry.face, alt = Entry.alternate, cells = Entry.cells, doorSet = Entry.doorSet, why = Entry.why,
        digest = Entry.digest, rampSet = Entry.rampSet, sprite = Entry.sprite, push = Q.push, cancel = Q.cancel,
        busy = Q.busy, load = PS.load, ui = MinidoracatUI, core = Core, q = ISTimedActionQueue, specific = getSpecificPlayer,
        max = sb.MaxCellsPerDrag }
    B.Recipes = nil
    -- 時鐘：每幀（frame）前進 200 ms；一幀裡從第 slowAt 次讀起已經超過預算，之後一直超過（同一幀內單調不減）。
    -- 一幀讀時鐘的順序：tick 的 now、drain 每看完一段 256 片一次、算片的迴圈每片一次（fresh 會多讀一次 sAt）
    local T, reads, slowAt = 9000000, 0, nil
    getTimestampMs = function()
        reads = reads + 1
        if slowAt and reads >= slowAt then return T + 100 end
        return T
    end
    -- 假世界：evals＝每格被 evaluate 幾次（每片算一次讀一次 getChunkForGridSquare），items＝Check.item 被叫幾次
    local evals, items, SQS, CODE, SHORT, HOLES = {}, {}, {}, {}, true, {}
    local function sqAt(x, y, z)
        local k = x .. "," .. y .. "," .. z
        local s = SQS[k]
        if not s then
            s = { objs = {} }
            function s:getObjects() return javaList(self.objs) end
            function s:has(f) return f == IsoFlagType.solidfloor and self.floor == true end
            SQS[k] = s
        end
        return s
    end
    local cellObj = {
        getChunkForGridSquare = function(_, x, y) local k = x .. "," .. y; evals[k] = (evals[k] or 0) + 1; return true end,
        getGridSquare = function(_, x, y, z)
            if HOLES[x .. "," .. y .. "," .. z] then return nil end
            return sqAt(x, y, z)
        end,
    }
    getCell = function() return cellObj end
    instanceof = function() return false end
    local function tile(name) return { getSprite = function() return { getName = function() return name end } end } end
    local function fspr(name) return { getName = function() return name end, name = name } end
    -- 坡道 pp_ramp：頭片、兩片中段沿 +x，坡頂往前一格、上一層是平台
    local ENT = { pp_a = { kind = "floor", spr = "pp_a" }, pp_ramp = { kind = "ramp", spr = "pp_ramp" } }
    local RAMP = { n = 3, dx = 1, dy = 0 }
    Entry.resolve = function(id) return ENT[id] end
    Entry.face = function(e) return fspr(e.spr) end
    Entry.alternate = function(s) return s end
    Entry.cells = function(spr)
        if spr.name == "pp_ramp" then
            return { { 0, 0, 0, fspr("pp_ramp") }, { 1, 0, 0, fspr("pp_ramp_1") }, { 2, 0, 0, fspr("pp_ramp_2") },
                { 3, 0, 1, fspr("pp_deck"), "platform" } }
        end
        return { { 0, 0, 0, spr.name } }
    end
    Entry.rampSet = function(spr) return spr and spr.name == "pp_ramp" and RAMP or nil end
    Entry.sprite = function(name) return (name == "pp_ramp" or name == "pp_a") and fspr(name) or nil end
    Entry.doorSet = function() return nil end
    Entry.why = function() return "UNKNOWN" end
    local DG = "pp1"
    Entry.digest = function() return DG end
    Check.item = function(_, _, _, a)
        local k = a[1] .. "," .. a[2]
        items[k] = (items[k] or 0) + 1
        return CODE[k] or (SHORT and "NO_MATERIAL" or nil)
    end
    local MG = 1
    Materials.summary = function() return { gen = MG } end
    Materials.same = function(a, b) return a ~= nil and b ~= nil and a.gen == b.gen end
    local OX, OY = 500, 500
    local pl
    B.PlanMode = { plan = function() return pl end, origin = function() return OX, OY, 0 end, playerNum = 0 }
    local K = player({ id = 91, x = 532.5, y = 532.5 })
    local function frame(slow)
        T = T + 200
        reads, slowAt = 0, slow
        PC.tick(K)
    end
    -- 跑到 busy() 變 false：回跑了幾幀（上限 200，沒停表示卡住）
    local function settle(slow)
        local f = 0
        repeat
            f = f + 1
            frame(slow)
        until not PC.busy() or f >= 200
        return f
    end
    local function sum(t)
        local n = 0
        for _, v in pairs(t) do n = n + v end
        return n
    end
    -- 每片 Check.item 幾次：最少、最多
    local function spread(plan)
        local lo, hi = math.huge, 0
        Plan.each(plan, function(p)
            local n = items[(p.x + OX) .. "," .. (p.y + OY)] or 0
            if n < lo then lo = n end
            if n > hi then hi = n end
        end)
        return lo, hi
    end
    local function allState(plan, want)
        local bad = 0
        Plan.each(plan, function(p) if PC.state(p) ~= want then bad = bad + 1 end end)
        return bad
    end
    -- 64×64 一層地板（skip＝不放的那一格 "x,y"），全部算完（缺料）再清掉計數
    local function bigPlan(skipKey)
        pl = Plan.new("perf")
        local it = Plan.item(pl, "pp_a")
        for i = 0, 4095 do
            local x, y = i % 64, math.floor(i / 64)
            if x .. "," .. y ~= skipKey then Plan.add(pl, x, y, 0, 0, 0, it) end
        end
        SHORT, CODE = true, {}
        PC.reset()
        frame(nil)
        local ok = not PC.busy() and allState(pl, "short") == 0
        evals, items = {}, {}
        return ok
    end
    -- 材料變了：下一次比摘要（SUMMARY_MS 後）時重排
    local function materialsChange()
        SHORT, MG, T = false, MG + 1, T + PC.SUMMARY_MS
    end

    -- 每片 Check.item 剛好 k 次的片數
    local function times(plan, k)
        local n = 0
        Plan.each(plan, function(p) if (items[(p.x + OX) .. "," .. (p.y + OY)] or 0) == k then n = n + 1 end end)
        return n
    end

    -- 1. 4,096 片算完後改材料，預算一直超過：重排每幀看一段（身邊 12 圈分 3 幀看完，第 3 幀接著看清單第一段，
    --    之後每幀一段 256 片），18 幀看完（第 19 幀不再為重排讀時鐘）；同時每幀只算一片，其餘積在佇列（busy() 是 true）。
    --    之後預算夠時算完，每片剛好一次
    local ready = bigPlan(nil)
    materialsChange()
    local frameReads = {}
    for f = 1, 19 do
        frame(2)
        frameReads[f] = reads
    end
    local scanFrames = 0
    for f = 1, 18 do if frameReads[f] == 3 then scanFrames = scanFrames + 1 end end
    local evaluated, backlog = sum(items), PC.busy()
    local nearOnly = true -- 算過的 19 片都在玩家（532,532）身邊 2 格內：身邊先排、由近到遠算（✗ 不是清單前段的遠片）
    for k in pairs(items) do
        local x, y = k:match("^(%-?%d+),(%-?%d+)$")
        if math.max(math.abs(tonumber(x) - 532), math.abs(tonumber(y) - 532)) > 2 then nearOnly = false end
    end
    check(ready and pl.n == 4096 and scanFrames == 18 and frameReads[19] == 2,
        "重排分幀：預算超過時每幀只看一段（✗ 不是一幀 4,096 片），身邊 3 幀＋清單 16 段共 18 幀看完、第 19 幀不再排")
    check(evaluated == 19 and backlog == true,
        "重排分幀：超過預算的幀只算一片（19 幀算了 " .. evaluated .. " 片），佇列還有待算片時 busy() 是 true")
    check(nearOnly, "重排先排玩家身邊：前 19 幀算的都是身邊 2 格內的片（✗ 不是清單前段、離玩家遠的片）")
    settle(nil)
    local lo, hi = spread(pl)
    check(not PC.busy() and lo == 1 and hi == 1 and sum(items) == 4096 and allState(pl, "ok") == 0,
        "重排分幀：預算夠時把積壓算完，每片 Check.item 剛好一次、全部變能蓋")

    -- 2. 時鐘不是每片都讀：走開 MOVE 格重排 far（沒有 far 的片），一幀讀 1＋身邊 2＋4,096／256 次
    K.pos.x = K.pos.x + PC.MOVE + 1
    frame(nil)
    local farReads = reads
    K.pos.x = 532.5
    frame(nil)
    check(farReads == 1 + 2 + 4096 / 256 and not PC.busy(), "重排每 256 片（格）才看一次時鐘（這一幀讀了 " .. farReads .. " 次）")

    -- 2b. 放下 4,096 片的藍圖：那一幀只建清單，片不一次全排（同步掃描照重排的分幀、身邊先排）。預算一直超過時
    --     第 1 幀讀時鐘 4 次（tick 的 now、fresh 的 sAt、看完身邊 6 圈、算一片），之後每幀 3 次到 18 幀看完、第 19 幀 2 次；
    --     第 1 幀算的是玩家腳下那片。之後預算夠時每片剛好一次
    pl = Plan.new("place")
    local pa = Plan.item(pl, "pp_a")
    for i = 0, 4095 do Plan.add(pl, i % 64, math.floor(i / 64), 0, 0, 0, pa) end
    SHORT, CODE = true, {}
    PC.reset()
    evals, items = {}, {}
    local placeReads, firstEval = {}, nil
    for f = 1, 19 do
        frame(2)
        placeReads[f] = reads
        if f == 1 then firstEval = next(items) end
    end
    local placeScan = 0
    for f = 2, 18 do if placeReads[f] == 3 then placeScan = placeScan + 1 end end
    local placeBusy = PC.busy()
    settle(nil)
    lo, hi = spread(pl)
    check(placeReads[1] == 4 and placeScan == 17 and placeReads[19] == 2 and firstEval == "532,532" and placeBusy
        and lo == 1 and hi == 1 and sum(items) == 4096 and allState(pl, "short") == 0,
        "放下 4,096 片的藍圖：片分 18 幀排進佇列（✗ 不是放下那一幀全排）、身邊先算；之後每片剛好一次")

    -- 3. 重排到一半、佇列裡還有待算片時加一片（rev 變、清單與佇列重建）：不漏、不重複、不越界
    ready = bigPlan("63,63")
    materialsChange()
    for _ = 1, 8 do frame(2) end -- 看過身邊與清單前 1,536 片、只算了 8 片，其餘積在佇列
    local partial = sum(items)
    Plan.add(pl, 63, 63, 0, 0, 0, Plan.item(pl, "pp_a"))
    for _ = 1, 4 do frame(2) end
    local fine, err = pcall(settle, nil)
    lo, hi = spread(pl)
    check(ready and partial == 8 and fine and pl.n == 4096 and lo == 1 and hi == 1 and sum(items) == 4096
        and allState(pl, "ok") == 0 and not PC.busy(),
        "重排到一半、佇列還有待算片時加一片：每片（含新的）剛好一次，舊佇列不留重複" .. (fine and "" or " " .. tostring(err)))
    -- 重排到一半拿掉一大半（清單變短、比目前索引還短）：沒出錯，留下的每片剛好一次，拿掉的不再算
    ready = bigPlan(nil)
    materialsChange()
    for _ = 1, 4 do frame(2) end -- 看過身邊與清單前 512 片、算了 4 片
    local drop = {}
    Plan.each(pl, function(p) if p.y < 8 or p.y >= 32 then drop[#drop + 1] = p end end)
    local function dropped()
        local n = 0
        for _, p in ipairs(drop) do n = n + (items[(p.x + OX) .. "," .. (p.y + OY)] or 0) end
        return n
    end
    local dropBefore = dropped()
    Plan.remove(pl, drop)
    fine, err = pcall(settle, nil)
    lo, hi = spread(pl)
    check(ready and fine and pl.n == 1536 and lo == 1 and hi == 1 and dropped() == dropBefore
        and sum(items) == 1536 + dropBefore and allState(pl, "ok") == 0,
        "重排到一半拿掉 2,560 片：留下的每片剛好一次，拿掉的不再算" .. (fine and "" or " " .. tostring(err)))

    -- 4. 重排到一半又來「全部」（沙盒變了）：從頭來，每片都涵蓋；請求之前已經算過的片再算一次，還在排的不重複
    ready = bigPlan(nil)
    materialsChange()
    for _ = 1, 8 do frame(2) end
    local beforeAll = sum(items)
    DG, T = "pp2", T + PC.SUMMARY_MS
    settle(nil)
    lo, hi = spread(pl)
    check(ready and beforeAll == 8 and lo == 1 and hi == 2 and times(pl, 2) == beforeAll and sum(items) == 4096 + beforeAll
        and allState(pl, "ok") == 0 and not PC.busy(),
        "重排到一半沙盒又變：從頭排，每片都算到（請求前算過的 " .. beforeAll .. " 片再算一次）")
    DG = "pp1"

    -- 4b. 還有待算片時 rev 變了，接著再併進一張「全部」：每片都涵蓋，請求前算過的才算第二次
    ready = bigPlan("63,63")
    materialsChange()
    for _ = 1, 6 do frame(2) end
    Plan.add(pl, 63, 63, 0, 0, 0, Plan.item(pl, "pp_a"))
    for _ = 1, 3 do frame(2) end
    beforeAll = sum(items)
    DG, T = "pp3", T + PC.SUMMARY_MS
    fine, err = pcall(settle, nil)
    lo, hi = spread(pl)
    check(ready and fine and beforeAll == 9 and lo == 1 and hi == 2 and times(pl, 2) == beforeAll
        and sum(items) == 4096 + beforeAll and allState(pl, "ok") == 0 and not PC.busy(),
        "重排中 rev 變了、再併一張「全部」：每片都算到，只有請求前算過的再算一次" .. (fine and "" or " " .. tostring(err)))
    DG = "pp1"

    -- 4c. 重排到一半、佇列還有待算片時藍圖搬走（原點變了：佇列重建）：搬過去的每片剛好一次（舊佇列不留重複），
    --     搬之前算過的不再算
    ready = bigPlan(nil)
    materialsChange()
    for _ = 1, 5 do frame(2) end
    local beforeMove = sum(items)
    OX = 600
    fine, err = pcall(settle, nil)
    lo, hi = spread(pl)
    OX = 500
    check(ready and fine and beforeMove == 5 and lo == 1 and hi == 1 and sum(items) == 4096 + beforeMove and not PC.busy(),
        "重排到一半藍圖搬走：搬過去的每片剛好一次，舊佇列不留重複" .. (fine and "" or " " .. tostring(err)))
    PC.reset()

    -- 5. 請求清掉：藍圖收起 busy() 是 false；換人從頭算、每片一次；reset 後 false
    ready = bigPlan(nil)
    materialsChange()
    frame(2)
    local was = PC.busy()
    local keep = pl
    pl = nil
    local putAway = PC.busy()
    pl = keep
    local back = PC.busy()
    local K2 = player({ id = 92, x = 532.5, y = 532.5 })
    evals, items = {}, {}
    reads, slowAt, T = 0, nil, T + 200
    PC.tick(K2)
    lo, hi = spread(pl)
    local swapped = not PC.busy() and lo == 1 and hi == 1
    PC.reset()
    check(ready and was and not putAway and back and swapped and not PC.busy(),
        "藍圖收起時 busy() 是 false、拿回來接著排；換人從頭算每片一次；reset 後 false")

    -- 6. sweep：done、ok 的片時間到不重查（反面）；BLOCKED 到 STALE_MS 照樣重查；物件數變了連旁邊一起查
    pl = Plan.new("sweep")
    local it = Plan.item(pl, "pp_a")
    for x = 30, 34 do Plan.add(pl, x, 30, 0, 0, 0, it) end
    SHORT, CODE = false, { [(OX + 34) .. "," .. (OY + 30)] = "BLOCKED" }
    sqAt(OX + 30, OY + 30, 0).objs = { tile("pp_a") } -- 蓋好了
    PC.reset()
    frame(nil)
    local function at(x) return (OX + x) .. "," .. (OY + 30) end
    local s30, s31, s34 = PC.state(Plan.at(pl, 30, 30, 0)[1]), PC.state(Plan.at(pl, 31, 30, 0)[1]),
        PC.state(Plan.at(pl, 34, 30, 0)[1])
    evals = {}
    T = T + 60000
    frame(nil)
    check(s30 == "done" and s31 == "ok" and s34 == "blocked" and evals[at(30)] == nil and evals[at(31)] == nil
        and evals[at(32)] == nil and evals[at(34)] == 1,
        "sweep：蓋好、能蓋的片時間到不重查（反面）；放不下的 STALE_MS 到了照樣重查")
    evals = {}
    sqAt(OX + 32, OY + 30, 0).objs = { tile("pp_junk") }
    frame(nil)
    check(evals[at(31)] == 1 and evals[at(32)] == 1 and evals[at(33)] == 1 and evals[at(30)] == nil and evals[at(34)] == nil,
        "sweep：格上物件數變了，那片連四鄰一起重查（隔一格的不查）")
    PC.reset()

    -- 6b. 坡道一片代表整組：每一格斜面都要有那一片、平台格有任何地板才算蓋好；缺片或格子不在都不算
    pl = Plan.new("rampDone")
    local rp = Plan.add(pl, 10, 10, 0, 0, 0, Plan.item(pl, "pp_ramp"))
    SHORT, CODE = false, {}
    local function rampAt(dx, dz) return sqAt(OX + 10 + dx, OY + 10, dz or 0) end
    local function buildRamp(skip, deckFloor)
        for i, name in ipairs({ "pp_ramp", "pp_ramp_1", "pp_ramp_2" }) do
            rampAt(i - 1).objs = skip == i and {} or { tile(name) }
        end
        local deck = rampAt(3, 1)
        deck.objs, deck.floor = {}, deckFloor -- 平台格沒有平台圖、只有任何地板
    end
    local function rampState()
        PC.reset()
        frame(nil)
        return (PC.state(rp))
    end
    buildRamp(nil, true)
    local rFull = rampState()
    buildRamp(2, true)
    local rNoMid = rampState()
    buildRamp(nil, false)
    local rNoDeck = rampState()
    buildRamp(2, false)
    rampAt(2).objs = {}
    local rHeadOnly = rampState()
    buildRamp(nil, true)
    HOLES[(OX + 12) .. "," .. (OY + 10) .. ",0"] = true
    local rHole = rampState()
    HOLES[(OX + 12) .. "," .. (OY + 10) .. ",0"] = nil
    check(rFull == "done" and rNoMid == "ok" and rNoDeck == "ok" and rHeadOnly == "ok" and rHole == "ok",
        "坡道：整組（平台格只有地板）算蓋好；✗ 缺中段、缺平台、只有頭片、有一格不在都不算蓋好")
    ENT.pp_ramp = nil -- 這裡關掉了：項目認不回，世界上的照樣看整組
    buildRamp(2, true)
    local rOffPart = rampState()
    buildRamp(nil, true)
    local rOffFull = rampState()
    ENT.pp_ramp = { kind = "ramp", spr = "pp_ramp" }
    check(rOffFull == "done" and rOffPart ~= nil and rOffPart ~= "done",
        "坡道關掉時：整組照樣算蓋好；✗ 缺中段不算（不退回只看頭片）")
    PC.reset()

    -- 6c. 蓋好的坡道之後中段或平台被拆（頭片那格物件數沒變）：不 reset、只跑 tick，STALE_MS 到了就不再是 done；
    --     沒到之前不重算這一片（✗ 不是每幀整組重算）。坡道放在玩家身邊 NEAR 格內
    pl = Plan.new("rampStale")
    local rq = Plan.add(pl, 30, 30, 0, 0, 0, Plan.item(pl, "pp_ramp"))
    SHORT, CODE = false, {}
    local function nearAt(dx, dz) return sqAt(OX + 30 + dx, OY + 30, dz or 0) end
    local function staleCase(breakIt)
        for i, name in ipairs({ "pp_ramp", "pp_ramp_1", "pp_ramp_2" }) do nearAt(i - 1).objs = { tile(name) } end
        local deck = nearAt(3, 1)
        deck.objs, deck.floor = {}, true
        PC.reset()
        frame(nil)
        local before = PC.state(rq)
        breakIt()
        evals = {}
        frame(nil)
        local early, earlyEvals = PC.state(rq), evals[(OX + 30) .. "," .. (OY + 30)]
        T = T + PC.STALE_MS
        frame(nil)
        return before == "done" and early == "done" and earlyEvals == nil and PC.state(rq) == "ok"
    end
    local midGone = staleCase(function() nearAt(1).objs = {} end)
    local deckGone = staleCase(function() nearAt(3, 1).floor = false end)
    check(midGone and deckGone,
        "坡道蓋好後中段或平台被拆（頭片還在）：STALE_MS 到了就不再是蓋好；沒到之前不重算（✗ 不每幀整組重算）")
    PC.reset()

    -- 6d. 蓋好的車庫門、雙開門之後非錨點那片被拆（錨點那格物件數沒變）：同 6c，不 reset、只跑 tick，
    --     沒到 STALE_MS 不重算、到了就不再是 done
    do
        local GSET = { garage = true, members = { pp_garage = true, pp_garage_2 = true } }
        local DSET = { members = { pp_dbl = true, pp_dbl_2 = true } }
        local fakeDoorSet, realGroupCells, fakeCells = Entry.doorSet, Entry.groupCells, Entry.cells
        ENT.pp_garage = { kind = "door", spr = "pp_garage" }
        ENT.pp_dbl = { kind = "door", spr = "pp_dbl" }
        Entry.doorSet = function(spr) return (spr.name == "pp_garage" and GSET) or (spr.name == "pp_dbl" and DSET) or nil end
        Entry.groupCells = function() return { { 0, 0, 0 }, { 1, 0, 0 } } end -- 車庫門兩格沿 +x
        Entry.cells = function(spr) -- 雙開門（不是車庫門，佔地走 Entry.cells）兩格沿 +y
            if spr.name == "pp_dbl" then return { { 0, 0, 0, spr }, { 0, 1, 0, spr } } end
            return fakeCells(spr)
        end
        local function doorCase(id, other, otherName)
            pl = Plan.new("groupStale")
            local dp = Plan.add(pl, 30, 30, 0, 0, 0, Plan.item(pl, id))
            SHORT, CODE = false, {}
            sqAt(OX + 30, OY + 30, 0).objs = { tile(id) }
            sqAt(OX + 30 + other[1], OY + 30 + other[2], 0).objs = { tile(otherName) }
            PC.reset()
            frame(nil)
            local before = PC.state(dp)
            sqAt(OX + 30 + other[1], OY + 30 + other[2], 0).objs = {}
            evals = {}
            frame(nil)
            local early, earlyEvals = PC.state(dp), evals[(OX + 30) .. "," .. (OY + 30)]
            T = T + PC.STALE_MS
            frame(nil)
            return before == "done" and early == "done" and earlyEvals == nil and PC.state(dp) == "ok"
        end
        local garageGone = doorCase("pp_garage", { 1, 0 }, "pp_garage_2")
        local dblGone = doorCase("pp_dbl", { 0, 1 }, "pp_dbl_2")
        Entry.doorSet, Entry.groupCells, Entry.cells = fakeDoorSet, realGroupCells, fakeCells
        ENT.pp_garage, ENT.pp_dbl = nil, nil
        check(garageGone, "車庫門蓋好後非錨點那片被拆：STALE_MS 到了就不再是蓋好；沒到之前不重算（✗ 不每幀整組重算）")
        check(dblGone, "雙開門蓋好後非錨點那片被拆：STALE_MS 到了就不再是蓋好；沒到之前不重算（✗ 不每幀整組重算）")
        PC.reset()
    end

    -- 6e. sweep 的定時重查只給 RECHECK、BLOCKED 與蓋好的多格組：身邊缺料（NO_MATERIAL）、SAME_TILE 的片過了 STALE_MS
    --     不重查（反面）；同一幀 BLOCKED 的片與蓋好的坡道照樣重查
    do
        pl = Plan.new("stale")
        local si = Plan.item(pl, "pp_a")
        for x = 30, 35 do Plan.add(pl, x, 34, 0, 0, 0, si) end
        Plan.add(pl, 30, 36, 0, 0, 0, Plan.item(pl, "pp_ramp"))
        for i, name in ipairs({ "pp_ramp", "pp_ramp_1", "pp_ramp_2" }) do sqAt(OX + 29 + i, OY + 36, 0).objs = { tile(name) } end
        local deck = sqAt(OX + 33, OY + 36, 1)
        deck.objs, deck.floor = {}, true
        SHORT, CODE = false, { [(OX + 30) .. "," .. (OY + 34)] = "NO_MATERIAL", [(OX + 31) .. "," .. (OY + 34)] = "SAME_TILE",
            [(OX + 32) .. "," .. (OY + 34)] = "BLOCKED", [(OX + 33) .. "," .. (OY + 34)] = "SAFEHOUSE",
            [(OX + 34) .. "," .. (OY + 34)] = "NOT_EMPTY", [(OX + 35) .. "," .. (OY + 34)] = "NO_UPPER" }
        PC.reset()
        frame(nil)
        local s0 = { PC.state(Plan.at(pl, 30, 34, 0)[1]), PC.state(Plan.at(pl, 31, 34, 0)[1]),
            PC.state(Plan.at(pl, 32, 34, 0)[1]), PC.state(Plan.at(pl, 30, 36, 0)[1]) }
        evals = {}
        T = T + PC.STALE_MS
        frame(nil)
        local function ev(x, y) return evals[(OX + x) .. "," .. (OY + y)] end
        check(s0[1] == "short" and s0[2] == "blocked" and s0[3] == "blocked" and s0[4] == "done"
            and ev(30, 34) == nil and ev(31, 34) == nil and ev(32, 34) == 1 and ev(30, 36) == 1,
            "sweep：缺料、SAME_TILE 的片過了 STALE_MS 不重查（反面）；同一幀 BLOCKED 與蓋好的坡道照樣重查")
        -- 審查第 5 輪 R5-3：解除時格上物件數不變、也沒有別的通知的原因（被加進安全屋、舊容器清空、上一層蓋好）
        -- 同 BLOCKED 定時重查；原因解除後變回可蓋
        local wokeOnce = ev(33, 34) == 1 and ev(34, 34) == 1 and ev(35, 34) == 1
        for x = 33, 35 do CODE[(OX + x) .. "," .. (OY + 34)] = nil end
        T = T + PC.STALE_MS
        frame(nil)
        check(wokeOnce and PC.state(Plan.at(pl, 33, 34, 0)[1]) == "ok" and PC.state(Plan.at(pl, 34, 34, 0)[1]) == "ok"
            and PC.state(Plan.at(pl, 35, 34, 0)[1]) == "ok",
            "sweep：SAFEHOUSE、NOT_EMPTY、NO_UPPER 的片過了 STALE_MS 重查；原因解除（格上物件數沒變）後變回可蓋"
                .. "（✗ 一直卡在擋住）")
        SHORT, CODE = false, {}
        PC.reset()
    end

    -- 6f. settled 的邊界：掃描的 ring 是「下一圈、還沒看」，身邊看完時只到 RING（12）圈。重排中（預算一直超過、每幀一片）：
    --     身邊看到第 10 圈時，距離 10 挑得、11 挑不得；身邊看完、清單還沒看完時，距離 12 挑得、13 挑不得
    do
        pl = Plan.new("settled")
        local ti = Plan.item(pl, "pp_a")
        Plan.add(pl, 32, 32, 0, 0, 0, ti) -- 腳下（距離 0）
        Plan.add(pl, 37, 32, 0, 0, 0, ti) -- 距離 5
        for y = 52, 59 do for x = 0, 63 do Plan.add(pl, x, y, 0, 0, 0, ti) end end -- 清單上 512 片、距離 20 以上
        SHORT, CODE = true, {}
        PC.reset()
        frame(nil)
        materialsChange()
        frame(2) -- 身邊看到第 5 圈、算腳下那片（距離 5 那片排著、還沒算）
        local at4, at5 = PC.settled(532 + 4, 532, 0), PC.settled(532 + 5, 532, 0)
        frame(2) -- 看到第 10 圈、算距離 5 那片
        local at10, at11 = PC.settled(532 + 10, 532, 0), PC.settled(532 + 11, 532, 0)
        frame(2) -- 身邊看完、清單看了第一段（遠的那些排進佇列）、算一片遠的
        local at12, at13 = PC.settled(532 + 12, 532, 0), PC.settled(532 + 13, 532, 0)
        local scanning = PC.busy()
        settle(nil)
        check(at4 == true and at5 == false and at10 == true and at11 == false and at12 == true and at13 == false and scanning
            and PC.settled(532 + 13, 532, 0),
            "settled：還排著沒算的那片（距離 5）挑不得；身邊看到第 10 圈時距離 11 挑不得、身邊看完時距離 13 挑不得；掃描完都挑得")
        SHORT = false
        PC.reset()
    end

    -- 6g. touch 叫醒上下一層：下層格變動時重查正上方與上一層四鄰的片（單斜屋頂往上一層接時靠斜下方鄰格撐），
    --     上層格變動時重查正下方與下一層四鄰的片；不在 AROUND 的（上一層隔兩格）不查
    do
        pl = Plan.new("touchZ")
        local zi = Plan.item(pl, "pp_a")
        Plan.add(pl, 40, 40, 1, 0, 0, zi) -- 下層 (40,40,0) 的正上方；也是下層 (40,41,0) 的斜上方
        Plan.add(pl, 42, 40, 1, 0, 0, zi) -- 離 (40,41,0) 隔兩格的上一層
        Plan.add(pl, 45, 40, 0, 0, 0, zi) -- 上層 (45,40,1) 的正下方
        Plan.add(pl, 45, 43, 0, 0, 0, zi) -- 上層 (45,42,1) 的斜下方
        SHORT, CODE = false, {}
        PC.reset()
        frame(nil)
        local function ev(x, y) return evals[(OX + x) .. "," .. (OY + y)] end
        evals = {}
        PC.touch(OX + 40, OY + 40, 0)
        PC.touch(OX + 45, OY + 40, 1)
        frame(nil)
        local straight = ev(40, 40) == 1 and ev(45, 40) == 1 and ev(42, 40) == nil and ev(45, 43) == nil
        evals = {}
        PC.touch(OX + 40, OY + 41, 0)
        PC.touch(OX + 45, OY + 42, 1)
        frame(nil)
        check(straight and ev(40, 40) == 1 and ev(45, 43) == 1 and ev(42, 40) == nil and ev(45, 40) == nil,
            "touch：下層格變動重查正上方與斜上方的片、上層格變動重查正下方與斜下方的片（隔兩格的不查）")
        PC.reset()
    end

    -- 7. Runner 的環境（假的建造佇列、材料箱、動作佇列、玩家狀態）
    local pushes = {}
    Q.push = function(_, id, anchors) pushes[#pushes + 1] = { id = id, anchors = anchors }; return #pushes end
    Q.cancel = function() end
    Q.busy = function() return 0 end
    PS.load = function() return { boxes = {} } end
    MinidoracatUI = { v1 = { Toast = { show = function() end } } }
    Core = { getTileScale = function() return 1 end }
    ISTimedActionQueue = { isPlayerDoingAction = function() return false end, clear = function() end,
        hasAction = function() return false end, add = function() end }
    function K:isAsleep() return false end
    function K:getStats() return { getNumChasingZombies = function() return 0 end } end
    function K:isAttackStarted() return false end
    function K:isAiming() return false end
    function K:isJustMoved() return false end
    function K:getJoypadBind() return -1 end
    getSpecificPlayer = function() return K end
    local function run(n)
        for _ = 1, n do
            T = T + 100
            R.tick()
        end
    end

    -- 7a. 真的 PlanCheck 配 Runner：材料變了、重排還在跑而且算過的片都還缺料時按照圖蓋：開得了（✗ 不回 NOTHING），
    --     挑不到片時等（✗ 不發 LEFT）；重算出能蓋的片就送
    R.stop()
    pl = Plan.new("realRun")
    local fr = Plan.item(pl, "pp_a")
    for x = 0, 63 do for y = 0, 7 do Plan.add(pl, x, y, 0, 0, 0, fr) end end
    SHORT, CODE = true, {}
    PC.reset()
    frame(nil)
    local allShort = allState(pl, "short") == 0
    local realMaterials = PC.materials
    PC.materials = function() return { need = {}, have = {}, tools = {} } end -- Runner 總結用；這裡的假圖沒有成本表
    MG, T = MG + 1, T + PC.SUMMARY_MS -- 摘要變了，但重算的片照樣缺料
    frame(2)
    local okStart, why0 = R.start(K)
    T = T + 1000
    R.tick()
    local waiting, whyWait = R.state(), R.reason()
    SHORT = false -- 之後重算的片能蓋
    for _ = 1, 10 do
        if pushes[1] then break end
        frame(2)
        R.tick()
    end
    local sentReal = pushes[1]
    R.stop()
    PC.materials = realMaterials
    slowAt = nil
    check(allShort and okStart == true and why0 == nil and waiting == "pick" and whyWait == nil and sentReal
        and #sentReal.anchors >= 1,
        "Runner 配真的 PlanCheck：重排中、算過的片都缺料時照圖蓋開得了、挑不到片也等著；重算出能蓋的片就送")
    pushes = {}
    PC.reset()

    -- 照圖蓋開始後一直跑（每幀 PlanCheck 一次、Runner 一次）到送出第一批：回第一片的世界座標 "x,y"
    local function firstSent(slow)
        for _ = 1, 60 do
            if pushes[1] then break end
            frame(slow)
            R.tick()
        end
        local a = pushes[1] and pushes[1].anchors[1]
        return a and (a[1] .. "," .. a[2]) or nil
    end
    local fakeMaterials = function() return { need = {}, have = {}, tools = {} } end
    local realMaterials2 = PC.materials
    PC.materials = fakeMaterials -- Runner 總結用；這裡的假圖沒有成本表
    -- 7c～7d' 玩家站在 64×64 地板的東南角（蛇形起點）：地板照蛇形從離玩家最近的角蓋，腳下那片就是第一片
    K.pos.x, K.pos.y = 563.5, 563.5

    -- 7c. 4,096 片、材料到了之後第 0～3 幀按照圖蓋（預算一直超過、每幀只算一片）：送出的第一片是玩家腳下那片（蛇形起點），
    --     和全部算完才按同一片（✗ 不是清單前段先算出來的遠片）。第 0 幀＝每秒一次的比對還沒看到就按
    local function pressAfter(k)
        R.stop()
        bigPlan(nil)
        pushes = {}
        if k == nil then
            materialsChange()
            settle(nil)
        elseif k == 0 then
            SHORT, MG = false, MG + 1
        else
            materialsChange()
            for _ = 1, k do frame(2) end
        end
        local started = R.start(K)
        local at = firstSent(k ~= nil and 2 or nil)
        R.stop()
        return started == true and at or tostring(started) .. "/" .. tostring(at)
    end
    local nearRef = pressAfter(nil)
    local nearPicks = { pressAfter(0), pressAfter(1), pressAfter(2), pressAfter(3) }
    check(nearRef == "563,563" and nearPicks[1] == nearRef and nearPicks[2] == nearRef and nearPicks[3] == nearRef
        and nearPicks[4] == nearRef,
        "照圖蓋在材料到了之後第 0～3 幀按：第一片是玩家腳下那片，和全部算完才按同一片（" .. table.concat(nearPicks, " ") .. "）")

    -- 7c'. 清單前段（離玩家遠）的片本來就能蓋、身邊的缺料；材料到了同一幀就按，而且 Runner 在 PlanCheck 之前先挑
    --      （OnTick 的先後不保證）：先等身邊的片重算，送出的第一片是腳下那片（✗ 不先挑走舊狀態裡能蓋的遠片）
    R.stop()
    bigPlan(nil)
    SHORT, CODE = false, {}
    Plan.each(pl, function(p) if p.y >= 4 then CODE[(p.x + OX) .. "," .. (p.y + OY)] = "NO_MATERIAL" end end)
    MG, T = MG + 1, T + PC.SUMMARY_MS
    settle(nil)
    local frontOk = allState(pl, "ok") == 4096 - 4 * 64
    pushes, CODE, MG = {}, {}, MG + 1
    local staleStart = R.start(K)
    R.tick()
    local staleAt = firstSent(2)
    R.stop()
    check(frontOk and staleStart == true and staleAt == "563,563",
        "照圖蓋：遠處的片本來就能蓋、身邊的剛拿到料，同一幀按下先等身邊重算，第一片是腳下那片（送了 " .. tostring(staleAt) .. "）")

    -- 7d. 剛拿到料就按照圖蓋（PlanCheck 每秒一次的比對還沒看到）：同一幀、第 1 幀、第 30 幀按都開得了（✗ 不回 NOTHING），
    --     重算完送出蛇形起點（離玩家最近的角）那片；真的沒料（摘要沒變）時照舊回 NOTHING、不在重排
    local function smallPress(k, give)
        R.stop()
        pl = Plan.new("mnGo")
        local mi = Plan.item(pl, "pp_a")
        for x = 30, 31 do for y = 30, 31 do Plan.add(pl, x, y, 0, 0, 0, mi) end end
        SHORT, CODE = true, {}
        PC.reset()
        frame(nil)
        local allShortNow = allState(pl, "short") == 0
        if give then SHORT, MG = false, MG + 1 end
        for _ = 1, k do -- 一幀 16 ms：30 幀還不到每秒一次的比對
            T = T + 16
            reads, slowAt = 0, nil
            PC.tick(K)
        end
        pushes = {}
        local started, why = R.start(K)
        local busyNow = PC.busy()
        local at = started and firstSent(nil)
        R.stop()
        return allShortNow, started, why, busyNow, at
    end
    local mnOk = true
    for _, k in ipairs({ 0, 1, 30 }) do
        local a, started, why, busyNow, at = smallPress(k, true)
        if not (a and started == true and why == nil and busyNow and at == "531,531") then mnOk = false end
    end
    local na, nStarted, nWhy, nBusy = smallPress(1, false)
    check(mnOk, "剛拿到料就按照圖蓋：同一幀、第 1 幀、第 30 幀按都開得了（✗ 不回 NOTHING），重算完送蛇形起點（離玩家最近的角）那片")
    check(na and nStarted == nil and nWhy == "NOTHING" and nBusy == false,
        "沒拿到料時按照圖蓋：照舊回 NOTHING、不在重排（反面）")

    -- 7d'. 4,096 片都能蓋時挑一批（一批蓋完後重挑也是這樣）：一次 R.tick 最多問 PICK_CHUNK 片的狀態，4,096 片分 8 幀看完，
    --      送出的還是腳下那片（✗ 一幀看完整張：E2EPerf11 重量的 bigRun 約 4,000 片能蓋時 Runner 一幀 32 ms）；
    --      按下那一下 PlanCheck 在重排（剛拿到料）時，Runner.start 不逐片問狀態（✗ 全缺料時整張問一遍）
    do
        R.stop()
        bigPlan(nil)
        materialsChange()
        settle(nil)
        local allOk = allState(pl, "ok") == 0
        local realState7 = PC.state
        local asks = 0
        PC.state = function(p)
            asks = asks + 1
            return realState7(p)
        end
        pushes = {}
        local started = R.start(K)
        local ticks, most = 0, 0
        while not pushes[1] and ticks < 20 do
            asks = 0
            R.tick()
            ticks = ticks + 1
            if asks > most then most = asks end
        end
        local a = pushes[1] and pushes[1].anchors[1]
        local at = a and (a[1] .. "," .. a[2])
        R.stop()
        bigPlan(nil)
        SHORT, MG = false, MG + 1
        asks = 0
        local busyStart = R.start(K)
        local startAsks, busyNow = asks, PC.busy()
        R.stop()
        PC.state = realState7
        local chunk = R.PICK_CHUNK or 512 -- 舊版沒有這個常數：照 512 比
        -- 最後一幀另外再問挑到的那一批（挑到的那片＋一批最多 32 片，審查第 5 輪 R5-5）
        check(allOk and started == true and ticks == 8 and most <= chunk + 33 and at == "563,563",
            "照圖蓋挑 4,096 片都能蓋的藍圖：分 8 幀看完、一幀最多問 " .. chunk .. " 片（最後一幀多問挑到的那一批），第一片是腳下那片（"
            .. ticks .. " 幀、一幀最多 " .. most .. " 片、送 " .. tostring(at) .. "）")
        check(busyStart == true and busyNow and startAsks == 0,
            "剛拿到料（PlanCheck 在重排）按照圖蓋：Runner.start 不逐片問狀態（問了 " .. startAsks .. " 片）")
        -- 審查第 5 輪 R5-5：分幀看到一半，腳下那片被別人蓋好了（狀態變 done）：看完不送它，重看一輪、送別片
        R.stop()
        bigPlan(nil)
        materialsChange()
        settle(nil)
        local foot, footAsks = Plan.at(pl, 63, 63, 0)[1], 0
        pushes = {}
        local started2 = R.start(K)
        PC.state = function(p)
            if p == foot then
                footAsks = footAsks + 1
                if footAsks > 1 then return "done" end
            end
            return realState7(p)
        end
        local ticks2, sentFoot = 0, false
        while not pushes[1] and ticks2 < 40 do
            R.tick()
            ticks2 = ticks2 + 1
        end
        for _, a2 in ipairs(pushes[1] and pushes[1].anchors or {}) do
            if a2[1] == 563 and a2[2] == 563 then sentFoot = true end
        end
        R.stop()
        PC.state = realState7
        check(started2 == true and pushes[1] ~= nil and footAsks > 1 and not sentFoot,
            "照圖蓋分幀挑片途中腳下那片變成蓋好：不送它（✗ 照舊狀態再蓋一次、多扣料），重看後送別片（看了 " .. ticks2 .. " 幀）")
        -- 複核：同一批裡不是第一片的那片（蛇形同一排的下一片）在送出前變成蓋好：只丟那一片，腳下那片照送
        R.stop()
        bigPlan(nil)
        materialsChange()
        settle(nil)
        local side, sideAsks = Plan.at(pl, 62, 63, 0)[1], 0
        pushes = {}
        local started3 = R.start(K)
        PC.state = function(p)
            if p == side then
                sideAsks = sideAsks + 1
                if sideAsks > 1 then return "done" end
            end
            return realState7(p)
        end
        local ticks3, sentSide, sentFoot3 = 0, false, false
        while not pushes[1] and ticks3 < 40 do
            R.tick()
            ticks3 = ticks3 + 1
        end
        for _, a3 in ipairs(pushes[1] and pushes[1].anchors or {}) do
            if a3[1] == 562 and a3[2] == 563 then sentSide = true end
            if a3[1] == 563 and a3[2] == 563 then sentFoot3 = true end
        end
        R.stop()
        PC.state = realState7
        check(started3 == true and side ~= nil and sideAsks > 1 and sentFoot3 and not sentSide,
            "照圖蓋同一批裡旁邊那片在送出前變成蓋好：只丟那一片、腳下那片照送（✗ 整批照舊狀態送出）")
    end
    K.pos.x, K.pos.y = 532.5, 532.5
    PC.materials = realMaterials2
    pushes, SHORT, CODE = {}, false, {}
    PC.reset()

    -- 7e. 結束通知的標題寫這張藍圖的片數：全部蓋好（藍圖跟著收起）是「蓋好 N／N」（✗ 不是 0／0）；藍圖改了而暫停
    --     （PlanCheck 還沒同步）照實寫蓋好幾片（✗ 不是 0／N）；剩下蓋不了的（LEFT）照實寫。假伺服器收下就回蓋好
    do
        local realToastT, realGetText, realPush7, realMat7 = B.Messages.toast, getText, Q.push, PC.materials
        PC.materials = fakeMaterials -- Runner 總結用；這裡的假圖沒有成本表
        local titles = {}
        B.Messages.toast = function(_, _, title) titles[#titles + 1] = title end
        getText = function(k, ...)
            local a = { ... }
            return #a > 0 and (k .. ":" .. table.concat(a, "/")) or k
        end
        Q.push = function(_, _, anchors, _, _, opts)
            pushes[#pushes + 1] = { anchors = anchors }
            opts.onDone({ owner = "plan", count = #anchors, placed = #anchors, stopped = false })
            return #pushes
        end
        B.PlanMode.clear = function() pl = nil; PC.reset(); return true end -- 同 PM.clear：收起藍圖、PlanCheck 重來
        sb.MaxCellsPerDrag = 2
        local function runTitle(n, blocked, edit)
            R.stop()
            pl = Plan.new("title")
            local ti = Plan.item(pl, "pp_a")
            SHORT, CODE = false, {}
            for x = 1, n do
                Plan.add(pl, 30 + x, 30, 0, 0, 0, ti)
                if x > n - blocked then CODE[(OX + 30 + x) .. "," .. (OY + 30)] = "BLOCKED" end
            end
            PC.reset()
            settle(nil)
            pushes, titles = {}, {}
            R.start(K)
            for _ = 1, 100 do
                if edit and pushes[1] then
                    Plan.add(pl, 40, 40, 0, 0, 0, ti) -- 藍圖改了：PlanCheck 還沒同步這一幀就看到
                    R.tick()
                    break
                end
                frame(nil)
                R.tick()
                if R.state() == "done" or R.state() == "paused" then break end
            end
            local st7, why7 = R.state(), (R.reason())
            R.stop()
            return st7, why7, titles[1]
        end
        local dState, dWhy, dTitle = runTitle(5, 0, false)
        local eState, eWhy, eTitle = runTitle(5, 0, true)
        local lState, lWhy, lTitle = runTitle(5, 2, false)
        B.Messages.toast, getText, Q.push, B.PlanMode.clear, sb.MaxCellsPerDrag = realToastT, realGetText, realPush7, nil, 8
        PC.materials = realMat7
        SHORT, CODE, pushes = false, {}, {}
        PC.reset()
        check(dState == "done" and dWhy == "DONE" and dTitle == "IGUI_MBLD_Run_Progress:5/5",
            "照圖蓋全部蓋好（藍圖跟著收起）：通知標題是蓋好 5／5（✗ 不是 0／0；收到 " .. tostring(dTitle) .. "）")
        check(eState == "paused" and eWhy == "EDIT" and eTitle == "IGUI_MBLD_Run_Progress:2/6",
            "照圖蓋中藍圖改了而暫停：通知標題照實寫蓋好 2／6（✗ 不是 0／6；收到 " .. tostring(eTitle) .. "）")
        check(lState == "done" and lWhy == "LEFT" and lTitle == "IGUI_MBLD_Run_Progress:3/5",
            "照圖蓋剩下蓋不了的（LEFT）：通知標題蓋好 3／5（收到 " .. tostring(lTitle) .. "）")
    end

    -- 7b. Runner 配假的 PlanCheck：busy() 期間挑不到片不結束、不回 NOTHING；busy() 結束後真的沒有才 LEFT
    local S, BUSY = {}, true
    B.PlanCheck = {
        resolve = function(p) local x = pl.items[p.it]; return x and x.id, p.x + OX, p.y + OY, p.z, p.d, p.o, p.w end,
        state = function(p) local v = S[p]; if type(v) == "table" then return v[1], v[2] end return v end,
        busy = function() return BUSY end,
        touch = function() end,
    }
    R.stop()
    pl = Plan.new("run")
    local a1 = Plan.add(pl, 0, 0, 0, 0, 0, Plan.item(pl, "pp_a"))
    local a2 = Plan.add(pl, 1, 0, 0, 0, 0, Plan.item(pl, "pp_a"))
    S[a1], S[a2] = "short", "short"
    BUSY = false
    local n1, c1 = R.start(K)
    BUSY = true
    local n2 = R.start(K)
    run(10)
    local during, why = R.state(), R.reason()
    S[a2] = "ok" -- 重算完：一片變能蓋
    run(3)
    local sent = pushes[1]
    R.stop()
    check(n1 == nil and c1 == "NOTHING" and n2 == true and during == "pick" and why == nil and sent and #sent.anchors == 1,
        "Runner：沒在重排時回 NOTHING（對照）；重排中 start 不回 NOTHING、挑不到片不結束，重算出能蓋的片就送")
    pushes = {}
    S[a2] = "short"
    BUSY = true
    R.start(K)
    run(5)
    local waited = R.state()
    BUSY = false
    run(5)
    check(waited == "pick" and R.state() == "done" and (R.reason()) == "LEFT" and #pushes == 0,
        "Runner：busy() 期間不發 LEFT（反面），busy() 結束後真的沒有才 LEFT")
    -- busy() 一直是 true：等到 BUSY_MAX_MS 照沒在重排的路徑結束；不到就不結束（反面）
    pushes = {}
    BUSY = true
    R.start(K)
    run(math.floor(R.BUSY_MAX_MS / 100) - 5)
    local before, beforeWhy = R.state(), R.reason()
    run(10)
    check(before == "pick" and beforeWhy == nil, "Runner：busy() 一直是 true，不到 BUSY_MAX_MS 不結束（反面）")
    check(R.state() == "done" and (R.reason()) == "LEFT" and #pushes == 0,
        "Runner：busy() 一直是 true，等滿 BUSY_MAX_MS 照舊路徑結束（LEFT）")
    BUSY = false

    -- 8. 坡道一批一片（伺服器只收一個錨點）；同款地板照一批上限
    sb.MaxCellsPerDrag = 8
    pl = Plan.new("ramp")
    local ri = Plan.item(pl, "pp_ramp")
    S = {}
    for x = 0, 2 do S[Plan.add(pl, x, 0, 0, 0, 0, ri)] = "ok" end
    BUSY = false
    Check.item = function() return nil end
    R.start(K)
    run(1)
    local rampBatch = pushes[1]
    R.stop()
    pushes = {}
    pl = Plan.new("floor")
    local fi = Plan.item(pl, "pp_a")
    S = {}
    for x = 0, 2 do S[Plan.add(pl, x, 5, 0, 0, 0, fi)] = "ok" end
    R.start(K)
    run(1)
    local floorBatch = pushes[1]
    R.stop()
    check(rampBatch and rampBatch.id == "pp_ramp" and #rampBatch.anchors == 1 and floorBatch and #floorBatch.anchors == 3
        and R.SEGMENT.ramp == R.SEGMENT.stairs,
        "Runner：坡道一批只送一組（地板照一批上限 3 片）；坡道和樓梯同一段")

    -- 8b. 地板那一段照蛇形一排一排蓋（從藍圖範圍離玩家最近的角開始，一輪只定一次）：8×4 一樓地板，玩家在西北角外，第一批
    --     32 片是第 0 排 x 由小到大、第 1 排由大到小…；玩家在東南角外從東南角反向走；牆照舊由近到遠；兩種地板交錯時每批
    --     同一種、序號遞增
    do
        local realPush8 = Q.push
        -- 西北角（500,500）起的蛇形序號；fx/fy＝從東／南邊起
        local function snake(x, y, fx, fy)
            local r = fy and (503 - y) or (y - 500)
            local k = fx and (507 - x) or (x - 500)
            if r % 2 == 1 then k = 7 - k end
            return r * 8 + k
        end
        local function order(b, fx, fy)
            local bad = {}
            for i, a in ipairs(b and b.anchors or {}) do
                if snake(a[1], a[2], fx, fy) ~= i - 1 then bad[#bad + 1] = i .. ":" .. a[1] .. "," .. a[2] end
            end
            return b ~= nil and #b.anchors == 32 and #bad == 0, table.concat(bad, " ")
        end
        local function firstBatch(px, py)
            R.stop()
            pl = Plan.new("snake")
            local it = Plan.item(pl, "pp_a")
            S = {}
            for y = 0, 3 do for x = 0, 7 do S[Plan.add(pl, x, y, 0, 0, 0, it)] = "ok" end end
            K.pos.x, K.pos.y = px, py
            pushes = {}
            R.start(K)
            run(1)
            R.stop()
            return pushes[1]
        end
        sb.MaxCellsPerDrag = 32
        local nwOk, nwBad = order(firstBatch(499.5, 499.5), false, false)
        check(nwOk, "照圖蓋地板照蛇形：8×4 地板、玩家在西北角外，第一批 32 片第 0 排 x 由小到大、第 1 排由大到小…（錯在 " .. nwBad .. "）")
        local seOk, seBad = order(firstBatch(508.5, 504.5), true, true)
        check(seOk, "照圖蓋地板照蛇形：玩家在東南角外，從東南角那片起反向一排一排（錯在 " .. seBad .. "）")
        -- 牆：同一排 8 片，玩家站在 x＝505 那格的北邊：由近到遠（✗ 照蛇形從最近的角 507 起）
        ENT.pp_w = { kind = "wall", spr = "pp_w" }
        R.stop()
        pl = Plan.new("snakeWall")
        local wi = Plan.item(pl, "pp_w")
        S = {}
        for x = 0, 7 do S[Plan.add(pl, x, 0, 0, 0, 0, wi)] = "ok" end
        K.pos.x, K.pos.y = 505.5, 499.5
        pushes = {}
        R.start(K)
        run(1)
        R.stop()
        local wb, near, last = pushes[1], true, -1
        for _, a in ipairs(wb and wb.anchors or {}) do
            local d = (a[1] + 0.5 - 505.5) ^ 2 + (a[2] + 0.5 - 499.5) ^ 2
            if d < last then near = false end
            last = d
        end
        check(wb and #wb.anchors == 8 and wb.anchors[1][1] == 505 and near,
            "照圖蓋的牆照舊由近到遠（第一片是玩家旁邊那格，不照地板的蛇形）")
        ENT.pp_w = nil
        -- 兩種地板棋盤格交錯、一批最多 8 片、假伺服器收下就蓋好：4 批，每批同一種、序號遞增，同一種接著上一批往後
        ENT.pp_b = { kind = "floor", spr = "pp_b" }
        sb.MaxCellsPerDrag = 8
        Q.push = function(_, id, anchors, _, _, opts)
            pushes[#pushes + 1] = { id = id, anchors = anchors }
            opts.onDone({ owner = "plan", count = #anchors, placed = #anchors, stopped = false })
            return #pushes
        end
        pl, S = Plan.new("snakeMix"), {}
        local xa, xb = Plan.item(pl, "pp_a"), Plan.item(pl, "pp_b")
        for y = 0, 3 do for x = 0, 7 do S[Plan.add(pl, x, y, 0, 0, 0, (x + y) % 2 == 0 and xa or xb)] = "ok" end end
        pushes = {}
        K.pos.x, K.pos.y = 499.5, 499.5
        R.start(K)
        for _ = 1, 40 do
            if #pushes >= 4 then break end
            run(1)
        end
        R.stop()
        local mixOk, lastOf, ids = #pushes == 4, {}, {}
        for _, b in ipairs(pushes) do
            ids[#ids + 1] = b.id
            local prev = lastOf[b.id] or -1
            for _, a in ipairs(b.anchors) do
                local want = (a[1] + a[2]) % 2 == 0 and "pp_a" or "pp_b"
                local k = snake(a[1], a[2], false, false)
                if want ~= b.id or k <= prev then mixOk = false end
                prev = k
            end
            lastOf[b.id] = prev
            if #b.anchors ~= 8 then mixOk = false end
        end
        check(mixOk and table.concat(ids, " ") == "pp_a pp_b pp_a pp_b",
            "照圖蓋兩種地板交錯：每批同一種、序號遞增（" .. table.concat(ids, " ") .. "）")
        ENT.pp_b, Q.push, sb.MaxCellsPerDrag, pushes = nil, realPush8, 8, {}
        K.pos.x, K.pos.y = 532.5, 532.5
    end

    -- 8c. 地面覆蓋等同格的地板先蓋（審查 1124 Codex）：A（500,500）只有半格、B（501,500）是地板＋同款半格，玩家在西北角外，
    --     蛇形從 A 起。假伺服器照 Server.complete 換地圖地板：蓋地板時那格掛著的覆蓋連帳本一起沒了（不是地毯，見「換地圖
    --     地板（不算替換）」那條）。蓋完 B 的地板、半格與帳本都在（✗ 第一批 A、B 的半格一起送，B 的半格被地板拆掉）。
    --     多格地板（審查 1124 第二輪）：兩格地板 pp_a2 錨點在 501、另一格在 502，半格擺在 502（不是錨點格），玩家在東邊外，
    --     蛇形從 502 起：伺服器逐格換地板，502 的半格要等整組地板蓋好（✗ 只看同格錨點時半格先蓋、被地板拆掉）。
    --     同一格 1 片地板＋n 張半格挑一次批，問片的次數照 n 線性長（✗ 每張半格各自重走同格所有片，n 張是 n² 次）
    do
        local realPush8c, realCells8c, realResolve8c = Q.push, Entry.cells, B.PlanCheck.resolve
        ENT.pp_o = { kind = "floorOverlay", spr = "pp_o" }
        ENT.pp_a2 = { kind = "floor", spr = "pp_a2" }
        Entry.cells = function(spr)
            if spr.name == "pp_a2" then return { { 0, 0, 0, spr }, { 1, 0, 0, spr } } end
            return realCells8c(spr)
        end
        local floorAt, hung = {}, {}
        Q.push = function(_, id, anchors, _, _, opts)
            pushes[#pushes + 1] = { id = id, anchors = anchors }
            for _, a in ipairs(anchors) do
                if ENT[id].kind == "floor" then
                    for _, f in ipairs(Entry.cells(Entry.face(ENT[id], a[4]))) do
                        local key = (a[1] + f[1]) .. "," .. (a[2] + f[2])
                        floorAt[key], hung[key] = id, nil
                    end
                else
                    hung[a[1] .. "," .. a[2]] = id
                end
            end
            opts.onDone({ owner = "plan", count = #anchors, placed = #anchors, stopped = false })
            return #pushes
        end
        sb.MaxCellsPerDrag = 8
        -- 擺好藍圖（{ 項目, x, 狀態（預設 ok） } 都在 y＝0）、玩家站 (px, py)，照圖蓋到停：回各批 "項目@x,y+x,y"
        local function build(name, list, px)
            R.stop()
            pl, S, floorAt, hung = Plan.new(name), {}, {}, {}
            for _, e in ipairs(list) do S[Plan.add(pl, e[2], 0, 0, 0, 0, Plan.item(pl, e[1]))] = e[3] or "ok" end
            K.pos.x, K.pos.y = px, 499.5
            pushes = {}
            R.start(K)
            for _ = 1, 200 do
                if R.state() == "done" then break end
                run(1)
            end
            local seq = {}
            for _, b in ipairs(pushes) do
                local cells = {}
                for _, a in ipairs(b.anchors) do cells[#cells + 1] = a[1] .. "," .. a[2] end
                seq[#seq + 1] = b.id .. "@" .. table.concat(cells, "+")
            end
            return table.concat(seq, " ")
        end
        local seq = build("overlayFirst", { { "pp_o", 0 }, { "pp_a", 1 }, { "pp_o", 1 } }, 499.5)
        check(R.state() == "done" and (R.reason()) == "DONE" and floorAt["501,500"] == "pp_a" and hung["501,500"] == "pp_o"
            and hung["500,500"] == "pp_o",
            "照圖蓋：同格還有地板沒蓋時那格的地面覆蓋不先蓋，蓋完 B 的地板、半格與帳本都在（" .. seq .. "）")
        local seq2 = build("overlayWide", { { "pp_a2", 1 }, { "pp_o", 2 } }, 503.5)
        check(R.state() == "done" and (R.reason()) == "DONE" and floorAt["502,500"] == "pp_a2" and hung["502,500"] == "pp_o",
            "照圖蓋：兩格地板的非錨點格上的半格等整組地板蓋好才蓋，蓋完那格的地板、半格與帳本都在（" .. seq2 .. "）")
        -- 同格地板缺料（沒有材料箱）：半格等著，這一輪結束時總結把它算進缺料（✗ 狀態 ok 沒有原因，結束畫面少一行）
        local seq3 = build("overlayShort", { { "pp_a", 0, "short" }, { "pp_o", 0 } }, 499.5)
        local sum3 = R.summary()
        check(R.state() == "done" and seq3 == "" and sum3.left == 2 and sum3.short.n == 2,
            "照圖蓋：在等同格地板的半格，總結照那片地板沒蓋的原因說（left " .. sum3.left .. "、缺料 " .. sum3.short.n .. "，"
            .. seq3 .. "）")
        -- 樓上那格還沒有格子：半格是 blocked／WAIT（等同格地板），地板缺料時總結一樣算進缺料（✗ fbF-w-new up2Go：WAIT=1、缺料 1）
        local seq3w = build("overlayShortWait", { { "pp_a", 0, "short" }, { "pp_o", 0, { "blocked", "WAIT" } } }, 499.5)
        local sum3w = R.summary()
        check(R.state() == "done" and seq3w == "" and sum3w.left == 2 and sum3w.short.n == 2 and not sum3w.blocked.WAIT,
            "照圖蓋：在等同格地板的半格（WAIT），總結照那片地板沒蓋的原因說（left " .. sum3w.left .. "、缺料 " .. sum3w.short.n
            .. "、WAIT " .. tostring(sum3w.blocked.WAIT) .. "，" .. seq3w .. "）")
        -- 同格地板的種類在沙盒關掉（off）：之後不會蓋，半格照蓋（✗ 一直等）
        local seq4 = build("overlayOff", { { "pp_a", 0, "off" }, { "pp_o", 0 } }, 499.5)
        check(seq4 == "pp_o@500,500" and hung["500,500"] == "pp_o",
            "照圖蓋：同格地板的種類關掉了，半格不等它（" .. seq4 .. "）")
        local asks
        B.PlanCheck.resolve = function(p)
            asks = asks + 1
            return realResolve8c(p)
        end
        -- 同一格同一個項目只能擺一片：n 張半格用 n 個項目；地板最後擺（同格清單裡排在半格後面）
        for i = 1, 40 do ENT["pp_o" .. i] = { kind = "floorOverlay", spr = "pp_o" .. i } end
        local function count(n)
            R.stop()
            pl, S = Plan.new("overlayPile"), {}
            for i = 1, n do S[Plan.add(pl, 0, 0, 0, 0, 0, Plan.item(pl, "pp_o" .. i))] = "ok" end
            S[Plan.add(pl, 0, 0, 0, 0, 0, Plan.item(pl, "pp_a"))] = "ok"
            K.pos.x, K.pos.y, pushes, asks = 499.5, 499.5, {}, 0
            R.start(K)
            for _ = 1, 10 do
                if pushes[1] then break end
                run(1)
            end
            R.stop()
            return pushes[1] and asks or 0
        end
        local a10, a40 = count(10), count(40)
        check(a10 > 0 and a40 > 0 and a40 < 6 * a10, "照圖蓋挑批：同格 1 片地板＋n 張半格，送出第一批前問片次數照 n 線性長"
            .. "（n＝10：" .. a10 .. "，n＝40：" .. a40 .. "）")
        for i = 1, 40 do ENT["pp_o" .. i] = nil end
        ENT.pp_o, ENT.pp_a2, Q.push, Entry.cells, B.PlanCheck.resolve = nil, nil, realPush8c, realCells8c, realResolve8c
        sb.MaxCellsPerDrag, pushes = 8, {}
        K.pos.x, K.pos.y = 532.5, 532.5
    end

    -- 8d. PlanCheck 掃描中按照圖蓋（審查 1124 實機 snScan）：8×4 地板，玩家站在中間，掃描只看完玩家身邊 3×3 格。地板那一段先等
    --     （✗ 先送玩家身邊那幾片，第一批蓋在藍圖中間）；掃描完第一片是蛇形起點角；等滿 WAIT_MS 還沒掃完就照挑身邊的。
    --     蓋到一半材料變了的重排：第 0 排蓋好、玩家在西北角外、只有前兩排算過，下一片（第 1 排東端）就在算過的裡面：
    --     不等（✗ 等到後兩排也算完，每批都多等）
    do
        local near = function(x, y) return x >= 502 and x <= 504 and y >= 500 and y <= 502 end
        local ready
        B.PlanCheck.settled = function(x, y) return ready(x, y) end
        sb.MaxCellsPerDrag = 8
        local function begin(px, py, f, done)
            R.stop()
            pl, S = Plan.new("scanHold"), {}
            local it = Plan.item(pl, "pp_a")
            for y = 0, 3 do for x = 0, 7 do S[Plan.add(pl, x, y, 0, 0, 0, it)] = (done and y == 0) and "done" or "ok" end end
            K.pos.x, K.pos.y, ready, pushes = px, py, f, {}
            R.start(K)
        end
        begin(503.5, 501.5, near)
        run(20)
        local held = #pushes
        ready = function() return true end
        for _ = 1, 20 do
            if pushes[1] then break end
            run(1)
        end
        local a = pushes[1] and pushes[1].anchors[1]
        local corner = a and (a[1] == 500 or a[1] == 507) and (a[2] == 500 or a[2] == 503)
        begin(503.5, 501.5, near)
        run(40)
        local b = pushes[1] and pushes[1].anchors[1]
        local late = b and near(b[1], b[2])
        begin(499.5, 499.5, function(_, y) return y <= 501 end, true)
        run(2)
        local m = pushes[1] and pushes[1].anchors[1]
        local mid = m and m[1] == 507 and m[2] == 501
        -- 掃描已排進佇列、還沒算完（settled 回 true，state 還是 nil）：沒算過的片排在前面也要等（✗ fbF-w-new snScan 第一批 #167）
        begin(503.5, 501.5, function() return true end)
        local far = {}
        for p in pairs(S) do if not near(500 + p.x, 500 + p.y) then far[#far + 1] = p end end
        for _, p in ipairs(far) do S[p] = nil end
        run(20)
        local held2 = #pushes
        for _, p in ipairs(far) do S[p] = "ok" end
        for _ = 1, 20 do
            if pushes[1] then break end
            run(1)
        end
        local c = pushes[1] and pushes[1].anchors[1]
        local corner2 = c and (c[1] == 500 or c[1] == 507) and (c[2] == 500 or c[2] == 503)
        R.stop()
        local function at(v) return v and (v[1] .. "," .. v[2]) or "nil" end
        check(held == 0 and corner and late and mid and held2 == 0 and corner2,
            "照圖蓋在掃描中：地板先等、不挑玩家身邊的片；掃描完從蛇形起點角起；等滿上限照挑身邊的；下一片算過了就不等；"
            .. "沒算過的片排在前面也等（held=" .. held .. " first=" .. at(a) .. " late=" .. at(b) .. " mid=" .. at(m) .. " held2="
            .. held2 .. " first2=" .. at(c) .. "）")
        B.PlanCheck.settled, sb.MaxCellsPerDrag, pushes = nil, 8, {}
        K.pos.x, K.pos.y = 532.5, 532.5
    end

    -- 9. 伺服器限流：照圖蓋照這台客戶端最近一個窗送過的請求數節流（手動送的也算）、被限流時等一下重送、連續被限流才暫停。
    --    假伺服器照 Server 的 rateOk 算（每人一個窗，窗從窗外的第一個請求起算 RATE_WINDOW_MS、含兩端，超過 RATE_MAX
    --    不收），收下的瞬間蓋好；假的 Queue 照真的一樣經過 Client 的送出點記一筆（Client.build 裡的 Client.sent）
    do
        local fh = assert(io.open(MEDIA .. "/server/MinidoracatBuilder/Server.lua", "rb"))
        local w, m = fh:read("*a"):match("local RATE_WINDOW_MS, RATE_MAX = (%d+), (%d+)")
        fh:close()
        local SW, SM = tonumber(w), tonumber(m) -- 假伺服器照 Server.lua 的值算
        local RR, RG = R.RATE_RETRY_MS or 1500, R.RATE_GIVE_UP_MS or 15000
        local CL = B.Client
        check(SW == CL.RATE_WINDOW_MS and SM == CL.RATE_MAX,
            "客戶端的限流常數和 Server.lua 的 RATE_WINDOW_MS、RATE_MAX 一致（伺服器那份客戶端讀不到，兩邊要一起改）")

        local pushFake, realToast, Msg = Q.push, B.Messages.toast, B.Messages
        local srvT0, srvN, sentAt, forced, toasts = nil, 0, {}, 0, 0
        Q.push = function(_, _, anchors, _, _, opts)
            if CL.sent then CL.sent() end
            local ok
            if not srvT0 or T - srvT0 > SW then
                srvT0, srvN, ok = T, 1, true
            else
                srvN = srvN + 1
                ok = srvN <= SM
            end
            if forced > 0 then forced, ok = forced - 1, false end
            sentAt[#sentAt + 1] = { t = T, x = anchors[1][1], ok = ok }
            if not ok then
                opts.onDone({ owner = "plan", count = #anchors, placed = 0, refused = "RATE_LIMITED", stopped = true })
                return nil, "RATE_LIMITED"
            end
            opts.onDone({ owner = "plan", count = #anchors, placed = #anchors, stopped = false })
            return #sentAt
        end
        Msg.toast = function() toasts = toasts + 1 end
        local function fresh(name, n, f)
            R.stop()
            pl = Plan.new(name)
            local qi = Plan.item(pl, "pp_a")
            S = {}
            for x = 0, n - 1 do S[Plan.add(pl, x, 20, 0, 0, 0, qi)] = "ok" end
            BUSY = false
            T = T + SW + 1000 -- 前面的請求都出了窗
            srvT0, srvN, sentAt, forced, toasts = nil, 0, {}, f, 0
            return R.start(K)
        end
        sb.MaxCellsPerDrag = 1 -- 一片一個請求

        -- 9a. 60 片、瞬間蓋好、每 0.1 秒挑一次：從頭蓋到完，中間不暫停、沒被限流，任一個窗送的請求不超過上限減 2
        local started = fresh("rate60", 60, 0)
        local t0, paused = T, false
        for _ = 1, 600 do
            run(1)
            if R.state() == "paused" then paused = true end
            if R.state() == "done" then break end
        end
        local okN, refusedN, worst = 0, 0, 0
        for i, a in ipairs(sentAt) do
            if a.ok then okN = okN + 1 else refusedN = refusedN + 1 end
            local n = 0
            for j = i, #sentAt do
                if sentAt[j].t - a.t <= SW then n = n + 1 end
            end
            if n > worst then worst = n end
        end
        check(started == true and not paused and R.state() == "done" and (R.reason()) ~= "REFUSED" and okN == 60
            and refusedN == 0 and worst == SM - 2,
            "照圖蓋 60 片（瞬間蓋好）：從頭蓋到完不暫停、沒被限流，一個窗最多送 " .. worst .. " 個（上限 "
            .. SM .. "，留 2 個），花 " .. (T - t0) .. " ms")

        -- 9b. 伺服器回一次 RATE_LIMITED（玩家同時手動送的也算在額度裡）：不暫停、不通知，等 RATE_RETRY_MS 重送同一片，收下
        fresh("rate1", 3, 1)
        run(1)
        local afterRefuse, toastsNow = R.state(), toasts
        run(math.floor(RR / 100) - 2)
        local beforeRetry = #sentAt
        run(5)
        local s1, s2 = sentAt[1], sentAt[2]
        check(s1 and not s1.ok and afterRefuse == "pick" and toastsNow == 0 and beforeRetry == 1 and s2 and s2.ok
            and s2.x == s1.x and s2.t - s1.t >= RR and R.state() ~= "paused" and toasts == 0,
            "照圖蓋被限流一次：不暫停、不通知，等一下重送同一片、收下（✗ 不整批暫停）")

        -- 9c. 一直被限流：RATE_GIVE_UP_MS 之前照樣等著重送、不通知；到了才暫停，原因是伺服器拒絕整批（RATE_LIMITED）
        fresh("rateAll", 3, 1e9)
        run(math.floor(RG / 100) - 5)
        local midState, midWhy, midToasts, midSent = R.state(), R.reason(), toasts, #sentAt
        local realRefusal, refusalCode = Msg.refusal, nil
        Msg.refusal = function(code, ...) refusalCode = code; return realRefusal(code, ...) end
        run(30)
        local endWhy, endText = R.reason()
        Msg.refusal = realRefusal
        check(midState == "pick" and midWhy == nil and midToasts == 0 and midSent >= 5 and R.state() == "paused"
            and endWhy == "REFUSED" and type(endText) == "string" and refusalCode == "RATE_LIMITED" and toasts == 1,
            "照圖蓋一直被限流：" .. RG .. " ms 之前等著重送（送了 " .. midSent .. " 次）、不通知；到了才暫停並說原因")
        R.stop()

        -- 9d. 玩家手動送的建造、拆除也算在額度裡（多人連線時伺服器限流是不回覆，不能等被拒才知道）：同一個窗裡手動送了
        --     8 個建造、2 個拆除之後，照圖蓋只再送到上限減 2（再送 8 個）；出了窗才繼續，也不暫停
        fresh("rateMix", 20, 0)
        local realIsClient, realSend = isClient, sendClientCommand
        isClient = function() return true end
        sendClientCommand = function() end
        for i = 1, 8 do CL.build(K, "pp_a", { { OX + i, OY + 40, 0, 0 } }) end
        for i = 1, 2 do
            CL.dismantleMany(K, { { x = OX + i, y = OY + 41, z = 0, name = "pp_a", kind = "wall", north = true, own = {},
                route = "builder" } })
        end
        isClient, sendClientCommand = realIsClient, realSend
        local manual = CL.recentSends and CL.recentSends(T)
        CL.pending, CL.pendingUnbuild = nil, nil -- 玩家的請求都做完了（不然照圖蓋算玩家動手、暫停）
        run(30) -- 3 秒，手動送的那 10 個都還在窗裡
        local inWindow = #sentAt
        run(30) -- 手動送的出了窗
        check(manual == 10 and inWindow == SM - 2 - 10 and #sentAt > inWindow and R.state() ~= "paused",
            "手動送了 8 個建造、2 個拆除之後，照圖蓋同一個窗裡只再送 " .. inWindow .. " 個（上限減 2 共 "
            .. (SM - 2) .. "）；出了窗才繼續、不暫停")
        R.stop()
        Q.push, Msg.toast, sb.MaxCellsPerDrag = pushFake, realToast, 8
        pushes = {}
    end

    B.PlanMode, B.PlanCheck, B.Recipes = real.PM, real.PC, real.rec
    getCell, getTimestampMs, instanceof, getSpecificPlayer = real.cell, real.clock, real.inst, real.specific
    Check.item, Materials.summary, Materials.same = real.item, real.summary, real.same
    Entry.resolve, Entry.face, Entry.alternate, Entry.cells, Entry.doorSet, Entry.why, Entry.digest =
        real.resolve, real.face, real.alt, real.cells, real.doorSet, real.why, real.digest
    Entry.rampSet, Entry.sprite = real.rampSet, real.sprite
    Q.push, Q.cancel, Q.busy, PS.load = real.push, real.cancel, real.busy, real.load
    MinidoracatUI, Core, ISTimedActionQueue, sb.MaxCellsPerDrag = real.ui, real.core, real.q, real.max
end)()

-- ===== 快選列、匯入框、記錄（HotbarImport） =====
;(function()
